import { LogoError } from './errors';

export type TokenType =
  | 'number'
  | 'word'
  | 'param' // legacy :name
  | 'string'
  | 'lbracket'
  | 'rbracket'
  | 'lparen'
  | 'rparen'
  | 'comma'
  | 'op' // + - * /
  | 'cmp'; // < > = <= >= <>

export interface Token {
  type: TokenType;
  /** Source text of the token. */
  text: string;
  /** Case-folded text for words and :params (without the colon). */
  key: string;
  value: number;
  line: number;
  column: number;
  offset: number;
  /** Whitespace (or start of source) immediately before the token. */
  spaceBefore: boolean;
  /** Whitespace (or end of source) immediately after the token. */
  spaceAfter: boolean;
  /** First token on its source line. */
  lineStart: boolean;
  /** Last token on its source line. */
  lineEnd: boolean;
}

export const MAX_SOURCE = 50_000;
export const MAX_TOKENS = 10_000;

const isLetter = (c: string) => /[\p{L}_]/u.test(c);
const isWordChar = (c: string) => /[\p{L}\p{N}_]/u.test(c);
const isDigit = (c: string) => c >= '0' && c <= '9';
const isSpace = (c: string) => c === ' ' || c === '\t' || c === '\n' || c === '\r' || c === '\f' || c === '\v' || c === ' ';

export function fold(text: string): string {
  return text.toLocaleLowerCase('pl').normalize('NFC');
}

export function tokenize(src: string): Token[] {
  const source = src.normalize('NFC');
  // Line/column bookkeeping.
  let line = 1;
  let col = 1;
  let i = 0;
  const posOf = (offset: number) => {
    let l = 1;
    let c = 1;
    for (let k = 0; k < offset; k++) {
      if (source[k] === '\n') {
        l++;
        c = 1;
      } else c++;
    }
    return { line: l, column: c };
  };
  if (source.length > MAX_SOURCE) {
    const p = posOf(MAX_SOURCE);
    throw new LogoError(`Program jest za długi: więcej niż ${fmt(MAX_SOURCE)} znaków.`, p.line, p.column);
  }

  const tokens: Token[] = [];
  let sawSpace = true;
  let lineHasToken = false;

  const advance = (n: number) => {
    for (let k = 0; k < n; k++) {
      if (source[i] === '\n') {
        line++;
        col = 1;
      } else col++;
      i++;
    }
  };

  const push = (type: TokenType, text: string, key: string, value = 0) => {
    const prev = tokens[tokens.length - 1];
    if (prev) prev.spaceAfter = sawSpace;
    if (tokens.length >= MAX_TOKENS) {
      throw new LogoError(`Program ma za dużo elementów: więcej niż ${fmt(MAX_TOKENS)}.`, line, col);
    }
    tokens.push({
      type,
      text,
      key,
      value,
      line,
      column: col,
      offset: i,
      spaceBefore: sawSpace,
      spaceAfter: true,
      lineStart: !lineHasToken,
      lineEnd: true,
    });
    if (prev && lineHasToken) prev.lineEnd = false;
    lineHasToken = true;
    sawSpace = false;
    advance(text.length);
  };

  while (i < source.length) {
    const c = source[i];
    if (isSpace(c)) {
      if (c === '\n') lineHasToken = false;
      sawSpace = true;
      advance(1);
      continue;
    }
    if (c === ';') {
      while (i < source.length && source[i] !== '\n') advance(1);
      sawSpace = true;
      continue;
    }
    if (isDigit(c) || (c === '.' && isDigit(source[i + 1] ?? ''))) {
      let j = i;
      while (j < source.length && isDigit(source[j])) j++;
      if (source[j] === '.') {
        j++;
        const fracStart = j;
        while (j < source.length && isDigit(source[j])) j++;
        if (j === fracStart) {
          throw new LogoError(`Niepoprawna liczba „${source.slice(i, j)}”: po kropce muszą być cyfry.`, line, col);
        }
      }
