import { at } from './errors';
import type { Expr, Program, Stmt } from './ast';
import { KEYWORDS } from './keywords';
import type { Token } from './lexer';

export type Mode = '2d' | '3d';

export function parse(tokens: Token[], mode: Mode): Program {
  return new Parser(tokens, mode).program();
}

class Parser {
  i = 0;
  constructor(
    private toks: Token[],
    private mode: Mode,
  ) {}

  peek(): Token | undefined {
    return this.toks[this.i];
  }

  program(): Program {
    const main: Stmt[] = [];
    while (this.peek()) main.push(this.statement());
    return { main };
  }

  statement(): Stmt {
    const tok = this.toks[this.i++];
    const id = tok.type === 'word' ? KEYWORDS.get(tok.key) : undefined;
    switch (id) {
      case 'fd':
      case 'bk':
        return { kind: 'move', sign: id === 'fd' ? 1 : -1, arg: this.expr(), tok };
      case 'rt':
      case 'lt':
        return { kind: 'turn', axis: 'yaw', sign: id === 'rt' ? 1 : -1, arg: this.expr(), tok };
      case 'repeat': {
        const count = this.expr();
        const open = this.toks[this.i++];
        const body: Stmt[] = [];
        while (this.peek() && this.peek()!.type !== 'rbracket') body.push(this.statement());
        const close = this.toks[this.i++];
        void open;
        return { kind: 'repeat', count, body, tok, close };
      }
    }
    throw at(`Nieznane polecenie „${tok.text}”.`, tok);
  }

  expr(): Expr {
    const tok = this.toks[this.i++];
    return { kind: 'num', value: tok.value, first: tok };
  }
}
