export type Vec = [number, number, number];

const RAD = Math.PI / 180;

/** Sine and cosine of an angle in degrees, exact at multiples of 30°. */
export function sincos(deg: number): [number, number] {
  const a = ((deg % 360) + 360) % 360;
  const exact: Record<number, [number, number]> = {
    0: [0, 1],
    30: [0.5, Math.sqrt(3) / 2],
    90: [1, 0],
    150: [0.5, -Math.sqrt(3) / 2],
    180: [0, -1],
    210: [-0.5, -Math.sqrt(3) / 2],
    270: [-1, 0],
    330: [-0.5, Math.sqrt(3) / 2],
  };
  if (exact[a]) return exact[a];
  if (a === 60) return [Math.sqrt(3) / 2, 0.5];
  if (a === 120) return [Math.sqrt(3) / 2, -0.5];
  if (a === 240) return [-Math.sqrt(3) / 2, -0.5];
  if (a === 300) return [-Math.sqrt(3) / 2, 0.5];
  return [Math.sin(a * RAD), Math.cos(a * RAD)];
}

export const cross = (a: Vec, b: Vec): Vec => [
  a[1] * b[2] - a[2] * b[1],
  a[2] * b[0] - a[0] * b[2],
  a[0] * b[1] - a[1] * b[0],
];

/** Rotate unit vector `a` towards unit vector `b` (orthogonal to it) by `deg`; returns [a', b']. */
export function rotatePair(a: Vec, b: Vec, deg: number): [Vec, Vec] {
  const [s, c] = sincos(deg);
  return [
    [a[0] * c + b[0] * s, a[1] * c + b[1] * s, a[2] * c + b[2] * s],
    [b[0] * c - a[0] * s, b[1] * c - a[1] * s, b[2] * c - a[2] * s],
  ];
}

export class Turtle {
  pos: Vec = [0, 0, 0];
  heading: Vec = [0, 1, 0];
  up: Vec = [0, 0, 1];
  penDown = true;
  color = '#16866a';
  width = 3;

  get right(): Vec {
    return cross(this.heading, this.up);
  }
}
