    ]);
  });

  test('calls may precede definitions; arguments are expressions; legacy header works', () => {
    expect(lastTo('kwadrat 40 * 2 90\nTO kwadrat :bok :kąt\n np :bok pw kąt np bok\nEND')).toEqual([80, 80, 0]);
  });

  test('a parameter may share its name with a procedure', () => {
    expect(lastTo('oto a ma: a\n np a\njuż\na 7')).toEqual([0, 7, 0]);
  });

  test('niech inside a procedure is local and shadows the global for the rest of the call', () => {
    const r = run('niech x 1\noto p\n np x\n niech x 5\n np x\njuż\np\nnp x', '2d');
