    expect(lastTo('kwadrat 40 * 2 90\nTO kwadrat :bok :kąt\n np :bok pw kąt np bok\nEND')).toEqual([80, 80, 0]);
  });

  test('a parameter may share its name with a procedure', () => {
    expect(lastTo('oto a ma: a\n np a\njuż\na 7')).toEqual([0, 7, 0]);
  });

  test('niech inside a procedure is local and shadows the global for the rest of the call', () => {
    const r = run('niech x 1\noto p\n np x\n niech x 5\n np x\njuż\np\nnp x', '2d');
    expect(r.error).toBeNull();
    expect(r.segments.map((s) => s.to[1])).toEqual([1, 6, 7]);
  });

  test('parameters can be reassigned and used as repeat counts', () => {
    expect(lastTo('oto p ma: n\n niech n n + 1\n powtorz n [np 1]\njuż\np 2')).toEqual([0, 3, 0]);
  });

  test('stop ends the current call, even from inside a repeat; at top level it ends the program', () => {
    expect(lastTo('oto s ma: n\n jeśli n < 1 [stop]\n np n\n s n - 1\njuż\ns 3')).toEqual([0, 6, 0]);
    expect(lastTo('oto p\n powtorz 10 [np 1 jeśli nrpowt = 3 [stop]]\n np 100\njuż\np np 1')).toEqual([0, 4, 0]);
