  });

  test('reading a local before it is assigned, with no global, is a run-time error', () => {
    const r = run('np 10\noto p\n np q\n niech q 1\njuż\np', '2d');
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 3, column: 5 });
  });

  test.each([
    ['kwadrat 80\noto kwadrat ma: a, b\njuż', 1, 1],
    ['oto k ma: a, b\njuż\nk 80\nnp 5', 4, 1],
    ['oto k ma: a\njuż\nk 1 2', 3, 5],
    ['powtorz 2 [\noto x\njuż\n]', 2, 1],
    ['oto x\nnp 10', 1, 1],
    ['oto x\noto y\njuż\njuż', 2, 1],
    ['oto x\njuż\noto x\njuż', 3, 5],
    ['np 1 oto x\njuż', 1, 6],
    ['oto np\njuż', 1, 5],
    ['oto a\n np q\njuż\noto b\n niech q 1\njuż', 2, 5],
    ['oto a\n np nrpowt\njuż\npowtorz 2 [a]', 2, 5],
    ['oto a\njuż\nniech a 5', 3, 7],
    ['już', 1, 1],
    ['oto p ma: a, a\njuż', 1, 14],
