import type { CmpOp, Cond, Expr, Procedure, Program, Stmt } from './ast';
import { checkRepeat, checkWidth } from './checks';
import { LogoError, at } from './errors';
import { KEYWORDS, RESERVED } from './keywords';
import type { Token } from './lexer';

export type Mode = '2d' | '3d';

const MAX_PARENS = 256;
export const MAX_BRACKETS = 32;
const REPCOUNT = new Set(['nrpowt', 'repcount']);
const DEFINE = new Set(['oto', 'to']);
const END = new Set(['już', 'juz', 'end']);

const isName = (t: Token | undefined): t is Token => !!t && (t.type === 'word' || t.type === 'param');
const isLet = (t: Token) => t.type === 'word' && KEYWORDS.get(t.key) === 'let';

interface ProcHeader {
  proc: Procedure;
  body: Token[];
  end: Token;
}

/** Validate a whole program and build its syntax tree. Throws LogoError on the first problem. */
export function parse(tokens: Token[], mode: Mode): Program {
  const { headers, main } = scanDefinitions(tokens);
  const procs = new Map<string, Procedure>(headers.map((h) => [h.proc.name, h.proc]));

  // Names assigned by `niech` anywhere at top level are global variables.
  const globals = new Set<string>();
  for (let k = 0; k + 1 < main.length; k++) {
    if (isLet(main[k]) && isName(main[k + 1])) globals.add(main[k + 1].key);
  }

  // Parse every unit; report the earliest error in the source.
  const errors: LogoError[] = [];
  const attempt = (f: () => void) => {
    try {
      f();
    } catch (e) {
      if (e instanceof LogoError) errors.push(e);
      else throw e;
    }
  };
  let body: Stmt[] = [];
  attempt(() => {
    body = new Parser(main, mode, procs, globals, null, undefined).program();
  });
  for (const h of headers) {
    attempt(() => {
      const locals = new Set(h.proc.params);
      for (let k = 0; k + 1 < h.body.length; k++) {
        if (isLet(h.body[k]) && isName(h.body[k + 1])) locals.add(h.body[k + 1].key);
      }
      h.proc.body = new Parser(h.body, mode, procs, globals, locals, h.end).program();
    });
  }
  if (errors.length) {
    errors.sort((a, b) => a.line - b.line || a.column - b.column);
    throw errors[0];
  }
  return { main: body, procs };
}

/** Find `oto … już` definitions; returns their headers and the remaining top-level tokens. */
function scanDefinitions(tokens: Token[]): { headers: ProcHeader[]; main: Token[] } {
  const headers: ProcHeader[] = [];
  const main: Token[] = [];
  let depth = 0;
  let i = 0;
  while (i < tokens.length) {
    const t = tokens[i];
    if (t.type === 'word' && END.has(t.key)) {
      throw at(`„${t.text}” kończy definicję procedury, ale żadna nie została rozpoczęta słowem „oto”.`, t);
    }
    if (!(t.type === 'word' && DEFINE.has(t.key))) {
      if (t.type === 'lbracket') depth++;
      if (t.type === 'rbracket') depth--;
      main.push(t);
      i++;
      continue;
    }
    if (depth > 0) throw at('Procedurę można zdefiniować tylko poza nawiasami [ ].', t);
    if (!t.lineStart) throw at(`Definicja procedury „${t.text}” musi zaczynać się na początku linii.`, t);
    // Header: name and parameters on the same line.
    const name = tokens[i + 1];
    if (!name || name.line !== t.line) throw at(`Po „${t.text}” podaj nazwę procedury.`, t);
    if (name.type !== 'word') throw at(`Niepoprawna nazwa procedury „${name.text}”.`, name);
    if (RESERVED.has(name.key)) throw at(`„${name.text}” to słowo języka i nie może być nazwą procedury.`, name);
    if (headers.some((h) => h.proc.name === name.key)) {
      throw at(`Procedura „${name.text}” jest już zdefiniowana. Każdą nazwę można zdefiniować raz.`, name);
    }
    const params: string[] = [];
    const addParam = (p: Token) => {
      if (RESERVED.has(p.key)) throw at(`„${p.text}” to słowo języka i nie może być nazwą parametru.`, p);
      if (params.includes(p.key)) throw at(`Parametr „${p.text}” występuje dwa razy.`, p);
      params.push(p.key);
    };
    let j = i + 2;
    const onLine = () => tokens[j] && tokens[j].line === t.line;
    if (onLine() && tokens[j].type === 'word' && tokens[j].key === 'ma:') {
      j++;
      for (;;) {
        const p = tokens[j];
        if (!onLine() || p.type !== 'word') {
          throw at('Po „ma:” podaj nazwy parametrów oddzielone przecinkami, np. ma: bok, kąt.', onLine() ? p : tokens[j - 1]);
        }
        addParam(p);
        j++;
        if (onLine() && tokens[j].type === 'comma') j++;
        else break;
      }
    } else {
      while (onLine() && tokens[j].type === 'param') addParam(tokens[j++]);
    }
    if (onLine()) {
      throw at(`Nieoczekiwane „${tokens[j].text}” w nagłówku procedury. Parametry zapisz po „ma:”.`, tokens[j]);
    }
    // Body: up to `już` alone on its line.
    const body: Token[] = [];
    let end: Token | undefined;
    for (; j < tokens.length; j++) {
      const b = tokens[j];
      if (b.type === 'word' && DEFINE.has(b.key)) {
        throw at('Nie można definiować procedury wewnątrz innej procedury. Zakończ poprzednią słowem „już”.', b);
      }
      if (b.type === 'word' && END.has(b.key)) {
        if (!b.lineStart || !b.lineEnd) throw at(`„${b.text}” musi stać sam w osobnej linii.`, b);
        end = b;
        break;
      }
      body.push(b);
    }
    if (!end) throw at(`Brak „już” kończącego procedurę „${name.text}”.`, t);
    headers.push({ proc: { name: name.key, display: name.text, params, body: [], tok: name }, body, end });
    i = j + 1;
  }
  return { headers, main };
}

class Parser {
  i = 0;
  parenDepth = 0;
  bracketDepth = 0;
  repeatDepth = 0;

  constructor(
    private toks: Token[],
    private mode: Mode,
    private procs: Map<string, Procedure>,
    private globals: Set<string>,
    /** Parameters and `niech` names of the enclosing procedure, or null at top level. */
    private locals: Set<string> | null,
    /** The token that ends this unit (`już`), used to report a missing argument. */
    private endTok: Token | undefined,
  ) {}

  peek(): Token | undefined {
    return this.toks[this.i];
  }

  program(): Stmt[] {
    const out: Stmt[] = [];
    while (this.peek()) out.push(this.statement());
    return out;
  }

  statement(): Stmt {
    const tok = this.toks[this.i++];
    const id = tok.type === 'word' ? KEYWORDS.get(tok.key) : undefined;
    switch (id) {
      case 'fd':
      case 'bk':
        return { kind: 'move', sign: id === 'fd' ? 1 : -1, arg: this.expr(tok), tok };
      case 'rt':
      case 'lt':
        return { kind: 'turn', axis: 'yaw', sign: id === 'rt' ? 1 : -1, arg: this.expr(tok), tok };
      case 'up':
      case 'down':
      case 'rollr':
      case 'rolll':
        if (this.mode === '2d') {
          throw at(`Polecenie „${tok.text}” działa tylko w trybie 3D. Przełącz tryb na 3D albo usuń je.`, tok);
        }
        return {
          kind: 'turn',
          axis: id === 'up' || id === 'down' ? 'pitch' : 'roll',
          sign: id === 'up' || id === 'rollr' ? 1 : -1,
          arg: this.expr(tok),
          tok,
        };
      case 'pu':
      case 'pd':
        return { kind: 'pen', down: id === 'pd', tok };
      case 'color': {
        const c = this.peek();
        if (!c) throw at('Polecenie „kolor” potrzebuje koloru, np. kolor "#16866a".', this.endTok ?? tok);
        if (c.type !== 'string' || !/^#[0-9a-f]{6}$/i.test(c.key)) {
          throw at(
            `Niepoprawny kolor ${c.type === 'string' ? c.text : `„${c.text}”`}. Zapisz go jako sześć cyfr szesnastkowych w cudzysłowie, np. "#16866a".`,
            c,
          );
        }
        this.i++;
        return { kind: 'color', color: c.key.toLowerCase(), tok };
      }
      case 'width': {
        const arg = this.expr(tok);
        this.checkLiteral(arg, checkWidth);
        return { kind: 'width', arg, tok };
      }
      case 'let': {
        const name = this.peek();
        if (!name) {
          throw at('Polecenie „niech” potrzebuje nazwy zmiennej i wartości, np. niech bok 50.', this.endTok ?? tok);
        }
        if (!isName(name)) throw at(`Po „niech” oczekiwano nazwy zmiennej, a znaleziono „${name.text}”.`, name);
        if (RESERVED.has(name.key)) {
          throw at(`„${name.text}” to słowo języka i nie może być nazwą zmiennej.`, name);
        }
        if (this.procs.has(name.key)) {
          throw at(`„${name.text}” to nazwa procedury i nie może być nazwą zmiennej.`, name);
        }
        this.i++;
        return { kind: 'let', name: name.key, arg: this.expr(tok), tok };
      }
      case 'if':
      case 'ifelse': {
        const cond = this.condition(tok);
        const [then, closeThen] = this.body(tok);
        if (id === 'if') return { kind: 'if', cond, then, else: null, tok, closeThen, closeElse: null };
        const [otherwise, closeElse] = this.body(tok);
        return { kind: 'if', cond, then, else: otherwise, tok, closeThen, closeElse };
      }
      case 'repeat': {
        const count = this.expr(tok);
        this.checkLiteral(count, checkRepeat);
        this.repeatDepth++;
        const [body, close] = this.body(tok);
        this.repeatDepth--;
        return { kind: 'repeat', count, body, tok, close };
      }
      case 'stop':
        return { kind: 'stop', tok };
      case 'home':
        return { kind: 'home', tok };
      case 'clear':
        return { kind: 'clear', tok };
    }
    if (tok.type === 'word') {
      const proc = this.procs.get(tok.key);
      if (proc) {
        const args = proc.params.map((_, k) => this.expr(tok, proc, k));
        return { kind: 'call', proc, args, tok };
      }
    }
    if (tok.type === 'rbracket') throw at('Nawias „]” bez pasującego nawiasu „[”.', tok);
    if (tok.type === 'rparen') throw at('Nawias „)” bez pasującego nawiasu „(”.', tok);
    if (tok.type === 'lbracket') throw at('Nawias „[” może stać tylko po „powtórz”, „jeśli” albo „jeżeli”.', tok);
    if (tok.type === 'word' && REPCOUNT.has(tok.key)) {
      throw at(`„${tok.text}” to wartość, a nie polecenie. Użyj go jako argumentu, np. np ${tok.text}.`, tok);
    }
    if (isName(tok) && this.knows(tok.key)) {
      throw at(`Oczekiwano polecenia, a znaleziono wartość „${tok.text}”.`, tok);
    }
    if (tok.type === 'word' && (DEFINE.has(tok.key) || END.has(tok.key))) {
      throw at(`„${tok.text}” może stać tylko na początku osobnej linii, poza innymi poleceniami.`, tok);
    }
    if (tok.type === 'word') throw at(`Nieznane polecenie „${tok.text}”.`, tok);
    throw at(`Oczekiwano polecenia, a znaleziono „${tok.text}”.`, tok);
  }

  knows(key: string): boolean {
    return !!this.locals?.has(key) || this.globals.has(key);
  }

  condition(owner: Token): Cond {
    const left = this.expr(owner);
    const op = this.peek();
    if (!op || op.type !== 'cmp') {
      throw at(
        `Po „${owner.text}” oczekiwano warunku z porównaniem (<, >, =, <=, >=, <>)${op ? `, a znaleziono „${op.text}”` : ''}.`,
        op ?? this.endTok ?? owner,
      );
    }
    this.i++;
    return { left, op: op.text as CmpOp, right: this.expr(owner) };
  }

  /** Parse `[ statements ]`; returns the statements and the closing bracket. */
  body(owner: Token): [Stmt[], Token] {
    const open = this.peek();
    if (!open || open.type !== 'lbracket') {
      throw at(
        `Po „${owner.text}” oczekiwano nawiasu „[” z poleceniami${open ? `, a znaleziono „${open.text}”` : ''}.`,
        open ?? this.endTok ?? owner,
      );
    }
    this.i++;
    if (++this.bracketDepth > MAX_BRACKETS) {
      throw at(`Za głębokie zagnieżdżenie nawiasów: najwyżej ${MAX_BRACKETS} poziomy.`, open);
    }
    const stmts: Stmt[] = [];
    for (;;) {
      const t = this.peek();
      if (!t) throw at('Brak nawiasu zamykającego „]” do tego nawiasu.', open);
      if (t.type === 'rbracket') {
        this.i++;
        this.bracketDepth--;
        return [stmts, t];
      }
      stmts.push(this.statement());
    }
  }

  /** Validate an argument at parse time when it contains no names. */
  checkLiteral(e: Expr, check: (v: number, first: Token) => void) {
    if (!isLiteral(e)) return;
    const v = evalLiteral(e);
    if (Number.isFinite(v)) check(v, e.first);
  }

  /** True when `tok` may continue an expression as a binary operator. */
  isBinary(tok: Token | undefined, ops: string): boolean {
    return !!tok && tok.type === 'op' && ops.includes(tok.text) && tok.spaceBefore === tok.spaceAfter;
  }

  expr(owner: Token, proc?: Procedure, argIndex?: number): Expr {
    let left = this.term(owner, proc, argIndex);
    while (this.isBinary(this.peek(), '+-')) {
      const op = this.toks[this.i++].text as '+' | '-';
      left = { kind: 'bin', op, left, right: this.term(owner, proc, argIndex), first: left.first };
    }
    return left;
  }

  term(owner: Token, proc?: Procedure, argIndex?: number): Expr {
    let left = this.unary(owner, proc, argIndex);
    while (this.isBinary(this.peek(), '*/')) {
      const op = this.toks[this.i++].text as '*' | '/';
      left = { kind: 'bin', op, left, right: this.unary(owner, proc, argIndex), first: left.first };
    }
    return left;
  }

  unary(owner: Token, proc?: Procedure, argIndex?: number): Expr {
    const tok = this.peek();
    if (tok && tok.type === 'op' && (tok.text === '-' || tok.text === '+')) {
      this.i++;
      const arg = this.unary(owner, proc, argIndex);
      return tok.text === '-' ? { kind: 'neg', arg, first: tok } : { ...arg, first: tok };
    }
    return this.primary(owner, proc, argIndex);
  }

  primary(owner: Token, proc?: Procedure, argIndex?: number): Expr {
    const tok = this.peek();
    if (!tok) throw at(this.missing(owner, 'koniec programu', proc, argIndex), this.endTok ?? owner);
    if (tok.type === 'number') {
      this.i++;
      return { kind: 'num', value: tok.value, first: tok };
    }
    if (tok.type === 'lparen') {
      this.i++;
      if (++this.parenDepth > MAX_PARENS) throw at('Za dużo zagnieżdżonych nawiasów okrągłych.', tok);
      const inner = this.expr(owner, proc, argIndex);
      const close = this.peek();
      if (!close || close.type !== 'rparen') throw at('Brak nawiasu zamykającego „)” do tego nawiasu.', tok);
      this.i++;
      this.parenDepth--;
      return { ...inner, first: tok };
    }
    if (tok.type === 'word' && REPCOUNT.has(tok.key)) {
      this.i++;
      if (this.repeatDepth === 0) {
        throw at(
          this.locals
            ? `„${tok.text}” musi stać wewnątrz „powtórz” w tej samej procedurze.`
            : `„${tok.text}” działa tylko wewnątrz „powtórz”.`,
          tok,
        );
      }
      return { kind: 'rep', first: tok };
    }
    if (isName(tok) && this.knows(tok.key)) {
      this.i++;
      return { kind: 'var', name: tok.key, first: tok };
    }
    if (tok.type === 'param' || (tok.type === 'word' && !KEYWORDS.has(tok.key) && !this.procs.has(tok.key) && !RESERVED.has(tok.key))) {
      throw at(
        `Nieznana nazwa „${tok.text}”. To nie jest parametr ani zmienna${this.locals ? ' tej procedury ani zmienna globalna' : ''}; nadaj jej wartość poleceniem niech.`,
        tok,
      );
    }
    throw at(this.missing(owner, `„${tok.text}”`, proc, argIndex), tok);
  }

  missing(owner: Token, found: string, proc?: Procedure, argIndex?: number): string {
    if (proc) {
      const n = proc.params.length;
      return `Procedura „${proc.display}” potrzebuje ${n} ${plural(n, 'argumentu', 'argumentów', 'argumentów')}, podano ${argIndex}; znaleziono ${found}.`;
    }
    return `Polecenie „${owner.text}” potrzebuje liczby, a znaleziono ${found}.`;
  }
}

function plural(n: number, one: string, few: string, many: string) {
  if (n === 1) return one;
  const d = n % 10;
  const t = n % 100;
  return d >= 2 && d <= 4 && (t < 12 || t > 14) ? few : many;
}

function isLiteral(e: Expr): boolean {
  switch (e.kind) {
    case 'num':
      return true;
    case 'rep':
    case 'var':
      return false;
    case 'neg':
      return isLiteral(e.arg);
    case 'bin':
      return isLiteral(e.left) && isLiteral(e.right);
  }
}

function evalLiteral(e: Expr): number {
  switch (e.kind) {
    case 'num':
      return e.value;
    case 'rep':
    case 'var':
      return NaN;
    case 'neg':
      return -evalLiteral(e.arg);
    case 'bin': {
      const l = evalLiteral(e.left);
      const r = evalLiteral(e.right);
      return e.op === '+' ? l + r : e.op === '-' ? l - r : e.op === '*' ? l * r : l / r;
    }
  }
}

