  body: Token[];
  end: Token;
}

/** Validate a whole program and build its syntax tree. Throws LogoError on the first problem. */
export function parse(tokens: Token[], mode: Mode): Program {
  const { headers, main } = scanDefinitions(tokens);
  const procs = new Map<string, Procedure>(headers.map((h) => [h.proc.name, h.proc]));

  // Names assigned by `niech` anywhere at top level are global variables.
  const globals = new Set<string>();
  for (let k = 0; k + 1 < main.length; k++) {
    if (isLet(main[k]) && isName(main[k + 1])) globals.add(main[k + 1].key);
  }

  // Parse every unit; report the earliest error in the source.
  const errors: LogoError[] = [];
  const attempt = (f: () => void) => {
    try {
      f();
    } catch (e) {
      if (e instanceof LogoError) errors.push(e);
      else throw e;
    }
  };
  let body: Stmt[] = [];
  attempt(() => {
    body = new Parser(main, mode, procs, globals, null, undefined).program();
  });
  for (const h of headers) {
    attempt(() => {
      const locals = new Set(h.proc.params);
      for (let k = 0; k + 1 < h.body.length; k++) {
        if (isLet(h.body[k]) && isName(h.body[k + 1])) locals.add(h.body[k + 1].key);
