export type CommandId =
  | 'fd' | 'bk' | 'rt' | 'lt' | 'pu' | 'pd' | 'color' | 'width'
  | 'repeat' | 'let' | 'if' | 'ifelse' | 'stop' | 'home' | 'clear'
  | 'up' | 'down' | 'rollr' | 'rolll';

export const ALIASES: Record<CommandId, string[]> = {
  fd: ['np', 'naprzod', 'naprzód', 'fd', 'forward'],
  bk: ['ws', 'wstecz', 'bk', 'back'],
  rt: ['pw', 'prawo', 'rt', 'right'],
  lt: ['lw', 'lewo', 'lt', 'left'],
  pu: ['pod', 'podnies', 'podnieś', 'pu', 'penup'],
  pd: ['opu', 'opusc', 'opuść', 'pd', 'pendown'],
  color: ['kolor', 'color'],
  width: ['grubosc', 'grubość', 'width'],
  repeat: ['powtorz', 'powtórz', 'repeat'],
  let: ['niech', 'let'],
  if: ['jeśli', 'jesli', 'if'],
  ifelse: ['jeżeli', 'jezeli', 'ifelse'],
  stop: ['stop'],
  home: ['dom', 'home'],
  clear: ['czyść', 'czysc', 'cs', 'clearscreen'],
  up: ['gora', 'góra', 'pitchup'],
  down: ['dol', 'dół', 'pitchdown'],
  rollr: ['pp', 'przechylprawo', 'rr', 'rollright'],
  rolll: ['pl', 'przechyllewo', 'rl', 'rollleft'],
};

export const KEYWORDS = new Map<string, CommandId>();
for (const [id, names] of Object.entries(ALIASES) as [CommandId, string[]][]) {
  for (const n of names) KEYWORDS.set(n, id);
}

/** Words that are part of the language and cannot name a variable, parameter or procedure. */
export const RESERVED = new Set<string>([
  ...KEYWORDS.keys(),
  'nrpowt', 'repcount', 'oto', 'to', 'już', 'juz', 'end', 'ma:', 'ma',
]);
