import type { Token } from './lexer';

export type Expr =
  | { kind: 'num'; value: number; first: Token }
  | { kind: 'rep'; first: Token }
  | { kind: 'var'; name: string; first: Token }
  | { kind: 'neg'; arg: Expr; first: Token }
  | { kind: 'bin'; op: '+' | '-' | '*' | '/'; left: Expr; right: Expr; first: Token };

export type CmpOp = '<' | '>' | '=' | '<=' | '>=' | '<>';

export interface Cond {
  left: Expr;
  op: CmpOp;
  right: Expr;
}

export type Stmt =
  | { kind: 'move'; sign: 1 | -1; arg: Expr; tok: Token }
  | { kind: 'turn'; axis: 'yaw' | 'pitch' | 'roll'; sign: 1 | -1; arg: Expr; tok: Token }
  | { kind: 'pen'; down: boolean; tok: Token }
  | { kind: 'color'; color: string; tok: Token }
  | { kind: 'width'; arg: Expr; tok: Token }
  | { kind: 'let'; name: string; arg: Expr; tok: Token }
