describe('interpreter: 3D turtle, dom and czyść', () => {
  test.each([
    ['gora 90 np 10', [0, 0, 10]],
    ['dół 90 np 10', [0, 0, -10]],
    ['gora 90 pw 90 np 10', [10, 0, 0]],
    ['pp 90 pw 90 np 10', [0, 0, -10]],
    ['pl 90 pw 90 np 10', [0, 0, 10]],
    ['rr 90 fd 10', [0, 10, 0]],
    ['pitchup 45 pitchdown 45 rollleft 30 rollright 30 forward 10', [0, 10, 0]],
  ])('3D: %s ends at %j', (src, to) => {
    expect(lastTo(src, '3d')).toEqual(to);
  });

  test('pitch and roll commands are parse-time errors in 2D', () => {
    for (const cmd of ['gora', 'góra', 'dol', 'dół', 'pp', 'pl', 'pitchup', 'rollleft']) {
      const r = run(`np 10\n${cmd} 10`, '2d');
      expect(r.segments).toEqual([]);
      expect(r.error).toMatchObject({ line: 2, column: 1 });
    }
  });

  test('a flat program draws identical coordinates in 2D and 3D', () => {
    const src = 'powtorz 7 [np 37 pw 360 / 7 lw 13.5 ws 4]';
    expect(run(src, '3d')).toEqual(run(src, '2d'));
  });

  test('dom draws back to the origin when the pen is down and resets orientation', () => {
    const r = run('np 10 pw 90 np 10 gora 30 dom np 5', '3d');
    expect(pts(r).slice(2)).toEqual([
      [[10, 10, 0], [0, 0, 0]],
      [[0, 0, 0], [0, 5, 0]],
    ]);
    expect(run('dom pod np 5 dom', '2d').segments).toEqual([]);
  });

  test('czyść forgets earlier strokes and keeps position, pen and colour', () => {
    const r = run('kolor "#2b6fb3" np 10 czyść np 5', '2d');
    expect(r.segments).toEqual([{ from: [0, 10, 0], to: [0, 15, 0], color: '#2b6fb3', width: 3 }]);
    const e = run('np 10 cs np 5 np 1 / 0', '2d');
    expect(e.segments).toHaveLength(1);
    expect(e.error).not.toBeNull();
  });

  test('a move of zero draws nothing', () => {
    expect(run('np 0 ws 0', '2d').segments).toEqual([]);
  });
});
