describe('interpreter: limits', () => {
  test.each([
    // 1 (np) + 1 (repeat) + 4999 × (np + finishing the iteration) = 10 000
    ['np 0 powtorz 4999 [np 0]', true],
    ['powtorz 5000 [np 0]', false],
    ['powtorz 10000 []', false],
    // 1 + 3333 × (conditional + finishing its body + finishing the iteration) = 10 000
    ['powtorz 3333 [jeśli 1 = 1 []]', true],
    ['powtorz 3334 [jeśli 1 = 1 []]', false],
    // a false conditional runs no body: 1 + 4999 × 2 + 1 niech
    ['niech a 1 powtorz 4999 [jeśli 1 = 2 [np 5]]', true],
    // 1 + 3333 × (call + finishing the call + finishing the iteration) = 10 000
    ['oto p\njuż\npowtorz 3333 [p]', true],
    ['oto p\njuż\npowtorz 3334 [p]', false],
  ])('operation limit: %j runs to the end: %s', (src, ok) => {
    const r = run(src, '2d');
    if (ok) expect(r.error).toBeNull();
    else expect(r.error?.message).toMatch(/operacji/);
  });

  test('evaluating expressions is not an operation', () => {
    expect(run('np 0 powtorz 4999 [np (1 + 1 - 2) * 3 / 3]', '2d').error).toBeNull();
  });

  test('32 active frames are allowed, the 33rd is an error at the call', () => {
    const src = (n: number) => `oto r ma: n\n jeśli n > 0 [r n - 1]\njuż\nr ${n}`;
    expect(run(src(31), '2d').error).toBeNull();
    expect(run(src(32), '2d').error).toMatchObject({ line: 2, column: 15 });
    expect(run('oto r ma: n\n jeśli n > 0 [r n - 1]\njuż\npowtorz 1 [r 31]', '2d').error).toMatchObject({ line: 2, column: 15 });
  });

  test('coordinates must stay within ±100 000; what was drawn is kept', () => {
    expect(run('np 100000', '2d').error).toBeNull();
    const r = run('np 10 pod np 99991', '2d');
    expect(r.segments).toHaveLength(1);
    expect(r.error).toMatchObject({ line: 1, column: 11 });
  });

  test('source longer than 50 000 characters or 10 000 tokens is rejected before drawing', () => {
    expect(run('np 1 ' + ' '.repeat(49_995), '2d').error).toBeNull();
    expect(run('np 1 ' + ' '.repeat(49_996), '2d')).toMatchObject({ segments: [], error: { line: 1 } });
    expect(run('np 1 '.repeat(5000), '2d').error).toBeNull();
    expect(run('np 1 '.repeat(5000) + 'np', '2d').error).toMatchObject({ line: 1, column: 25001 });
  });
});
