import { describe, expect, test } from 'vitest';
import { EXAMPLES, exampleById } from '../src/content/examples';
import { run } from '../src/lang';

const ex = (id: string) => {
  const e = exampleById(id)!;
  const r = run(e.source, e.mode);
  expect(r.error).toBeNull();
  return r;
};
const close = (a: number[], b: number[]) => a.every((v, i) => Math.abs(v - b[i]) < 1e-6);

describe('standard programs', () => {
  test('all thirteen are shipped with their modes', () => {
    expect(EXAMPLES.map((e) => `${e.id}:${e.mode}`)).toEqual([
      'kwadrat:2d', 'gwiazda:2d', 'rozeta:2d', 'spirala:2d', 'wielokaty:2d', 'drzewo:2d', 'sniezynka:2d',
      'schody:3d', 'szescian:3d', 'pierscien:3d', 'kula:3d', 'helisa:3d', 'drzewo3d:3d',
    ]);
  });

  test.each([
    ['kwadrat', 4], ['gwiazda', 5], ['rozeta', 48], ['spirala', 90], ['wielokaty', 42],
    ['drzewo', 255], ['sniezynka', 768], ['schody', 12], ['szescian', 17], ['pierscien', 36],
    ['kula', 432], ['helisa', 240], ['drzewo3d', 121],
  ])('%s draws %d strokes without error', (id, n) => {
    expect(ex(id).segments).toHaveLength(n);
  });

  test('gwiazda and pierścień close on themselves', () => {
    for (const id of ['gwiazda', 'pierscien']) {
      const s = ex(id).segments;
      expect(close(s[s.length - 1].to, [0, 0, 0])).toBe(true);
    }
  });

  test('spirala alternates colours and grows by 2.5', () => {
    const s = ex('spirala').segments;
    expect(s.slice(0, 3).map((x) => x.color)).toEqual(['#16866a', '#c1763d', '#16866a']);
    expect(s[0].to).toEqual([0, 2.5, 0]);
  });

  test('drzewo: 15 brown trunk strokes of width 3, the rest green of width 1', () => {
    const s = ex('drzewo').segments;
    expect(s.filter((x) => x.color === '#6b4f2a' && x.width === 3)).toHaveLength(15);
    expect(s.filter((x) => x.color === '#2f8f4e' && x.width === 1)).toHaveLength(240);
    expect(s[0].from).toEqual([0, -120, 0]);
  });

  test('sześcian has every vertex on the 100-unit cube and 12 distinct edges', () => {
    const s = ex('szescian').segments;
    const ok = s.every((x) => [...x.from, ...x.to].every((c) => Math.abs(c) < 1e-9 || Math.abs(c - 100) < 1e-9));
    expect(ok).toBe(true);
    const key = (a: number[], b: number[]) => [a.map(Math.round).join(), b.map(Math.round).join()].sort().join('|');
    expect(new Set(s.map((x) => key(x.from, x.to))).size).toBe(12);
  });

  test('schody climbs to (0, 210, 120) and helisa rises to z = 180', () => {
    expect(close(ex('schody').segments[11].to, [0, 210, 120])).toBe(true);
    const h = ex('helisa').segments;
    expect(h[h.length - 1].to[2]).toBeCloseTo(180, 6);
  });

  test('pierścień lies in the plane tilted 30° about X', () => {
    const t = Math.tan(Math.PI / 6);
    expect(ex('pierscien').segments.every((x) => Math.abs(x.to[2] - x.to[1] * t) < 1e-6)).toBe(true);
  });

  test('drzewo 3D: the trunk goes straight up', () => {
    const s = ex('drzewo3d').segments;
    expect(close(s[0].to, [0, 0, 70])).toBe(true);
    expect(s.filter((x) => x.color === '#6b4f2a')).toHaveLength(4);
  });
});
