  const n = Math.hypot(v[0], v[1], v[2]);
  return [v[0] / n, v[1] / n, v[2] / n];
};

/** Re-orthonormalize heading and up so rounding errors cannot grow. */
export function orthonormal(h: Vec, u: Vec): [Vec, Vec] {
  const hn = norm(h);
  const d = u[0] * hn[0] + u[1] * hn[1] + u[2] * hn[2];
  return [hn, norm([u[0] - d * hn[0], u[1] - d * hn[1], u[2] - d * hn[2]])];
}

