import { describe, expect, test } from 'vitest';
import { createController, type Scheduler } from '../src/app/controller';
import { run } from '../src/lang';

/** A scheduler driven by hand: time is a system boundary. */
function manualClock() {
  let now = 0;
  let queued: ((t: number) => void)[] = [];
  const scheduler: Scheduler = {
    now: () => now,
    frame(cb) {
      queued.push(cb);
      return () => {
        queued = queued.filter((q) => q !== cb);
      };
    },
  };
  const advance = (ms: number, step = 16) => {
    for (let t = 0; t < ms; t += step) {
      now += Math.min(step, ms - t);
      const q = queued;
      queued = [];
      q.forEach((cb) => cb(now));
    }
  };
  return { scheduler, advance };
}

const SRC = 'np 10\npw 90\nnp 20\npw 90\nnp 30';

describe('execution controller', () => {
  test('running at full speed draws what run() draws', () => {
    const { scheduler, advance } = manualClock();
    const c = createController({ scheduler });
    c.setSpeed(10);
    c.run(SRC, '2d');
    advance(16);
    expect(c.state().status).toBe('done');
    expect(c.state().segments).toEqual(run(SRC, '2d').segments);
  });

  test('stepping executes one command at a time and reports its line', () => {
    const { scheduler } = manualClock();
    const c = createController({ scheduler });
    c.step(SRC, '2d');
    expect(c.state()).toMatchObject({ status: 'paused', line: 1 });
    expect(c.state().segments).toHaveLength(1);
    c.step(SRC, '2d');
    c.step(SRC, '2d');
    expect(c.state()).toMatchObject({ status: 'paused', line: 3 });
    expect(c.state().segments).toHaveLength(2);
  });

  test('pause holds the drawing; resume continues where it stopped', () => {
    const { scheduler, advance } = manualClock();
    const c = createController({ scheduler });
    c.setSpeed(1); // one command per second
    c.run(SRC, '2d');
    advance(2500);
    c.pause();
    const held = c.state().line;
    expect(c.state().status).toBe('paused');
    advance(10_000);
    expect(c.state().line).toBe(held);
    c.resume();
    advance(10_000);
    expect(c.state().status).toBe('done');
    expect(c.state().segments).toHaveLength(3);
  });

  test('reset forgets the drawing and returns the turtle home', () => {
    const { scheduler, advance } = manualClock();
    const c = createController({ scheduler });
    c.setSpeed(10);
    c.run(SRC, '2d');
    advance(16);
    c.reset();
    expect(c.state()).toMatchObject({ status: 'idle', segments: [], line: null, error: null });
    expect(c.state().turtle.pos).toEqual([0, 0, 0]);
  });

  test('a parse-time error draws nothing; a run-time error keeps what was drawn', () => {
    const { scheduler, advance } = manualClock();
    const c = createController({ scheduler });
    c.setSpeed(10);
    c.run('np 10\nxyz', '2d');
    advance(16);
    expect(c.state()).toMatchObject({ status: 'error', segments: [], error: { line: 2, column: 1 } });
    c.run('np 10\nnp 1 / 0', '2d');
    advance(16);
    expect(c.state()).toMatchObject({ status: 'error', error: { line: 2, column: 4 } });
    expect(c.state().segments).toHaveLength(1);
  });

  test('listeners hear every change', () => {
    const { scheduler } = manualClock();
    const c = createController({ scheduler });
    const seen: string[] = [];
    c.subscribe((s) => seen.push(s.status));
    c.step(SRC, '2d');
    c.reset();
    expect(seen).toEqual(['paused', 'idle']);
  });
});
EOF
