import { compile, errorInfo, type ErrorInfo, type Machine, type Mode, type Segment, Turtle } from '../lang';

export interface Scheduler {
  now(): number;
  /** Call `cb` on the next animation frame; returns a cancel function. */
  frame(cb: (now: number) => void): () => void;
}

export type Status = 'idle' | 'running' | 'paused' | 'done' | 'error';

export interface TurtleView {
  pos: [number, number, number];
  heading: [number, number, number];
  up: [number, number, number];
  penDown: boolean;
  color: string;
}

export interface ExecState {
  status: Status;
  mode: Mode;
  segments: Segment[];
  turtle: TurtleView;
  /** Line and column of the command executed last, while a program is active. */
  line: number | null;
  column: number | null;
  error: ErrorInfo | null;
  ops: number;
}

/** Commands per second for speed levels 1–10; level 10 runs without animation. */
export const SPEEDS = [1, 3, 8, 20, 50, 120, 300, 800, 2500, Infinity];

export const browserScheduler: Scheduler = {
  now: () => performance.now(),
  frame(cb) {
    const id = requestAnimationFrame(cb);
    return () => cancelAnimationFrame(id);
  },
};

const view = (t: Turtle): TurtleView => ({
  pos: [...t.pos],
  heading: [...t.heading],
  up: [...t.up],
  penDown: t.penDown,
  color: t.color,
});

export function createController({ scheduler = browserScheduler }: { scheduler?: Scheduler } = {}) {
