  });

  test('a drawing moved away from the start still counts', () => {
    expect(checkSolution(ch('prostokat'), 'pod np 50 pw 90 np 30 lw 90 opu np 160 pw 90 np 80 pw 90 np 160 pw 90 np 80').pass).toBe(true);
  });

  test('failures explain why', () => {
    expect(checkSolution(ch('prostokat'), '')).toMatchObject({ pass: false, reason: expect.stringMatching(/Nic/) });
