      pass: false,
      reason: expect.stringMatching(/za dużo|dodatkow/),
    });
    expect(checkSolution(ch('prostokat'), 'np 10 xyz')).toMatchObject({ pass: false, reason: expect.stringMatching(/Wiersz 1/) });
  });

  test('a required construct is enforced', () => {
