    expect(checkSolution(ch('szesciokat'), hex)).toMatchObject({ pass: false, reason: expect.stringMatching(/oto/) });
    expect(checkSolution(ch('szesciokat'), `oto s\n ${hex}\njuż\ns`).pass).toBe(true);
  });

  test('a 3D task is checked in space', () => {
    expect(checkSolution(ch('pion'), 'gora 90 powtorz 4 [np 80 dol 90]').pass).toBe(true);
    expect(checkSolution(ch('pion'), 'powtorz 4 [np 80 pw 90]').pass).toBe(false);
  });
});
