export type Requirement = 'repeat' | 'procedure' | 'repcount';

export interface Challenge {
  id: string;
  title: string;
  mode: Mode;
  /** What to draw, in Polish. */
  task: string;
  hint: string;
  requires?: Requirement;
  /** Reference solution; its drawing is the expected result. */
  solution: string;
  target(): Segment[];
}

const make = (c: Omit<Challenge, 'target'>): Challenge => {
  let cached: Segment[] | null = null;
  return { ...c, target: () => (cached ??= run(c.solution, c.mode).segments) };
};

