export const challengeById = (id: string) => CHALLENGES.find((c) => c.id === id);

export interface Verdict {
  pass: boolean;
  reason: string;
}

const REQUIREMENT_TEXT: Record<Requirement, string> = {
  repeat: 'To zadanie trzeba rozwiązać z użyciem „powtórz”.',
  procedure: 'To zadanie wymaga zdefiniowania własnej procedury słowami „oto” … „już” i jej wywołania.',
  repcount: 'To zadanie wymaga użycia „nrpowt”.',
};

function uses(source: string, req: Requirement): boolean {
  const toks = tokenize(source);
  switch (req) {
    case 'repeat':
      return toks.some((t) => t.type === 'word' && KEYWORDS.get(t.key) === 'repeat');
    case 'procedure': {
      const names = new Set<string>();
      toks.forEach((t, i) => {
        if (t.type === 'word' && (t.key === 'oto' || t.key === 'to') && toks[i + 1]) names.add(toks[i + 1].key);
      });
      // A procedure counts when its name also appears outside its own header.
      return [...names].some((n) => toks.filter((t) => t.type === 'word' && t.key === n).length > 1);
    }
    case 'repcount':
      return toks.some((t) => t.type === 'word' && (t.key === 'nrpowt' || t.key === 'repcount'));
  }
}

type V = [number, number, number];

function distToSegment(p: V, s: Segment): number {
  const d: V = [s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]];
  const w: V = [p[0] - s.from[0], p[1] - s.from[1], p[2] - s.from[2]];
  const len2 = d[0] * d[0] + d[1] * d[1] + d[2] * d[2];
  const t = len2 === 0 ? 0 : Math.max(0, Math.min(1, (w[0] * d[0] + w[1] * d[1] + w[2] * d[2]) / len2));
  return Math.hypot(w[0] - t * d[0], w[1] - t * d[1], w[2] - t * d[2]);
}

function samples(s: Segment, step: number): V[] {
  const len = Math.hypot(s.to[0] - s.from[0], s.to[1] - s.from[1], s.to[2] - s.from[2]);
  const n = Math.max(1, Math.ceil(len / step));
  const out: V[] = [];
  for (let k = 0; k <= n; k++) {
    const t = k / n;
    out.push([
      s.from[0] + (s.to[0] - s.from[0]) * t,
      s.from[1] + (s.to[1] - s.from[1]) * t,
      s.from[2] + (s.to[2] - s.from[2]) * t,
    ]);
  }
  return out;
}

/** First sample of `a` that lies farther than `tol` from every stroke of `b`. */
function uncovered(a: Segment[], b: Segment[], tol: number): V | null {
  for (const s of a) for (const p of samples(s, tol)) if (!b.some((q) => distToSegment(p, q) <= tol)) return p;
  return null;
}

function center(segs: Segment[]): V {
  const lo: V = [Infinity, Infinity, Infinity];
  const hi: V = [-Infinity, -Infinity, -Infinity];
  for (const s of segs)
    for (const p of [s.from, s.to])
      for (let k = 0; k < 3; k++) {
        lo[k] = Math.min(lo[k], p[k]);
        hi[k] = Math.max(hi[k], p[k]);
