}

const shift = (segs: Segment[], by: V): Segment[] =>
  segs.map((s) => ({
    ...s,
    from: [s.from[0] + by[0], s.from[1] + by[1], s.from[2] + by[2]],
    to: [s.to[0] + by[0], s.to[1] + by[1], s.to[2] + by[2]],
  }));

const where = (p: V, mode: Mode) =>
  mode === '2d' ? `(${Math.round(p[0])}, ${Math.round(p[1])})` : `(${Math.round(p[0])}, ${Math.round(p[1])}, ${Math.round(p[2])})`;

