export const TOLERANCE = 2;

/** Compare a drawing with the expected one: strokes may be split, reordered or reversed, and moved as a whole. */
export function compareDrawings(expected: Segment[], actual: Segment[], mode: Mode): Verdict {
  if (actual.length === 0) return { pass: false, reason: 'Nic nie zostało narysowane. Sprawdź, czy pisak jest opuszczony.' };
