  if (r.missing || r.extra) {
    const a = center(actual);
    const e = center(expected);
    const r2 = tryWith(shift(actual, [e[0] - a[0], e[1] - a[1], e[2] - a[2]]));
    if (!r2.missing && !r2.extra) {
      r = r2;
      moved = true;
    }
  }
  if (r.missing) return { pass: false, reason: `Brakuje części rysunku w okolicy punktu ${where(r.missing, mode)}.` };
  if (r.extra) {
    return { pass: false, reason: `Rysunek ma za dużo linii: dodatkowa kreska w okolicy punktu ${where(r.extra, mode)}.` };
  }
  return {
    pass: true,
    reason: moved ? 'Zaliczone! Rysunek jest przesunięty, ale kształt się zgadza.' : 'Zaliczone! Rysunek zgadza się z wzorem.',
  };
}

export function checkSolution(c: Challenge, source: string): Verdict {
  const r = run(source, c.mode);
  if (r.error) {
    return { pass: false, reason: `Program zgłasza błąd (Wiersz ${r.error.line}, kolumna ${r.error.column}): ${r.error.message}` };
  }
  const v = compareDrawings(c.target(), r.segments, c.mode);
  if (v.pass && c.requires && !uses(source, c.requires)) return { pass: false, reason: REQUIREMENT_TEXT[c.requires] };
  return v;
}
