  RotateCcw, Shapes, Square, StepForward, Sun, SunMoon, Trophy, Undo2, X, ZoomIn, ZoomOut, PenLine, Keyboard,
  createElement, type IconNode,
} from 'lucide';

const ICONS = {
  play: Play, pause: Pause, step: StepForward, reset: RotateCcw, fit: Maximize, zoomIn: ZoomIn, zoomOut: ZoomOut,
  camera: Crosshair, sun: Sun, moon: Moon, auto: SunMoon, link: Link, image: Image, save: FileDown, open: FileUp,
  check: Check, close: X, undo: Undo2, book: BookOpen, trophy: Trophy, shapes: Shapes, pen: PenLine, cube: Box,
  square: Square, copy: Copy, keyboard: Keyboard,
} satisfies Record<string, IconNode>;

export type IconName = keyof typeof ICONS;

export function icon(name: IconName, size = 18): SVGElement {
  const el = createElement(ICONS[name], { width: size, height: size, 'stroke-width': 2 }) as unknown as SVGElement;
  el.setAttribute('aria-hidden', 'true');
  el.setAttribute('focusable', 'false');
  el.classList.add('icon');
  return el;
}
