  private error: ErrorInfo | null = null;
  private execLine: number | null = null;
  private listeners: ((v: string) => void)[] = [];
  private lastRendered = '';

  constructor(opts: { describedBy?: string; label?: string } = {}) {
    this.textarea = h('textarea', {
      class: 'editor-input',
      'aria-label': opts.label ?? 'Program',
      'aria-describedby': opts.describedBy,
      spellcheck: 'false',
      autocapitalize: 'off',
      autocomplete: 'off',
      autocorrect: 'off',
      wrap: 'off',
    });
    this.gutter = h('div', { class: 'editor-gutter', 'aria-hidden': 'true' });
    this.layer = h('div', { class: 'editor-layer', 'aria-hidden': 'true' });
    this.el = h('div', { class: 'editor' }, this.gutter, h('div', { class: 'editor-code' }, this.layer, this.textarea));

    this.textarea.addEventListener('input', () => {
      this.error = null;
      this.render();
      this.listeners.forEach((l) => l(this.value));
    });
    this.textarea.addEventListener('scroll', () => this.syncScroll());
    this.textarea.addEventListener('keydown', (e) => this.onKey(e));
    this.render();
  }

  get value(): string {
    return this.textarea.value;
  }

  /** Replace the whole text (programmatic load). */
  set value(v: string) {
    this.textarea.value = v;
    this.error = null;
    this.execLine = null;
    this.render();
  }

  onInput(cb: (v: string) => void) {
    this.listeners.push(cb);
  }

  setError(err: ErrorInfo | null) {
    this.error = err;
    this.render(true);
  }

  setExecLine(line: number | null) {
    if (line === this.execLine) return;
    this.execLine = line;
    this.render(true);
    if (line !== null) this.revealLine(line);
  }

  /** Put the caret at a 1-based line and column. */
  focusAt(line: number, column: number) {
    const lines = this.value.split('\n');
    let offset = 0;
    for (let i = 0; i < line - 1 && i < lines.length; i++) offset += lines[i].length + 1;
    offset += Math.min(column - 1, (lines[line - 1] ?? '').length);
    this.textarea.focus();
    this.textarea.setSelectionRange(offset, offset);
    this.revealLine(line);
  }

  private revealLine(line: number) {
    const lh = parseFloat(getComputedStyle(this.textarea).lineHeight) || 22;
    const top = (line - 1) * lh;
    const ta = this.textarea;
    if (top < ta.scrollTop || top + lh > ta.scrollTop + ta.clientHeight) {
      ta.scrollTop = Math.max(0, top - ta.clientHeight / 2);
    }
  }

  private syncScroll() {
    const { scrollTop, scrollLeft } = this.textarea;
    this.layer.style.transform = `translate(${-scrollLeft}px, ${-scrollTop}px)`;
    this.gutter.style.transform = `translateY(${-scrollTop}px)`;
  }

  private onKey(e: KeyboardEvent) {
    // Keep the indentation of the current line on Enter.
    if (e.key === 'Enter' && !e.ctrlKey && !e.metaKey && !e.altKey && !e.shiftKey && !e.isComposing) {
      const ta = this.textarea;
      const start = ta.selectionStart;
      const lineStart = ta.value.lastIndexOf('\n', start - 1) + 1;
      const indent = /^[ \t]*/.exec(ta.value.slice(lineStart, start))![0];
      const opens = /\[\s*$/.test(ta.value.slice(lineStart, start)) ? '  ' : '';
      if (indent || opens) {
        e.preventDefault();
        ta.setRangeText('\n' + indent + opens, start, ta.selectionEnd, 'end');
        ta.dispatchEvent(new Event('input'));
      }
    }
  }

  private render(force = false) {
    const text = this.value;
    if (!force && text === this.lastRendered && !this.error && this.execLine === null) return;
    this.lastRendered = text;
    const lines: HTMLElement[][] = [[]];
    for (const tok of highlightTokens(text)) {
      const parts = tok.text.split('\n');
      parts.forEach((part, i) => {
        if (i > 0) lines.push([]);
        if (part) {
          const span = h('span', { class: `t-${tok.cls}` }, part);
          if (tok.cls === 'str' && /^"#[0-9a-f]{6}"$/i.test(part)) span.style.setProperty('--swatch', part.slice(1, -1));
          lines[lines.length - 1].push(span);
        }
      });
    }
    const err = this.error;
    const rows = lines.map((spans, i) => {
      const n = i + 1;
      const row = h('div', { class: 'editor-line' });
      if (n === this.execLine) row.classList.add('is-exec');
      if (err && n === err.line) {
        row.classList.add('is-error');
        row.append(...markColumn(spans, err.column));
        row.append(h('span', { class: 'error-flag' }, err.message));
      } else row.append(...spans);
      return row;
    });
    // Error past the last line (e.g. at the very end) still gets a row.
    if (err && err.line > lines.length) {
      rows.push(h('div', { class: 'editor-line is-error' }, h('span', { class: 'error-caret' }, ' '), h('span', { class: 'error-flag' }, err.message)));
    }
    this.layer.replaceChildren(...rows, h('div', { class: 'editor-line' }, ' '));
    this.gutter.replaceChildren(
      ...rows.map((_, i) => {
        const n = i + 1;
        const cls = ['gutter-line', n === this.execLine ? 'is-exec' : '', err && n === err.line ? 'is-error' : ''].join(' ').trim();
        return h('div', { class: cls }, String(n));
      }),
    );
    this.syncScroll();
  }
}

/** Wrap the token starting at `column` (1-based) in an error mark. */
function markColumn(spans: HTMLElement[], column: number): Node[] {
  const out: Node[] = [];
  let col = 1;
  let marked = false;
  for (const s of spans) {
    const text = s.textContent ?? '';
    const end = col + text.length;
    if (!marked && column >= col && column < end) {
      const off = column - col;
      if (off > 0) out.push(h('span', { class: s.className }, text.slice(0, off)));
      // Mark up to the next whitespace in this span.
      const rest = text.slice(off);
      const word = /^\S+/.exec(rest)?.[0] ?? rest.slice(0, 1);
      out.push(h('mark', { class: `error-token ${s.className}` }, word));
      if (rest.length > word.length) out.push(h('span', { class: s.className }, rest.slice(word.length)));
      marked = true;
    } else out.push(s);
    col = end;
  }
  if (!marked) out.push(h('span', { class: 'error-caret' }, ' '));
  return out;
}

