import type { Segment } from '../lang';
import type { TurtleView } from './controller';
import { palette, type Palette } from './theme';

const MIN_ZOOM = 0.01;
const MAX_ZOOM = 80;

/** The flat view: a canvas with pan, zoom, fit and a visible origin. */
export class View2D {
  readonly canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D | null;
  private segments: Segment[] = [];
  private target: Segment[] | null = null;
  private turtle: TurtleView | null = null;
  /** World point at the centre of the canvas, and pixels per unit. */
  private cx = 0;
  private cy = 0;
  private zoom = 1.5;
  private pending = false;
  private pointers = new Map<number, { x: number; y: number }>();
  private colors: Palette = palette();
  private resizeObserver?: ResizeObserver;

  constructor() {
    this.canvas = document.createElement('canvas');
    this.canvas.className = 'view-canvas';
    this.canvas.tabIndex = 0;
    this.canvas.setAttribute('role', 'img');
    this.canvas.setAttribute('aria-roledescription', 'płótno');
    this.canvas.setAttribute('aria-label', 'Rysunek 2D. Przeciągnij, aby przesunąć; kółko myszy, gest lub klawisze + i − przybliżają; strzałki przesuwają; 0 dopasowuje widok.');
    this.ctx = this.canvas.getContext('2d');
    this.bind();
    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => this.requestRender());
      this.resizeObserver.observe(this.canvas);
    }
  }

  destroy() {
    this.resizeObserver?.disconnect();
  }

  setScene(segments: Segment[], turtle: TurtleView | null) {
    this.segments = segments;
    this.turtle = turtle;
    this.requestRender();
  }

  setTarget(target: Segment[] | null) {
    this.target = target;
    this.requestRender();
  }

  refreshTheme() {
    this.colors = palette();
    this.requestRender();
  }

  /** Fit the drawing (and the origin and turtle) into the canvas. */
  fit() {
    const pts: [number, number][] = [[0, 0]];
    for (const s of [...this.segments, ...(this.target ?? [])]) pts.push([s.from[0], s.from[1]], [s.to[0], s.to[1]]);
    if (this.turtle) pts.push([this.turtle.pos[0], this.turtle.pos[1]]);
    let [x0, y0, x1, y1] = [Infinity, Infinity, -Infinity, -Infinity];
    for (const [x, y] of pts) {
      x0 = Math.min(x0, x);
      y0 = Math.min(y0, y);
      x1 = Math.max(x1, x);
      y1 = Math.max(y1, y);
    }
    const { w, h } = this.size();
    const pad = 36;
    const span = Math.max(x1 - x0, y1 - y0, 40);
    this.zoom = clamp(Math.min((w - pad * 2) / Math.max(x1 - x0, 1), (h - pad * 2) / Math.max(y1 - y0, 1), (Math.min(w, h) - pad * 2) / span * 4));
    if (!Number.isFinite(this.zoom) || this.zoom <= 0) this.zoom = 1;
    this.cx = (x0 + x1) / 2;
    this.cy = (y0 + y1) / 2;
    this.requestRender();
  }

  zoomBy(f: number, px?: number, py?: number) {
    const { w, h } = this.size();
    const sx = px ?? w / 2;
    const sy = py ?? h / 2;
    const [wx, wy] = this.toWorld(sx, sy);
    this.zoom = clamp(this.zoom * f);
    // Keep the point under the cursor in place.
    this.cx = wx - (sx - w / 2) / this.zoom;
    this.cy = wy + (sy - h / 2) / this.zoom;
    this.requestRender();
  }

  panBy(dxPx: number, dyPx: number) {
    this.cx -= dxPx / this.zoom;
    this.cy += dyPx / this.zoom;
    this.requestRender();
  }

  /** Render immediately and resolve after the frame is on screen. */
  async renderNow(): Promise<void> {
    this.draw();
    await nextFrame();
  }

  toBlob(): Promise<Blob | null> {
    this.draw();
    return new Promise((resolve) => {
      try {
        this.canvas.toBlob((b) => resolve(b), 'image/png');
      } catch {
        resolve(null);
      }
    });
  }

  requestRender() {
    if (this.pending) return;
    this.pending = true;
    nextFrame().then(() => {
      this.pending = false;
      this.draw();
    });
  }

  private size() {
    const r = this.canvas.getBoundingClientRect();
    return { w: r.width || this.canvas.clientWidth || 600, h: r.height || this.canvas.clientHeight || 400 };
  }

  private toWorld(sx: number, sy: number): [number, number] {
    const { w, h } = this.size();
    return [this.cx + (sx - w / 2) / this.zoom, this.cy - (sy - h / 2) / this.zoom];
  }

  private draw() {
    const ctx = this.ctx;
    if (!ctx) return;
    const { w, h } = this.size();
    const dpr = window.devicePixelRatio || 1;
    if (this.canvas.width !== Math.round(w * dpr) || this.canvas.height !== Math.round(h * dpr)) {
      this.canvas.width = Math.round(w * dpr);
      this.canvas.height = Math.round(h * dpr);
    }
    const c = this.colors;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = c.paper;
    ctx.fillRect(0, 0, w, h);
    const X = (x: number) => w / 2 + (x - this.cx) * this.zoom;
    const Y = (y: number) => h / 2 - (y - this.cy) * this.zoom;

    // Coordinate grid: a step that stays 40–100 px apart.
    const steps = [1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000];
    const step = steps.find((s) => s * this.zoom >= 40) ?? 100000;
    const [wx0, wy1] = this.toWorld(0, 0);
    const [wx1, wy0] = this.toWorld(w, h);
    ctx.lineWidth = 1;
    ctx.strokeStyle = c.grid;
    ctx.beginPath();
    for (let x = Math.ceil(wx0 / step) * step; x <= wx1; x += step) {
      ctx.moveTo(Math.round(X(x)) + 0.5, 0);
      ctx.lineTo(Math.round(X(x)) + 0.5, h);
    }
    for (let y = Math.ceil(wy0 / step) * step; y <= wy1; y += step) {
      ctx.moveTo(0, Math.round(Y(y)) + 0.5);
      ctx.lineTo(w, Math.round(Y(y)) + 0.5);
    }
    ctx.stroke();
    // Axes and the origin.
    ctx.strokeStyle = c.axis;
    ctx.beginPath();
    ctx.moveTo(0, Math.round(Y(0)) + 0.5);
    ctx.lineTo(w, Math.round(Y(0)) + 0.5);
    ctx.moveTo(Math.round(X(0)) + 0.5, 0);
    ctx.lineTo(Math.round(X(0)) + 0.5, h);
    ctx.stroke();
    ctx.fillStyle = c.axisText;
    ctx.font = '500 11px Lexend, system-ui, sans-serif';
    ctx.fillText('0', X(0) + 5, Y(0) + 14);
    ctx.fillText('x', w - 14, Y(0) - 6);
    ctx.fillText('y', X(0) + 6, 14);
    ctx.beginPath();
    ctx.arc(X(0), Y(0), 3.5, 0, Math.PI * 2);
    ctx.fill();

    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    if (this.target) {
      ctx.setLineDash([6, 6]);
      ctx.strokeStyle = c.target;
      ctx.lineWidth = 6;
      ctx.beginPath();
      for (const s of this.target) {
        ctx.moveTo(X(s.from[0]), Y(s.from[1]));
        ctx.lineTo(X(s.to[0]), Y(s.to[1]));
      }
      ctx.stroke();
      ctx.setLineDash([]);
    }
    // Strokes, batched by colour and width.
    let i = 0;
    const segs = this.segments;
    while (i < segs.length) {
      const { color, width } = segs[i];
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
      ctx.beginPath();
      while (i < segs.length && segs[i].color === color && segs[i].width === width) {
        const s = segs[i++];
        ctx.moveTo(X(s.from[0]), Y(s.from[1]));
        ctx.lineTo(X(s.to[0]), Y(s.to[1]));
      }
      ctx.stroke();
    }
    if (this.turtle) drawTurtle(ctx, X(this.turtle.pos[0]), Y(this.turtle.pos[1]), this.turtle, c);
  }

  private bind() {
    const cv = this.canvas;
    cv.addEventListener('pointerdown', (e) => {
      cv.setPointerCapture?.(e.pointerId);
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    });
    const end = (e: PointerEvent) => this.pointers.delete(e.pointerId);
    cv.addEventListener('pointerup', end);
    cv.addEventListener('pointercancel', end);
    cv.addEventListener('pointermove', (e) => {
      const prev = this.pointers.get(e.pointerId);
      if (!prev) return;
      if (this.pointers.size === 1) {
        this.panBy(e.clientX - prev.x, e.clientY - prev.y);
      } else if (this.pointers.size === 2) {
        const other = [...this.pointers.entries()].find(([id]) => id !== e.pointerId)![1];
        const before = Math.hypot(prev.x - other.x, prev.y - other.y);
        const after = Math.hypot(e.clientX - other.x, e.clientY - other.y);
        const r = cv.getBoundingClientRect();
        if (before > 0) this.zoomBy(after / before, (e.clientX + other.x) / 2 - r.left, (e.clientY + other.y) / 2 - r.top);
      }
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
    });
    cv.addEventListener(
      'wheel',
      (e) => {
        e.preventDefault();
        const r = cv.getBoundingClientRect();
        this.zoomBy(Math.exp(-e.deltaY * 0.0015), e.clientX - r.left, e.clientY - r.top);
      },
      { passive: false },
    );
    cv.addEventListener('keydown', (e) => {
      const k = e.key;
      const step = e.shiftKey ? 120 : 40;
      if (k === 'ArrowLeft') this.panBy(step, 0);
      else if (k === 'ArrowRight') this.panBy(-step, 0);
      else if (k === 'ArrowUp') this.panBy(0, step);
      else if (k === 'ArrowDown') this.panBy(0, -step);
      else if (k === '+' || k === '=') this.zoomBy(1.25);
      else if (k === '-' || k === '_') this.zoomBy(0.8);
      else if (k === '0' || k === 'f' || k === 'F') this.fit();
      else return;
      e.preventDefault();
    });
  }
}

/** The turtle: a cut-paper arrowhead pointing along its heading; hollow when the pen is up. */
function drawTurtle(ctx: CanvasRenderingContext2D, x: number, y: number, t: TurtleView, c: Palette) {
  const angle = Math.atan2(t.heading[0], t.heading[1]); // clockwise from +Y
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.beginPath();
  ctx.moveTo(0, -15);
  ctx.lineTo(10, 10);
  ctx.lineTo(0, 5);
  ctx.lineTo(-10, 10);
  ctx.closePath();
  ctx.lineWidth = 2;
  ctx.strokeStyle = c.turtleEdge;
  if (t.penDown) {
    ctx.fillStyle = t.color;
    ctx.fill();
  } else {
    ctx.fillStyle = c.paper;
    ctx.fill();
  }
  ctx.stroke();
  ctx.restore();
}

const clamp = (z: number) => Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, z));

export function nextFrame(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(() => resolve());
    else setTimeout(resolve, 16);
  });
}

