      ctx.lineTo(Math.round(X(x)) + 0.5, h);
    }
    for (let y = Math.ceil(wy0 / step) * step; y <= wy1; y += step) {
      ctx.moveTo(0, Math.round(Y(y)) + 0.5);
      ctx.lineTo(w, Math.round(Y(y)) + 0.5);
    }
    ctx.stroke();
    // Axes and the origin.
    ctx.strokeStyle = c.axis;
    ctx.beginPath();
    ctx.moveTo(0, Math.round(Y(0)) + 0.5);
    ctx.lineTo(w, Math.round(Y(0)) + 0.5);
    ctx.moveTo(Math.round(X(0)) + 0.5, 0);
    ctx.lineTo(Math.round(X(0)) + 0.5, h);
    ctx.stroke();
    ctx.fillStyle = c.axisText;
    ctx.font = '500 11px Lexend, system-ui, sans-serif';
    ctx.fillText('0', X(0) + 5, Y(0) + 14);
    ctx.fillText('x', w - 14, Y(0) - 6);
    ctx.fillText('y', X(0) + 6, 14);
    ctx.beginPath();
    ctx.arc(X(0), Y(0), 3.5, 0, Math.PI * 2);
    ctx.fill();

    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    if (this.target) {
      ctx.setLineDash([6, 6]);
      ctx.strokeStyle = c.target;
      ctx.lineWidth = 6;
      ctx.beginPath();
      for (const s of this.target) {
        ctx.moveTo(X(s.from[0]), Y(s.from[1]));
        ctx.lineTo(X(s.to[0]), Y(s.to[1]));
      }
      ctx.stroke();
      ctx.setLineDash([]);
    }
