    let i = 0;
    const segs = this.segments;
    while (i < segs.length) {
      const { color, width } = segs[i];
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
      ctx.beginPath();
      while (i < segs.length && segs[i].color === color && segs[i].width === width) {
