      else if (k === '+' || k === '=') this.zoomBy(1.25);
      else if (k === '-' || k === '_') this.zoomBy(0.8);
      else if (k === '0' || k === 'f' || k === 'F') this.fit();
      else return;
      e.preventDefault();
    });
  }
}

/** The turtle: a cut-paper arrowhead pointing along its heading; hollow when the pen is up. */
function drawTurtle(ctx: CanvasRenderingContext2D, x: number, y: number, t: TurtleView, c: Palette) {
  const angle = Math.atan2(t.heading[0], t.heading[1]); // clockwise from +Y
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(angle);
  ctx.beginPath();
  ctx.moveTo(0, -15);
  ctx.lineTo(10, 10);
  ctx.lineTo(0, 5);
  ctx.lineTo(-10, 10);
  ctx.closePath();
  ctx.lineWidth = 2;
  ctx.strokeStyle = c.turtleEdge;
  if (t.penDown) {
    ctx.fillStyle = t.color;
    ctx.fill();
  } else {
    ctx.fillStyle = c.paper;
    ctx.fill();
  }
  ctx.stroke();
  ctx.restore();
}

const clamp = (z: number) => Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, z));

export function nextFrame(): Promise<void> {
  return new Promise((resolve) => {
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(() => resolve());
    else setTimeout(resolve, 16);
  });
}

