    this.canvas.setAttribute('aria-label', 'Rysunek 2D. Przeciągnij, aby przesunąć; kółko myszy, gest lub klawisze + i − przybliżają; strzałki przesuwają; 0 dopasowuje widok.');
    this.ctx = this.canvas.getContext('2d');
    this.bind();
    if (typeof ResizeObserver !== 'undefined') {
      this.resizeObserver = new ResizeObserver(() => this.requestRender());
      this.resizeObserver.observe(this.canvas);
    }
  }

  destroy() {
    this.resizeObserver?.disconnect();
  }

  setScene(segments: Segment[], turtle: TurtleView | null) {
    this.segments = segments;
    this.turtle = turtle;
    this.requestRender();
  }

  setTarget(target: Segment[] | null) {
    this.target = target;
    this.requestRender();
  }

  refreshTheme() {
    this.colors = palette();
    this.requestRender();
  }

  /** Fit the drawing (and the origin and turtle) into the canvas. */
  fit() {
    const pts: [number, number][] = [[0, 0]];
    for (const s of [...this.segments, ...(this.target ?? [])]) pts.push([s.from[0], s.from[1]], [s.to[0], s.to[1]]);
    if (this.turtle) pts.push([this.turtle.pos[0], this.turtle.pos[1]]);
    let [x0, y0, x1, y1] = [Infinity, Infinity, -Infinity, -Infinity];
    for (const [x, y] of pts) {
      x0 = Math.min(x0, x);
      y0 = Math.min(y0, y);
      x1 = Math.max(x1, x);
      y1 = Math.max(y1, y);
    }
    const { w, h } = this.size();
    const pad = 36;
    const span = Math.max(x1 - x0, y1 - y0, 40);
