    this.cx = wx - (sx - w / 2) / this.zoom;
    this.cy = wy + (sy - h / 2) / this.zoom;
    this.requestRender();
  }

  panBy(dxPx: number, dyPx: number) {
    this.cx -= dxPx / this.zoom;
    this.cy += dyPx / this.zoom;
    this.requestRender();
  }

  /** Render immediately and resolve after the frame is on screen. */
  async renderNow(): Promise<void> {
    this.draw();
    await nextFrame();
  }

