export function webglProblem(): string | null {
  try {
    const c = document.createElement('canvas');
    const gl = c.getContext('webgl2') ?? c.getContext('webgl');
    if (!gl) return 'Ta przeglądarka nie udostępnia WebGL (może być wyłączony w ustawieniach albo nieobsługiwany przez kartę graficzną), więc widok 3D jest wyłączony. Programy 3D nadal się wykonują, a tryb 2D działa normalnie.';
    return null;
  } catch {
    return 'Nie udało się uruchomić WebGL, więc widok 3D jest wyłączony. Tryb 2D działa normalnie.';
  }
}

async function loadEngine() {
  const [THREE, { OrbitControls }, { LineSegments2 }, { LineSegmentsGeometry }, { LineMaterial }] = await Promise.all([
    import('three'),
