      else if (k === '-' || k === '_') this.zoomBy(0.8);
      else if (k === '0' || k === 'f' || k === 'F') this.fit();
      else return;
      e.preventDefault();
    });
  }
}

function makeTurtle(THREE: Three) {
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.ConeGeometry(0.45, 1.4, 4), new THREE.MeshBasicMaterial({ color: 0x16866a }));
  body.position.y = 0.2;
  body.name = 'body';
  // A fin that points along the turtle's up vector shows its roll.
  const finGeo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, -0.4, 0), new THREE.Vector3(0, 0.5, 0), new THREE.Vector3(0, -0.4, 0.9)]);
  const fin = new THREE.Mesh(finGeo, new THREE.MeshBasicMaterial({ color: 0x161a17, side: THREE.DoubleSide }));
  fin.name = 'fin';
  const edges = new THREE.LineSegments(new THREE.EdgesGeometry(body.geometry), new THREE.LineBasicMaterial({ color: 0x161a17 }));
  edges.position.copy(body.position);
  g.add(body, edges, fin);
  return g;
}

function placeTurtle(THREE: Three, g: import('three').Group, t: TurtleView, scale: number) {
  const hd = new THREE.Vector3(...t.heading);
  const up = new THREE.Vector3(...t.up);
  const right = new THREE.Vector3().crossVectors(hd, up);
  g.matrixAutoUpdate = false;
  const m = new THREE.Matrix4().makeBasis(right, hd, up).scale(new THREE.Vector3(scale, scale, scale));
  m.setPosition(...t.pos);
  g.matrix.copy(m);
  const body = g.getObjectByName('body') as import('three').Mesh;
  const mat = body.material as import('three').MeshBasicMaterial;
  mat.color.set(t.penDown ? t.color : palette().paper);
  const fin = g.getObjectByName('fin') as import('three').Mesh;
  (fin.material as import('three').MeshBasicMaterial).color.set(palette().turtleEdge);
  ((g.children[1] as import('three').LineSegments).material as import('three').LineBasicMaterial).color.set(palette().turtleEdge);
}

function niceStep(raw: number): number {
  const p = Math.pow(10, Math.floor(Math.log10(Math.max(raw, 1e-9))));
  const n = raw / p;
  return (n < 1.5 ? 1 : n < 3.5 ? 2 : n < 7.5 ? 5 : 10) * p;
}

