import type { Segment } from '../lang';
import type { TurtleView } from './controller';
import { h } from './dom';
import { palette } from './theme';
import { nextFrame } from './view2d';

type Three = typeof import('three');
type Engine = Awaited<ReturnType<typeof loadEngine>>;

/** Why 3D cannot be shown, or null when WebGL is available. */
export function webglProblem(): string | null {
  try {
    const c = document.createElement('canvas');
    const gl = c.getContext('webgl2') ?? c.getContext('webgl');
    if (!gl) return 'Ta przeglądarka nie udostępnia WebGL (może być wyłączony w ustawieniach albo nieobsługiwany przez kartę graficzną), więc widok 3D jest wyłączony. Programy 3D nadal się wykonują, a tryb 2D działa normalnie.';
    return null;
  } catch {
    return 'Nie udało się uruchomić WebGL, więc widok 3D jest wyłączony. Tryb 2D działa normalnie.';
  }
}

async function loadEngine() {
  const [THREE, { OrbitControls }, { LineSegments2 }, { LineSegmentsGeometry }, { LineMaterial }] = await Promise.all([
    import('three'),
    import('three/examples/jsm/controls/OrbitControls.js'),
    import('three/examples/jsm/lines/LineSegments2.js'),
    import('three/examples/jsm/lines/LineSegmentsGeometry.js'),
    import('three/examples/jsm/lines/LineMaterial.js'),
  ]);
  return { THREE, OrbitControls, LineSegments2, LineSegmentsGeometry, LineMaterial };
}

/** The spatial view: orbit, pan and zoom around a ground grid with axes. */
export class View3D {
  readonly el: HTMLDivElement;
  private host: HTMLDivElement;
  private labels: HTMLSpanElement[];
  private e?: Engine;
  private renderer?: import('three').WebGLRenderer;
  private scene?: import('three').Scene;
  private camera?: import('three').PerspectiveCamera;
  private controls?: InstanceType<Engine['OrbitControls']>;
  private strokes?: import('three').Group;
  private turtleMesh?: import('three').Group;
  private ghost?: import('three').Group;
  private grid?: import('three').Group;
  private segments: Segment[] = [];
  private target: Segment[] | null = null;
  private turtle: TurtleView | null = null;
  private builtCount = -1;
  private builtRef: Segment[] | null = null;
  private pending = false;
  private resizeObserver?: ResizeObserver;
  readonly ready: Promise<boolean>;
  problem: string | null = null;

  constructor() {
    this.host = h('div', { class: 'view3d-host' });
    this.labels = ['X', 'Y', 'Z'].map((t) => h('span', { class: `axis-label axis-${t.toLowerCase()}`, 'aria-hidden': 'true' }, t));
    this.el = h('div', { class: 'view3d' }, this.host, ...this.labels);
    this.problem = webglProblem();
    this.ready = this.problem ? Promise.resolve(false) : this.init();
  }

  private async init(): Promise<boolean> {
    try {
      const e = (this.e = await loadEngine());
      const { THREE } = e;
      const renderer = new THREE.WebGLRenderer({ antialias: true, preserveDrawingBuffer: true });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      const cv = renderer.domElement;
      cv.className = 'view-canvas';
      cv.tabIndex = 0;
      cv.setAttribute('role', 'img');
      cv.setAttribute('aria-roledescription', 'przestrzeń');
      cv.setAttribute(
        'aria-label',
        'Rysunek 3D. Przeciągnij, aby obracać; prawy przycisk lub dwa palce przesuwają; kółko lub gest przybliża. Klawisze: strzałki obracają, Shift ze strzałkami przesuwa, + i − przybliżają, 0 dopasowuje.',
      );
      this.host.append(cv);
      this.renderer = renderer;
      this.scene = new THREE.Scene();
      const camera = (this.camera = new THREE.PerspectiveCamera(45, 1, 0.5, 2_000_000));
      camera.up.set(0, 0, 1);
      const controls = (this.controls = new e.OrbitControls(camera, cv));
      controls.enableDamping = false;
      controls.screenSpacePanning = true;
      controls.addEventListener('change', () => this.requestRender());
      this.strokes = new THREE.Group();
      this.ghost = new THREE.Group();
      this.grid = new THREE.Group();
      this.turtleMesh = makeTurtle(THREE);
      this.scene.add(this.grid, this.ghost, this.strokes, this.turtleMesh);
      this.bindKeys(cv);
      this.rebuildGrid(200);
      this.resetCamera();
      if (typeof ResizeObserver !== 'undefined') {
        this.resizeObserver = new ResizeObserver(() => this.requestRender());
        this.resizeObserver.observe(this.host);
      }
      this.requestRender();
      return true;
    } catch {
      this.problem = 'Nie udało się uruchomić widoku 3D (WebGL). Tryb 2D działa normalnie.';
      return false;
    }
  }

  destroy() {
    this.resizeObserver?.disconnect();
    this.controls?.dispose();
    this.renderer?.dispose();
  }

  setScene(segments: Segment[], turtle: TurtleView | null) {
    this.segments = segments;
    this.turtle = turtle;
    this.requestRender();
  }

  setTarget(target: Segment[] | null) {
    this.target = target;
    if (this.e && this.ghost) {
      this.ghost.clear();
      if (target?.length) this.ghost.add(this.lines(target, palette().target, 4));
    }
    this.requestRender();
  }

  refreshTheme() {
    this.rebuildGrid(this.gridSize);
    this.setTarget(this.target);
  }

  private gridSize = 200;

  private rebuildGrid(size: number) {
    if (!this.e || !this.grid) return;
    const { THREE } = this.e;
    const c = palette();
    this.gridSize = size;
    this.grid.clear();
    const step = niceStep(size / 10);
    const half = Math.ceil(size / step) * step;
    const g = new THREE.GridHelper(half * 2, Math.round((half * 2) / step), new THREE.Color(c.axis), new THREE.Color(c.grid));
    g.rotation.x = Math.PI / 2; // into the XY plane
    this.grid.add(g);
    const axis = (to: [number, number, number], color: string) => {
      const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, 0), new THREE.Vector3(...to)]);
      return new THREE.Line(geo, new THREE.LineBasicMaterial({ color }));
    };
    const L = half * 0.6;
    this.grid.add(axis([L, 0, 0], c.axisX), axis([0, L, 0], c.axisY), axis([0, 0, L], c.axisZ));
    this.axisLength = L;
    if (this.renderer) {
      this.renderer.setClearColor(new THREE.Color(c.paper), 1);
    }
  }

  private axisLength = 120;

  private lines(segs: Segment[], color: string | null, width: number) {
    const { THREE, LineSegments2, LineSegmentsGeometry, LineMaterial } = this.e!;
    const pos = new Float32Array(segs.length * 6);
    const col = new Float32Array(segs.length * 6);
    const tmp = new THREE.Color();
    segs.forEach((s, i) => {
      pos.set([...s.from, ...s.to], i * 6);
      tmp.set(color ?? s.color);
      col.set([tmp.r, tmp.g, tmp.b, tmp.r, tmp.g, tmp.b], i * 6);
    });
    const geo = new LineSegmentsGeometry();
    geo.setPositions(pos);
    geo.setColors(col);
    const mat = new LineMaterial({ linewidth: width, vertexColors: true, worldUnits: false, transparent: color !== null, opacity: color ? 0.55 : 1 });
    const { w, h: hh } = this.size();
    mat.resolution.set(w, hh);
    return new LineSegments2(geo, mat);
  }

  private rebuildStrokes() {
    if (!this.e || !this.strokes) return;
    if (this.builtRef === this.segments && this.builtCount === this.segments.length) return;
    this.builtRef = this.segments;
    this.builtCount = this.segments.length;
    for (const child of this.strokes.children) {
      const l = child as import('three').Mesh;
      l.geometry.dispose();
      (l.material as import('three').Material).dispose();
    }
    this.strokes.clear();
    const byWidth = new Map<number, Segment[]>();
    for (const s of this.segments) {
      const list = byWidth.get(s.width) ?? [];
      list.push(s);
      byWidth.set(s.width, list);
    }
    for (const [w, list] of byWidth) this.strokes.add(this.lines(list, null, w));
  }

  /** Frame the drawing from the default viewpoint. */
  resetCamera() {
    this.frame(true);
  }

  fit() {
    this.frame(false);
  }

  private frame(fromDefault: boolean) {
    if (!this.e || !this.camera || !this.controls) return;
    const { THREE } = this.e;
    const box = new THREE.Box3();
    box.expandByPoint(new THREE.Vector3(0, 0, 0));
    for (const s of [...this.segments, ...(this.target ?? [])]) {
      box.expandByPoint(new THREE.Vector3(...s.from));
      box.expandByPoint(new THREE.Vector3(...s.to));
    }
    if (this.turtle) box.expandByPoint(new THREE.Vector3(...this.turtle.pos));
    const sphere = box.getBoundingSphere(new THREE.Sphere());
    const r = Math.max(sphere.radius, 40);
    const cam = this.camera;
    const dir = fromDefault
      ? new THREE.Vector3(0.55, -1.2, 0.85).normalize()
      : cam.position.clone().sub(this.controls.target).normalize();
    const dist = (r / Math.sin(((cam.fov / 2) * Math.PI) / 180)) * 1.08;
    this.controls.target.copy(sphere.center);
    cam.position.copy(sphere.center).addScaledVector(dir, dist);
    cam.near = Math.max(0.1, dist / 1000);
    cam.far = dist * 20;
    cam.updateProjectionMatrix();
    this.rebuildGrid(Math.max(200, Math.abs(box.min.x), Math.abs(box.max.x), Math.abs(box.min.y), Math.abs(box.max.y)) * 1.2);
    this.controls.update();
    this.requestRender();
  }

  zoomBy(f: number) {
    if (!this.camera || !this.controls) return;
    const offset = this.camera.position.clone().sub(this.controls.target).multiplyScalar(1 / f);
    this.camera.position.copy(this.controls.target).add(offset);
    this.controls.update();
  }

  async renderNow() {
    await this.ready;
    this.draw();
    await nextFrame();
  }

  async toBlob(): Promise<Blob | null> {
    if (!(await this.ready) || !this.renderer) return null;
    this.draw();
    return new Promise((resolve) => this.renderer!.domElement.toBlob((b) => resolve(b), 'image/png'));
  }

  requestRender() {
    if (this.pending) return;
    this.pending = true;
    nextFrame().then(() => {
      this.pending = false;
      this.draw();
    });
  }

  private size() {
    const r = this.host.getBoundingClientRect();
    return { w: Math.max(1, r.width || 600), h: Math.max(1, r.height || 400) };
  }

  private draw() {
    if (!this.renderer || !this.camera || !this.scene || !this.e) return;
    const { w, h: hh } = this.size();
    const cv = this.renderer.domElement;
    if (cv.width !== Math.round(w * this.renderer.getPixelRatio()) || cv.height !== Math.round(hh * this.renderer.getPixelRatio())) {
      this.renderer.setSize(w, hh, false);
      this.camera.aspect = w / hh;
      this.camera.updateProjectionMatrix();
    }
    this.rebuildStrokes();
    for (const g of [this.strokes, this.ghost])
      g?.children.forEach((l) => ((l as unknown as { material: { resolution: { set(a: number, b: number): void } } }).material.resolution.set(w, hh)));
    const t = this.turtle;
    if (this.turtleMesh) {
      this.turtleMesh.visible = !!t;
      if (t) placeTurtle(this.e.THREE, this.turtleMesh, t, Math.max(6, this.camera.position.distanceTo(this.controls!.target) / 40));
    }
    this.renderer.render(this.scene, this.camera);
    // Axis labels follow the projected axis tips.
    const tips: [number, number, number][] = [[this.axisLength, 0, 0], [0, this.axisLength, 0], [0, 0, this.axisLength]];
    tips.forEach((p, i) => {
      const v = new this.e!.THREE.Vector3(...p).project(this.camera!);
      const label = this.labels[i];
      label.style.display = v.z > 1 ? 'none' : '';
      label.style.transform = `translate(${((v.x + 1) / 2) * w}px, ${((1 - v.y) / 2) * hh}px)`;
    });
  }

  private bindKeys(cv: HTMLCanvasElement) {
    cv.addEventListener('keydown', (e) => {
      const c = this.controls;
      const cam = this.camera;
      if (!c || !cam || !this.e) return;
      const { THREE } = this.e;
      const k = e.key;
      if (k.startsWith('Arrow')) {
        const offset = cam.position.clone().sub(c.target);
        if (e.shiftKey) {
          // Pan in screen space.
          const dist = offset.length() * 0.05;
          const right = new THREE.Vector3().setFromMatrixColumn(cam.matrix, 0);
          const up = new THREE.Vector3().setFromMatrixColumn(cam.matrix, 1);
          const d = k === 'ArrowLeft' ? right.multiplyScalar(-dist) : k === 'ArrowRight' ? right.multiplyScalar(dist) : k === 'ArrowUp' ? up.multiplyScalar(dist) : up.multiplyScalar(-dist);
          cam.position.add(d);
          c.target.add(d);
        } else {
          const sph = new THREE.Spherical().setFromVector3(new THREE.Vector3(offset.x, offset.z, -offset.y));
          // Spherical works Y-up; we mapped Z-up into it.
          const a = Math.PI / 18;
          if (k === 'ArrowLeft') sph.theta -= a;
          if (k === 'ArrowRight') sph.theta += a;
          if (k === 'ArrowUp') sph.phi = Math.max(0.05, sph.phi - a);
          if (k === 'ArrowDown') sph.phi = Math.min(Math.PI - 0.05, sph.phi + a);
          const v = new THREE.Vector3().setFromSpherical(sph);
          cam.position.copy(c.target).add(new THREE.Vector3(v.x, -v.z, v.y));
        }
        c.update();
      } else if (k === '+' || k === '=') this.zoomBy(1.25);
      else if (k === '-' || k === '_') this.zoomBy(0.8);
      else if (k === '0' || k === 'f' || k === 'F') this.fit();
      else return;
      e.preventDefault();
    });
  }
}

