import type { Mode, Segment } from '../lang';
import { palette } from './theme';

/** Project a point for a thumbnail: flat programs from above, spatial ones from the default 3D viewpoint. */
function projector(mode: Mode) {
  if (mode === '2d') return (p: number[]): [number, number] => [p[0], p[1]];
  // Orthographic view along (0.55, -1.2, 0.85) with Z up.
  const d = [0.55, -1.2, 0.85];
  const n = Math.hypot(d[0], d[1], d[2]);
  const f = d.map((v) => v / n);
  const right = [-f[1], f[0], 0].map((v) => v / Math.hypot(f[0], f[1]));
  const up = [f[1] * right[2] - f[2] * right[1], f[2] * right[0] - f[0] * right[2], f[0] * right[1] - f[1] * right[0]];
  return (p: number[]): [number, number] => [
    p[0] * right[0] + p[1] * right[1] + p[2] * right[2],
    -(p[0] * up[0] + p[1] * up[1] + p[2] * up[2]),
  ];
}

/** Draw `segments` fitted into a canvas; used by example cards and challenge targets. */
