import type { Mode, RunResult } from '../lang';
import { MAX_OPS } from '../lang/exec';
import { fmt } from '../lang/lexer';
import type { Challenge, Verdict } from '../content/challenges';
import { createController, type ExecState, type Scheduler, SPEEDS } from './controller';
import { h } from './dom';
import { Editor } from './editor';
import { icon } from './icons';
import { View2D, nextFrame } from './view2d';
import { View3D } from './view3d';

export interface WorkspaceHooks {
  /** The user edited the program text. */
  onEdit(text: string): void;
  onSpeed(level: number): void;
  onShare(): void;
  onSaveFile(): void;
  onOpenFile(file: File): void;
  onExportPng(): void;
  onCheck(): void;
  onLeaveChallenge(): void;
  onRestoreBackup(): void;
  onDismissNotice(): void;
}

const STATUS_TEXT: Record<ExecState['status'], string> = {
  idle: 'Gotowy. Naciśnij „Uruchom”, aby narysować program.',
  running: 'Rysuję…',
  paused: 'Wstrzymano. „Krok” wykona następne polecenie, „Wznów” poprowadzi dalej.',
  done: 'Gotowe.',
  error: '',
};

export class Workspace {
  readonly el: HTMLElement;
  readonly editor: Editor;
  readonly controller;
  mode: Mode = '2d';
  private view2d = new View2D();
  private view3d: View3D | null = null;
  private stage: HTMLDivElement;
  private off3d: HTMLDivElement;
  private status: HTMLParagraphElement;
  private statusAction: HTMLButtonElement;
  private meter: HTMLDivElement;
  private meterFill: HTMLDivElement;
  private meterText: HTMLSpanElement;
  private readout: HTMLSpanElement;
  private buttons: Record<'run' | 'step' | 'pause' | 'reset', HTMLButtonElement>;
  private speed: HTMLInputElement;
  private speedOut: HTMLOutputElement;
  private notice: HTMLDivElement;
  private noticeText: HTMLSpanElement;
  private sharePanel: HTMLDivElement;
  private shareInput: HTMLInputElement;
  private fileInput: HTMLInputElement;
  private banner: HTMLDivElement;
  private bannerTitle: HTMLHeadingElement;
  private bannerTask: HTMLParagraphElement;
  private bannerHint: HTMLParagraphElement;
  private bannerResult: HTMLParagraphElement;
  private ghostToggle: HTMLButtonElement;
  private challenge: Challenge | null = null;
  private showGhost = true;
  private message: string | null = null;
  private liveRegion: HTMLParagraphElement;
  private autoFitPending = false;

  constructor(
    private hooks: WorkspaceHooks,
    scheduler?: Scheduler,
  ) {
    this.controller = createController({ scheduler });
    this.editor = new Editor({ describedBy: 'ws-status', label: 'Program' });

    const btn = (name: string, label: string, ico: Parameters<typeof icon>[0], keys: string, onclick: () => void, cls = 'btn') =>
      h(
        'button',
        { type: 'button', class: cls, 'aria-label': label, title: `${label} (${keys})`, 'aria-keyshortcuts': keys, 'data-action': name, onclick },
        icon(ico),
        h('span', { class: 'btn-label' }, label),
      );
    this.buttons = {
      run: btn('run', 'Uruchom', 'play', 'Control+Enter', () => this.run(), 'btn btn-primary'),
      step: btn('step', 'Krok', 'step', 'Control+Shift+Enter', () => this.step()),
      pause: btn('pause', 'Pauza', 'pause', 'Escape', () => this.togglePause()),
      reset: btn('reset', 'Reset', 'reset', 'Control+Shift+Backspace', () => this.reset(), 'btn btn-quiet'),
    };
    this.speed = h('input', { type: 'range', min: 1, max: 10, step: 1, value: 6, id: 'ws-speed', 'aria-describedby': 'ws-speed-out' });
    this.speedOut = h('output', { id: 'ws-speed-out', for: 'ws-speed', class: 'speed-out' });
    this.speed.addEventListener('input', () => {
      this.setSpeed(Number(this.speed.value));
      this.hooks.onSpeed(Number(this.speed.value));
    });

    const toolbar = h(
      'div',
      { class: 'toolbar', role: 'toolbar', 'aria-label': 'Wykonanie programu' },
      h('div', { class: 'toolbar-group' }, this.buttons.run, this.buttons.step, this.buttons.pause),
      h('label', { class: 'speed', for: 'ws-speed' }, h('span', { class: 'speed-label' }, 'Tempo'), this.speed, this.speedOut),
      h('div', { class: 'toolbar-sep', 'aria-hidden': 'true' }),
      this.buttons.reset,
    );

    // Challenge banner (hidden unless a challenge is active).
    this.bannerTitle = h('h2', { class: 'banner-title', id: 'ws-challenge-title' });
    this.bannerTask = h('p', { class: 'banner-task' });
    this.bannerHint = h('p', { class: 'banner-hint' });
    this.bannerResult = h('p', { class: 'banner-result', role: 'status', 'aria-live': 'polite' });
    this.ghostToggle = h('button', { type: 'button', class: 'btn btn-quiet btn-small', 'aria-pressed': 'true', onclick: () => this.toggleGhost() }, 'Wzór na płótnie');
    this.banner = h(
      'section',
      { class: 'challenge-banner', 'aria-labelledby': 'ws-challenge-title', hidden: true },
      h('div', { class: 'banner-head' }, this.bannerTitle, h('button', { type: 'button', class: 'btn btn-quiet btn-small', onclick: () => this.hooks.onLeaveChallenge() }, icon('close', 16), h('span', {}, 'Zakończ zadanie'))),
      this.bannerTask,
      h('details', { class: 'banner-details' }, h('summary', {}, 'Podpowiedź'), this.bannerHint),
      h(
        'div',
        { class: 'banner-actions' },
        h('button', { type: 'button', class: 'btn btn-challenge', 'data-action': 'check', onclick: () => this.hooks.onCheck() }, icon('check'), h('span', {}, 'Sprawdź')),
        this.ghostToggle,
      ),
      this.bannerResult,
    ) as HTMLDivElement;

    // Notice for draft backups.
    this.noticeText = h('span', {});
    this.notice = h(
      'div',
      { class: 'notice', role: 'status', hidden: true },
      icon('undo', 16),
      this.noticeText,
      h('button', { type: 'button', class: 'btn btn-small', 'data-action': 'restore', onclick: () => this.hooks.onRestoreBackup() }, 'Przywróć szkic'),
      h('button', { type: 'button', class: 'btn btn-quiet btn-small btn-icon', 'aria-label': 'Ukryj komunikat', onclick: () => this.hooks.onDismissNotice() }, icon('close', 16)),
    );

    this.status = h('p', { class: 'status-text', id: 'ws-status' });
    this.statusAction = h('button', { type: 'button', class: 'btn btn-small btn-quiet', hidden: true, onclick: () => this.goToError() }, 'Pokaż w kodzie');
    this.meterFill = h('div', { class: 'meter-fill' });
    this.meterText = h('span', { class: 'meter-text' });
    this.meter = h('div', { class: 'meter', role: 'meter', 'aria-label': 'Wykonane operacje', 'aria-valuemin': 0, 'aria-valuemax': MAX_OPS, 'aria-valuenow': 0 }, h('div', { class: 'meter-track' }, this.meterFill));
    this.liveRegion = h('p', { class: 'sr-only', 'aria-live': 'polite' });

    this.shareInput = h('input', { type: 'text', readonly: true, class: 'share-input', 'aria-label': 'Link do programu' });
    this.sharePanel = h(
      'div',
      { class: 'share-panel', hidden: true },
      h('label', { class: 'share-label' }, 'Link do tego programu', this.shareInput),
      h('button', { type: 'button', class: 'btn btn-small btn-quiet btn-icon', 'aria-label': 'Zamknij link', onclick: () => (this.sharePanel.hidden = true) }, icon('close', 16)),
    );
    this.fileInput = h('input', { type: 'file', accept: '.logo,.txt,text/plain', class: 'sr-only', tabindex: -1, 'aria-hidden': 'true' });
    this.fileInput.addEventListener('change', () => {
      const f = this.fileInput.files?.[0];
      if (f) this.hooks.onOpenFile(f);
      this.fileInput.value = '';
    });
    const fileBtn = (label: string, ico: Parameters<typeof icon>[0], action: string, onclick: () => void) =>
      h('button', { type: 'button', class: 'btn btn-quiet btn-small', 'data-action': action, onclick }, icon(ico, 16), h('span', {}, label));
    const filebar = h(
      'div',
      { class: 'filebar', role: 'group', 'aria-label': 'Plik i udostępnianie' },
      fileBtn('Otwórz plik', 'open', 'open', () => this.fileInput.click()),
      fileBtn('Zapisz .logo', 'save', 'save', () => this.hooks.onSaveFile()),
      fileBtn('Link', 'link', 'share', () => this.hooks.onShare()),
      fileBtn('PNG', 'image', 'png', () => this.hooks.onExportPng()),
      this.fileInput,
    );

    const codePanel = h(
      'section',
      { class: 'panel code-panel', 'aria-label': 'Program' },
      this.banner,
      toolbar,
      this.notice,
      this.editor.el,
      h('div', { class: 'statusbar' }, h('div', { class: 'status-row' }, this.status, this.statusAction), this.meter, this.meterText),
      filebar,
      this.sharePanel,
      h(
        'p',
        { class: 'shortcuts' },
        h('kbd', {}, 'Ctrl'), '+', h('kbd', {}, 'Enter'), ' uruchom · ',
        h('kbd', {}, 'Ctrl'), '+', h('kbd', {}, 'Shift'), '+', h('kbd', {}, 'Enter'), ' krok · ',
        h('kbd', {}, 'Esc'), ' pauza/wznów · ',
        h('kbd', {}, 'Ctrl'), '+', h('kbd', {}, 'Shift'), '+', h('kbd', {}, 'Backspace'), ' reset',
      ),
      this.liveRegion,
    );

    // Canvas panel.
    this.stage = h('div', { class: 'stage' }, this.view2d.canvas);
    this.off3d = h('div', { class: 'off3d', hidden: true, role: 'note' });
    this.readout = h('span', { class: 'readout', 'aria-hidden': 'true' });
    const viewBtn = (label: string, ico: Parameters<typeof icon>[0], action: string, onclick: () => void) =>
      h('button', { type: 'button', class: 'btn btn-icon btn-view', 'aria-label': label, title: label, 'data-action': action, onclick }, icon(ico));
    const viewControls = h(
      'div',
      { class: 'view-controls', role: 'group', 'aria-label': 'Widok' },
      viewBtn('Przybliż', 'zoomIn', 'zoom-in', () => this.view().zoomBy(1.25)),
      viewBtn('Oddal', 'zoomOut', 'zoom-out', () => this.view().zoomBy(0.8)),
      viewBtn('Dopasuj widok do rysunku', 'fit', 'fit', () => this.view().fit()),
      viewBtn('Ustaw kamerę od nowa', 'camera', 'camera', () => (this.mode === '3d' ? this.view3d?.resetCamera() : this.view2d.fit())),
    );
    const canvasPanel = h('section', { class: 'panel canvas-panel', 'aria-label': 'Rysunek' }, this.stage, this.off3d, viewControls, this.readout);

    this.el = h('div', { class: 'workspace' }, codePanel, canvasPanel);

    this.editor.onInput((text) => {
      const s = this.controller.state().status;
      if (s === 'running' || s === 'paused') {
        this.controller.halt();
        this.message = 'Program się zmienił, więc zatrzymałem wykonanie. Uruchom go ponownie, aby zobaczyć nową wersję.';
      } else if (s === 'error') {
        this.message = null;
      }
      this.renderState(this.controller.state());
      this.hooks.onEdit(text);
    });
    this.editor.textarea.addEventListener('keydown', (e) => this.onShortcut(e));
    canvasPanel.addEventListener('keydown', (e) => this.onShortcut(e));
    this.controller.subscribe((s) => this.renderState(s));
    this.setSpeed(6);
    this.renderState(this.controller.state());
  }

  destroy() {
    this.controller.reset();
    this.view2d.destroy();
    this.view3d?.destroy();
  }

  private view() {
    return this.mode === '3d' && this.view3d && !this.view3d.problem ? this.view3d : this.view2d;
  }

  setSpeed(level: number) {
    this.controller.setSpeed(level);
    this.speed.value = String(level);
    const rate = SPEEDS[level - 1];
    const text = rate === Infinity ? 'od razu' : `${fmt(rate)} pol./s`;
    this.speedOut.textContent = text;
    this.speed.setAttribute('aria-valuetext', rate === Infinity ? 'bez animacji' : `${fmt(rate)} poleceń na sekundę`);
  }

  /** Switch between the plane and space. */
  setMode(mode: Mode) {
    this.mode = mode;
    this.controller.reset(mode);
    if (mode === '3d') {
      if (!this.view3d) {
        this.view3d = new View3D();
        this.view3d.ready.then(() => {
          if (this.mode === '3d') this.showStage();
        });
      }
    }
    this.showStage();
    this.message = null;
    this.renderState(this.controller.state());
  }

  private showStage() {
    const v3 = this.view3d;
    if (this.mode === '3d' && v3) {
      if (v3.problem) {
        this.off3d.hidden = false;
        this.off3d.replaceChildren(h('strong', {}, 'Widok 3D jest wyłączony. '), v3.problem);
        this.stage.replaceChildren();
      } else {
        this.off3d.hidden = true;
        if (this.stage.firstChild !== v3.el) this.stage.replaceChildren(v3.el);
        v3.setTarget(this.challenge && this.showGhost ? this.challenge.target() : null);
      }
    } else {
      this.off3d.hidden = true;
      if (this.stage.firstChild !== this.view2d.canvas) this.stage.replaceChildren(this.view2d.canvas);
    }
    this.syncTarget();
    this.drawScene(this.controller.state());
  }

  refreshTheme() {
    this.view2d.refreshTheme();
    this.view3d?.refreshTheme();
  }

  run() {
    this.message = null;
    const st = this.controller.state().status;
    if (st === 'paused') return this.controller.resume();
    if (st === 'running') return;
    this.autoFitPending = true;
    this.controller.run(this.editor.value, this.mode);
  }

  step() {
    this.message = null;
    const st = this.controller.state().status;
    if (st === 'running') this.controller.pause();
    if (st === 'done' || st === 'error' || st === 'idle') this.controller.reset(this.mode);
    this.controller.step(this.editor.value, this.mode);
  }

  togglePause() {
    const st = this.controller.state().status;
    if (st === 'running') this.controller.pause();
    else if (st === 'paused') this.controller.resume();
  }

  reset() {
    this.message = null;
    this.controller.reset(this.mode);
  }

  /** Run to the end without animation, fit, and resolve once drawn. */
  async finish(): Promise<RunResult> {
    this.message = null;
    this.controller.finish(this.editor.value, this.mode);
    const s = this.controller.state();
    if (this.mode === '3d' && this.view3d) await this.view3d.ready;
    this.drawScene(s);
    this.view().fit();
    await this.view().renderNow();
    await nextFrame();
    return { segments: s.status === 'error' && s.segments.length === 0 ? [] : [...s.segments], error: s.error };
  }

  exportPng(): Promise<Blob | null> {
    return this.view().toBlob();
  }

  showShare(url: string) {
    this.sharePanel.hidden = false;
    this.shareInput.value = url;
    this.shareInput.focus();
    this.shareInput.select();
  }

  /** Show a transient message in the status line. */
  say(text: string) {
    this.message = text;
    this.renderState(this.controller.state());
    this.liveRegion.textContent = text;
  }

  showNotice(text: string | null) {
    this.notice.hidden = text === null;
    this.noticeText.textContent = text ?? '';
  }

  setChallenge(c: Challenge | null, solved = false) {
    this.challenge = c;
    this.banner.hidden = !c;
    this.el.classList.toggle('has-challenge', !!c);
    if (c) {
      this.bannerTitle.textContent = `Zadanie: ${c.title}`;
      this.bannerTask.textContent = c.task;
      this.bannerHint.textContent = c.hint;
      this.bannerResult.textContent = solved ? 'To zadanie jest już zaliczone. Możesz je rozwiązać jeszcze raz.' : '';
      this.bannerResult.className = 'banner-result';
    }
    this.syncTarget();
  }

  showVerdict(v: Verdict) {
    this.bannerResult.replaceChildren(icon(v.pass ? 'check' : 'close', 16), h('span', {}, v.reason));
    this.bannerResult.className = `banner-result ${v.pass ? 'is-pass' : 'is-fail'}`;
  }

  private toggleGhost() {
    this.showGhost = !this.showGhost;
    this.ghostToggle.setAttribute('aria-pressed', String(this.showGhost));
    this.syncTarget();
  }

  private syncTarget() {
    const t = this.challenge && this.showGhost ? this.challenge.target() : null;
    this.view2d.setTarget(this.mode === '2d' ? t : null);
    if (this.view3d && !this.view3d.problem) this.view3d.setTarget(this.mode === '3d' ? t : null);
  }

  private goToError() {
    const e = this.controller.state().error;
    if (e) this.editor.focusAt(e.line, e.column);
  }

  private onShortcut(e: KeyboardEvent) {
    const mod = e.ctrlKey || e.metaKey;
    if (mod && e.key === 'Enter') {
      e.preventDefault();
      if (e.shiftKey) this.step();
      else this.run();
    } else if (mod && e.shiftKey && e.key === 'Backspace') {
      e.preventDefault();
      this.reset();
    } else if (e.key === 'Escape' && !mod) {
      const st = this.controller.state().status;
      if (st === 'running' || st === 'paused') {
        e.preventDefault();
        this.togglePause();
      }
    }
  }

  private drawScene(s: ExecState) {
    const turtle = s.status === 'idle' && s.segments.length === 0 ? s.turtle : s.turtle;
    if (this.mode === '3d' && this.view3d && !this.view3d.problem) this.view3d.setScene(s.segments, turtle);
    else this.view2d.setScene(s.segments, turtle);
  }

  private renderState(s: ExecState) {
    this.drawScene(s);
    const active = s.status === 'running' || s.status === 'paused';
    this.editor.setExecLine(active ? s.line : null);
    this.editor.setError(s.status === 'error' && !this.message ? s.error : null);

    const b = this.buttons;
    b.run.disabled = s.status === 'running';
    (b.run.querySelector('.btn-label') as HTMLElement).textContent = s.status === 'paused' ? 'Wznów' : 'Uruchom';
    b.run.setAttribute('aria-label', s.status === 'paused' ? 'Wznów' : 'Uruchom');
    b.pause.disabled = !active;
    (b.pause.querySelector('.btn-label') as HTMLElement).textContent = s.status === 'paused' ? 'Wznów' : 'Pauza';
    b.pause.setAttribute('aria-label', s.status === 'paused' ? 'Wznów (pauza)' : 'Pauza');
    b.pause.setAttribute('aria-pressed', String(s.status === 'paused'));
    b.reset.disabled = s.status === 'idle';

    let text: string;
    if (this.message) text = this.message;
    else if (s.status === 'error' && s.error) {
      text = `Wiersz ${s.error.line}, kolumna ${s.error.column}: ${s.error.message}`;
    } else if (s.status === 'done') {
      const n = s.segments.length;
      text = `Gotowe. Narysowano ${fmt(n)} ${plural(n, 'odcinek', 'odcinki', 'odcinków')}.`;
    } else if (s.status === 'paused' && s.line) text = `Wstrzymano w wierszu ${s.line}. „Krok” wykona następne polecenie.`;
    else text = STATUS_TEXT[s.status];
    this.status.textContent = text;
    this.status.classList.toggle('is-error', s.status === 'error' && !this.message);
    this.statusAction.hidden = !(s.status === 'error' && s.error && !this.message);

    const ratio = Math.min(1, s.ops / MAX_OPS);
    this.meterFill.style.width = `${ratio * 100}%`;
    this.meter.setAttribute('aria-valuenow', String(s.ops));
    this.meter.setAttribute('aria-valuetext', `${fmt(s.ops)} z ${fmt(MAX_OPS)} operacji`);
    this.meterText.textContent = `${fmt(s.ops)} / ${fmt(MAX_OPS)} operacji`;

    const t = s.turtle;
    const r = (v: number) => (Math.round(v * 10) / 10).toLocaleString('pl-PL');
    const heading = (((Math.atan2(t.heading[0], t.heading[1]) * 180) / Math.PI + 360) % 360);
    this.readout.textContent =
      this.mode === '2d'
        ? `x ${r(t.pos[0])}  y ${r(t.pos[1])}  kierunek ${r(heading)}°  ${t.penDown ? 'pisak opuszczony' : 'pisak podniesiony'}`
        : `x ${r(t.pos[0])}  y ${r(t.pos[1])}  z ${r(t.pos[2])}  ${t.penDown ? 'pisak opuszczony' : 'pisak podniesiony'}`;

    if (s.status === 'done' || s.status === 'error') {
      if (this.autoFitPending) {
        this.autoFitPending = false;
        this.view().fit();
      }
      if (!this.message) this.liveRegion.textContent = text;
    }
  }
}

function plural(n: number, one: string, few: string, many: string) {
  if (n === 1) return one;
  const d = n % 10;
  const t = n % 100;
  return d >= 2 && d <= 4 && (t < 12 || t > 14) ? few : many;
}

