import { run, type Mode, type RunResult } from '../lang';
import { EXAMPLES } from '../content/examples';
import type { Scheduler } from './controller';
import { h } from './dom';
import { icon } from './icons';
import { createStore, type Store, type Theme } from './storage';
import { applyTheme } from './theme';
import { Workspace } from './workspace';

export interface AppDeps {
  scheduler?: Scheduler;
  storage?: Storage | null;
}

export interface App {
  open(source: string, mode: Mode): Promise<RunResult>;
  run(source: string, mode: Mode): RunResult;
  destroy(): void;
}

type Route = 'pracownia' | 'przyklady' | 'zadania' | 'pomoc';

const NAV: { route: Route; label: string; icon: Parameters<typeof icon>[0] }[] = [
  { route: 'pracownia', label: 'Pracownia', icon: 'pen' },
  { route: 'przyklady', label: 'Przykłady', icon: 'shapes' },
  { route: 'zadania', label: 'Zadania', icon: 'trophy' },
  { route: 'pomoc', label: 'Pomoc', icon: 'book' },
];

const THEME_LABEL: Record<Theme, string> = { auto: 'Motyw: jak w systemie', light: 'Motyw: jasny', dark: 'Motyw: ciemny' };

export function mountApp(root: HTMLElement, deps: AppDeps = {}): App {
  const store: Store = createStore(deps.storage === undefined ? undefined : deps.storage);
  const cleanups: (() => void)[] = [];
  let mode: Mode = store.mode();
  let theme: Theme = store.theme();

  const ws = new Workspace(
    {
      onEdit: (text) => store.setDraft(mode, text),
      onSpeed: (s) => store.setSpeed(s),
      onShare: () => {},
      onSaveFile: () => {},
      onOpenFile: () => {},
      onExportPng: () => {},
      onCheck: () => {},
      onLeaveChallenge: () => {},
      onRestoreBackup: () => {},
      onDismissNotice: () => ws.showNotice(null),
    },
    deps.scheduler,
  );
  ws.setSpeed(store.speed());

  // Header.
  const modeButtons = (['2d', '3d'] as Mode[]).map((m) =>
    h('button', { type: 'button', class: 'seg-btn', 'aria-pressed': 'false', 'data-mode': m, onclick: () => switchMode(m) }, m.toUpperCase()),
  );
  const themeButton = h('button', { type: 'button', class: 'btn btn-icon btn-quiet', onclick: () => cycleTheme() });
  const navLinks = NAV.map((n) =>
    h('a', { href: `#/${n.route === 'pracownia' ? '' : n.route}`, class: `nav-link nav-${n.route}`, 'data-route': n.route }, icon(n.icon, 18), h('span', {}, n.label)),
  );
  const header = h(
    'header',
    { class: 'topbar' },
    h('a', { href: '#/', class: 'brand', 'aria-label': 'Logomocja — pracownia' }, brandMark(), h('span', { class: 'brand-name' }, 'Logomocja')),
    h('nav', { class: 'nav', 'aria-label': 'Sekcje' }, ...navLinks),
    h('div', { class: 'topbar-tools' }, h('div', { class: 'seg', role: 'group', 'aria-label': 'Tryb rysowania' }, ...modeButtons), themeButton),
  );

  const pages: Record<Route, HTMLElement> = {
    pracownia: h('div', { class: 'page page-pracownia', 'data-page': 'pracownia' }, ws.el),
    przyklady: h('div', { class: 'page page-przyklady', 'data-page': 'przyklady' }),
    zadania: h('div', { class: 'page page-zadania', 'data-page': 'zadania' }),
    pomoc: h('div', { class: 'page page-pomoc', 'data-page': 'pomoc' }),
  };
  const main = h('main', { class: 'main', id: 'tresc', tabindex: -1 }, ...Object.values(pages));
  const skip = h('a', { href: '#tresc', class: 'skip-link', onclick: (e: Event) => { e.preventDefault(); main.focus(); } }, 'Przejdź do treści');
  root.classList.add('app');
  root.replaceChildren(skip, header, main);

  function renderMode() {
    modeButtons.forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.mode === mode)));
  }

  function switchMode(m: Mode, opts: { keepText?: boolean } = {}) {
    if (m !== mode || !opts.keepText) {
      mode = m;
      store.setMode(m);
      ws.setMode(m);
      if (!opts.keepText) ws.editor.value = draftFor(m);
    }
    renderMode();
  }

  function draftFor(m: Mode): string {
    return store.draft(m) ?? EXAMPLES.find((e) => e.mode === m)!.source;
  }

  function cycleTheme() {
    theme = theme === 'auto' ? 'light' : theme === 'light' ? 'dark' : 'auto';
    store.setTheme(theme);
    renderTheme();
  }

  function renderTheme() {
    const resolved = applyTheme(theme);
    themeButton.replaceChildren(icon(theme === 'auto' ? 'auto' : resolved === 'dark' ? 'moon' : 'sun'));
    themeButton.setAttribute('aria-label', THEME_LABEL[theme]);
    themeButton.title = `${THEME_LABEL[theme]} (kliknij, aby zmienić)`;
    ws.refreshTheme();
  }
  const mq = typeof matchMedia === 'function' ? matchMedia('(prefers-color-scheme: dark)') : null;
  const onSystemTheme = () => theme === 'auto' && renderTheme();
  mq?.addEventListener?.('change', onSystemTheme);
  cleanups.push(() => mq?.removeEventListener?.('change', onSystemTheme));

  // Routing.
  function currentRoute(): Route {
    const path = location.hash.replace(/^#\/?/, '').split(/[/?]/)[0];
    return (NAV.find((n) => n.route === path)?.route ?? 'pracownia') as Route;
  }
  function showRoute(r: Route) {
    for (const [k, el] of Object.entries(pages)) el.hidden = k !== r;
    navLinks.forEach((a) => {
      if (a.dataset.route === r) a.setAttribute('aria-current', 'page');
      else a.removeAttribute('aria-current');
    });
    root.dataset.section = r;
  }
  const onHash = () => showRoute(currentRoute());
  window.addEventListener('hashchange', onHash);
  cleanups.push(() => window.removeEventListener('hashchange', onHash));

  function go(r: Route) {
    const target = r === 'pracownia' ? '#/' : `#/${r}`;
    if (location.hash !== target) history.pushState(null, '', target);
    showRoute(r);
  }

  // Start.
  renderTheme();
  ws.setMode(mode);
  ws.editor.value = draftFor(mode);
  renderMode();
  showRoute(currentRoute());

  return {
    run,
    async open(source: string, m: Mode) {
      switchMode(m, { keepText: true });
      ws.editor.value = source;
      store.setDraft(m, source);
      go('pracownia');
      return ws.finish();
    },
    destroy() {
      cleanups.forEach((c) => c());
      ws.destroy();
      root.replaceChildren();
    },
  };
}

/** The wordmark's cut-out: an eight-petal wycinanka star. */
function brandMark(): SVGElement {
  const ns = 'http://www.w3.org/2000/svg';
  const s = document.createElementNS(ns, 'svg');
  s.setAttribute('viewBox', '-12 -12 24 24');
  s.setAttribute('width', '26');
  s.setAttribute('height', '26');
  s.setAttribute('aria-hidden', 'true');
  s.classList.add('brand-mark');
  for (let i = 0; i < 8; i++) {
    const p = document.createElementNS(ns, 'path');
    p.setAttribute('d', 'M0 -2 C 2.4 -4.5, 2.4 -8.5, 0 -11.5 C -2.4 -8.5, -2.4 -4.5, 0 -2 Z');
    p.setAttribute('transform', `rotate(${i * 45})`);
    p.setAttribute('class', `petal-${i % 4}`);
    s.append(p);
  }
  const c = document.createElementNS(ns, 'circle');
  c.setAttribute('r', '2.6');
  c.setAttribute('class', 'brand-core');
  s.append(c);
  return s;
}

