  test('Krok highlights each executed line; Wznów finishes; Reset clears', () => {
    mount();
    type('np 10\npw 90\nnp 20');
    button(/^Krok$/).click();
    expect(execLine()).toBe('1');
    button(/^Krok$/).click();
    expect(execLine()).toBe('2');
    expect(status()).toMatch(/wierszu 2/);
