import { run, type Mode } from '../lang';
import { EXAMPLES, type Example } from '../content/examples';
import { codeBlock } from './code';
import { h } from './dom';
import { icon } from './icons';
import { drawThumb } from './thumb';

const MODE_NAME: Record<Mode, string> = { '2d': '2D · płaszczyzna', '3d': '3D · przestrzeń' };

/** The examples roster: one card per standard program. */
export function examplesPage(onLoad: (e: Example) => void) {
  const thumbs: { canvas: HTMLCanvasElement; e: Example }[] = [];
  const cards = EXAMPLES.map((e) => {
    const canvas = h('canvas', { class: 'thumb', 'aria-hidden': 'true' });
    thumbs.push({ canvas, e });
    return h(
      'article',
      { class: `example-card mode-${e.mode}`, 'aria-labelledby': `ex-${e.id}` },
      h('div', { class: 'card-art' }, canvas),
      h(
        'div',
        { class: 'card-body' },
        h('div', { class: 'card-plate' }, h('h2', { class: 'card-title', id: `ex-${e.id}` }, e.name), h('span', { class: `chip chip-${e.mode}` }, MODE_NAME[e.mode])),
        h('p', { class: 'card-text' }, e.tagline),
        h('details', { class: 'card-code' }, h('summary', {}, 'Kod programu'), codeBlock(e.source)),
        h(
          'button',
          { type: 'button', class: 'btn btn-primary btn-small', 'aria-label': `Wczytaj przykład ${e.name}`, onclick: () => onLoad(e) },
          icon('play', 16),
          h('span', {}, 'Wczytaj i uruchom'),
        ),
      ),
    );
  });
  const el = h(
    'div',
    { class: 'page-inner' },
    h('header', { class: 'page-head' }, h('h1', {}, 'Przykłady'), h('p', { class: 'lead' }, 'Trzynaście programów do obejrzenia i przerobienia. Wczytany przykład trafia do pracowni we właściwym trybie; Twój szkic zostaje zachowany.')),
    h('div', { class: 'card-grid' }, ...cards),
  );
  let drawn = false;
  return {
    el,
    /** Draw thumbnails once the page is visible (they need layout). */
    shown() {
      if (drawn) return;
      drawn = true;
      for (const { canvas, e } of thumbs) drawThumb(canvas, run(e.source, e.mode).segments, e.mode);
    },
    refresh() {
      drawn = false;
    },
  };
}
EOF
