import type { Mode } from '../lang';

/** UTF-8 → base64url. */
export function encodeText(text: string): string {
  const bytes = new TextEncoder().encode(text);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/** base64url or base64 → UTF-8; null when malformed. */
export function decodeText(code: string): string | null {
  try {
    let b = code.replace(/ /g, '+').replace(/-/g, '+').replace(/_/g, '/');
    while (b.length % 4) b += '=';
    const bin = atob(b);
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    return null;
  }
}

/** The hash part of a permalink. */
export function permalinkHash(source: string, mode: Mode): string {
  return `#/?tryb=${mode}&kod=${encodeText(source)}`;
}

/** Read a program from a permalink hash, if it carries one. */
export function readPermalink(hash: string): { source: string; mode: Mode } | null {
  const q = hash.indexOf('?');
  if (q < 0) return null;
  const params = new URLSearchParams(hash.slice(q + 1));
  const code = params.get('kod');
  if (code === null) return null;
  const source = decodeText(code);
  if (source === null) return null;
  return { source, mode: params.get('tryb') === '3d' ? '3d' : '2d' };
}
