import { CHALLENGES, type Challenge } from '../content/challenges';
import type { Progress } from './storage';
import { rosette } from './rosette';

/** The challenges list with the large progress rosette. */
export function challengesPage(opts: { onSolve: (c: Challenge) => void; onResetProgress: () => void }) {
  const el = h('div', { class: 'page-inner' });
  let progress: Record<string, Progress> = {};
  let armed = false;
  const thumbs: { canvas: HTMLCanvasElement; c: Challenge }[] = [];

  function render() {
    thumbs.length = 0;
    const solvedFlags = CHALLENGES.map((c) => !!progress[c.id]?.solved);
    const count = solvedFlags.filter(Boolean).length;
    const cards = CHALLENGES.map((c, i) => {
      const canvas = h('canvas', { class: 'thumb', 'aria-hidden': 'true' });
      thumbs.push({ canvas, c });
      const solved = solvedFlags[i];
      return h(
        'article',
        { class: `challenge-card${solved ? ' is-solved' : ''}`, 'aria-labelledby': `ch-${c.id}` },
        h('div', { class: 'card-art' }, canvas),
        h(
          'div',
          { class: 'card-body' },
          h(
            'div',
            { class: 'card-plate' },
            h('h2', { class: 'card-title', id: `ch-${c.id}` }, c.title),
            h('span', { class: `chip chip-${c.mode}` }, c.mode.toUpperCase()),
          ),
          h('p', { class: 'card-text' }, c.task),
          h('p', { class: `challenge-status${solved ? ' is-solved' : ''}` }, solved ? icon('check', 16) : null, solved ? 'Zaliczone' : 'Do zrobienia'),
          h(
            'button',
            { type: 'button', class: 'btn btn-challenge btn-small', 'aria-label': `Rozwiąż zadanie ${c.title}`, onclick: () => opts.onSolve(c) },
            h('span', {}, solved ? 'Rozwiąż ponownie' : 'Rozwiąż'),
          ),
        ),
      );
    });
    const resetBtn = h(
      'button',
      {
        type: 'button',
        class: `btn btn-danger btn-small${armed ? ' is-armed' : ''}`,
        onclick: () => {
          if (!armed) {
            armed = true;
            render();
            (el.querySelector('.btn-danger') as HTMLElement)?.focus();
          } else {
            armed = false;
            opts.onResetProgress();
          }
        },
        onblur: () => {
          if (armed) {
            armed = false;
            setTimeout(render);
          }
        },
      },
      armed ? 'Na pewno? Kliknij ponownie, aby wyzerować' : 'Wyzeruj postęp',
    );
    el.replaceChildren(
      h(
        'header',
        { class: 'page-head page-head-rosette' },
        rosette(CHALLENGES.length, solvedFlags, 112),
        h(
          'div',
          {},
          h('h1', {}, 'Zadania'),
          h('p', { class: 'lead' }, `Zaliczone: ${count} z ${CHALLENGES.length}. Każde zadanie pokazuje wzór; Twój program jest porównywany z nim automatycznie (z tolerancją ${2} jednostek, kolejność i kierunek linii nie mają znaczenia).`),
        ),
      ),
      h('div', { class: 'card-grid' }, ...cards),
      h('div', { class: 'danger-zone' }, h('p', {}, 'Postęp jest zapisany tylko w tej przeglądarce.'), resetBtn),
    );
  }
  return {
    el,
    update(p: Record<string, Progress>) {
      progress = p;
      render();
    },
    shown() {
      for (const { canvas, c } of thumbs) drawThumb(canvas, c.target(), c.mode, { dashed: false });
    },
  };
}
