import { ALIASES } from '../src/lang/keywords';

describe('command reference', () => {
  test('documents every command alias, the language topics and the limits', () => {
    mount();
    goTo('#/pomoc');
    expect(visiblePage()).toBe('pomoc');
    const text = root.querySelector('[data-page="pomoc"]')!.textContent!;
