      expect(headings.some((x) => x!.includes(topic))).toBe(true);
    }
  });

  test('every command has an example that runs and can be tried in the right mode', () => {
    mount();
    goTo('#/pomoc');
    const tries = [...root.querySelectorAll<HTMLButtonElement>('[data-page="pomoc"] button[data-try]')];
    expect(tries.length).toBeGreaterThanOrEqual(Object.keys(ALIASES).length);
    for (const b of tries) {
      const r = run(b.dataset.source!, b.dataset.mode as '2d' | '3d');
      expect(r.error, b.dataset.source).toBeNull();
    }
    const pitch = tries.find((b) => /góra|gora/.test(b.dataset.source!))!;
    pitch.click();
    expect(visiblePage()).toBe('pracownia');
    expect(modeOn()).toBe('3D');
    expect(editor().value).toBe(pitch.dataset.source);
  });

  test('a section of the reference survives a refresh', () => {
    location.hash = '#/pomoc/procedury';
    mount();
    expect(visiblePage()).toBe('pomoc');
  });
});
