import { mountApp } from './app/app';
import { run, type Mode } from './lang';

declare const __APP_VERSION__: string;

const root = document.getElementById('app')!;
const app = mountApp(root);

const checkMode = (mode: Mode) => {
  if (mode !== '2d' && mode !== '3d') throw new TypeError('mode musi mieć wartość "2d" albo "3d"');
  return mode;
};

/** Testing hook: interpret without the UI, or load into the editor and draw. */
Object.defineProperty(window, 'logomocja', {
  value: Object.freeze({
    version: __APP_VERSION__,
    run: (source: string, mode: Mode) => run(String(source), checkMode(mode)),
    open: (source: string, mode: Mode) => app.open(String(source), checkMode(mode)),
  }),
  configurable: true,
});
EOF
