input.content:
/* Logomocja — cut-paper workspace (wycinanki łowickie).
   Flat saturated layers on a white or black sheet; one hue per section; vermilion only for errors. */

:root {
  --font-ui: 'Lexend', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-code: 'JetBrains Mono', ui-monospace, 'Cascadia Mono', Menlo, Consolas, monospace;

  /* Sheet and ink (light: white paper). */
  --ground: #f2f4ef;
  --sheet: #ffffff;
  --paper: #ffffff;
  --ink: #161a17;
  --ink-2: #4a524c;
  --ink-3: #6c756d;
  --line: #d7dcd3;
  --line-strong: #b9c0b6;
  --tint: #eef1ea;

  /* Section hues: the wycinanka wheel. */
  --hue-pracownia: #187a35;
  --hue-przyklady: #f2a516;
  --hue-zadania: #c8186e;
  --hue-pomoc: #2346a8;
  --hue-violet: #6b3fa0;
  --on-pracownia: #ffffff;
  --on-przyklady: #161a17;
  --on-zadania: #ffffff;
  --on-pomoc: #ffffff;
  --tint-pracownia: #e6f2e9;
  --tint-przyklady: #fdf1d6;
  --tint-zadania: #fbe4ef;
  --tint-pomoc: #e5ebf8;

  /* Errors only. */
  --vermilion: #d63a1c;
  --vermilion-text: #b42f15;
  --vermilion-tint: #fde7e1;

  --focus: #2346a8;
  --canvas-grid: #eceee8;
  --canvas-axis: #b3bbb0;
  --canvas-target: rgba(200, 24, 110, 0.3);

  /* Syntax. */
  --syn-cmd: #2346a8;
  --syn-num: #9a4f00;
  --syn-name: #6b3fa0;
  --syn-str: #b0145f;
  --syn-comment: #6c756d;
  --syn-bracket: #187a35;
  --syn-op: #4a524c;
  --syn-def: #187a35;

  --radius: 12px;
  --radius-s: 8px;
  --code-size: 14px;
  --code-lh: 22px;
  --bar-h: 56px;

  --section-hue: var(--hue-pracownia);
  --section-on: var(--on-pracownia);
  --section-tint: var(--tint-pracownia);

  color-scheme: light;
}

:root[data-theme='dark'] {
  /* Black paper. */
  --ground: #0b0c0b;
  --sheet: #141614;
  --paper: #0f110f;
  --ink: #f1f3ed;
  --ink-2: #b2b9b0;
  --ink-3: #8c948a;
  --line: #2b302b;
  --line-strong: #434a42;
  --tint: #1b1e1b;

  --hue-pracownia: #3fbf68;
  --hue-przyklady: #f5b335;
  --hue-zadania: #f0559c;
  --hue-pomoc: #7f9cf5;
  --hue-violet: #b18ae8;
  --on-pracownia: #0b0c0b;
  --on-przyklady: #0b0c0b;
  --on-zadania: #0b0c0b;
  --on-pomoc: #0b0c0b;
  --tint-pracownia: #14261a;
  --tint-przyklady: #2b2210;
  --tint-zadania: #2d1220;
  --tint-pomoc: #161d33;

  --vermilion: #ff6b4a;
  --vermilion-text: #ff8a6e;
  --vermilion-tint: #33160f;

  --focus: #9db4ff;
  --canvas-grid: #1b1f1b;
  --canvas-axis: #3a423a;
  --canvas-target: rgba(240, 85, 156, 0.38);

  --syn-cmd: #8fa8ff;
  --syn-num: #f5b335;
  --syn-name: #c9a6f5;
  --syn-str: #ff7cb5;
  --syn-comment: #8c948a;
  --syn-bracket: #5fd283;
  --syn-op: #b2b9b0;
  --syn-def: #5fd283;

  color-scheme: dark;
}

.app[data-section='przyklady'] { --section-hue: var(--hue-przyklady); --section-on: var(--on-przyklady); --section-tint: var(--tint-przyklady); }
.app[data-section='zadania'] { --section-hue: var(--hue-zadania); --section-on: var(--on-zadania); --section-tint: var(--tint-zadania); }
.app[data-section='pomoc'] { --section-hue: var(--hue-pomoc); --section-on: var(--on-pomoc); --section-tint: var(--tint-pomoc); }

*,
*::before,
*::after { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--ground);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection { background: color-mix(in srgb, var(--section-hue) 28%, transparent); }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

a { color: var(--hue-pomoc); text-underline-offset: 3px; }

code, kbd, pre { font-family: var(--font-code); }

kbd {
  display: inline-block;
  font-size: 11px;
  line-height: 16px;
  padding: 0 5px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--sheet);
  color: var(--ink-2);
}

.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%);
  white-space: nowrap; border: 0; padding: 0; margin: -1px;
}

.skip-link {
  position: absolute; left: 12px; top: -60px; z-index: 30;
  background: var(--sheet); color: var(--ink);
  padding: 8px 14px; border-radius: var(--radius-s); border: 2px solid var(--focus);
}
.skip-link:focus { top: 8px; }

/* ---------- Shell ---------- */

.app {
  display: grid;
  grid-template-rows: auto 1fr;
  height: 100vh;
  height: 100dvh;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  height: var(--bar-h);
  padding: 0 16px;
  background: var(--sheet);
  /* The current section's layer runs under the whole bar. */
  border-bottom: 4px solid var(--section-hue);
  position: relative;
  z-index: 5;
}

.brand {
  display: flex; align-items: center; gap: 10px;
  color: var(--ink); text-decoration: none;
  font-weight: 600; font-size: 18px; letter-spacing: -0.01em;
  padding: 4px 6px; margin-left: -6px; border-radius: var(--radius-s);
}
.brand-mark .petal-0 { fill: var(--hue-pracownia); }
.brand-mark .petal-1 { fill: var(--hue-przyklady); }
.brand-mark .petal-2 { fill: var(--hue-zadania); }
.brand-mark .petal-3 { fill: var(--hue-pomoc); }
.brand-mark .brand-core { fill: var(--ink); }

.nav { display: flex; gap: 4px; align-self: stretch; align-items: flex-end; }

.nav-link {
  display: flex; align-items: center; gap: 8px;
  height: 40px; padding: 0 14px;
  border-radius: var(--radius-s) var(--radius-s) 0 0;
  color: var(--ink-2); text-decoration: none; font-weight: 500; font-size: 14px;
  transition: background-color 160ms ease-out, color 160ms ease-out;
}
.nav-link:hover { background: var(--tint); color: var(--ink); }
.nav-link[aria-current='page'] { background: var(--section-hue); color: var(--section-on); }
.nav-link[aria-current='page'] .icon { opacity: 1; }
.nav-link .icon { opacity: 0.8; }

.topbar-tools { margin-left: auto; display: flex; align-items: center; gap: 10px; }

.progress-link {
  display: grid; place-items: center;
  width: 40px; height: 40px; border-radius: 50%;
}
.progress-link:hover { background: var(--tint); }

.seg {
  display: inline-flex;
  padding: 3px;
  border-radius: 10px;
  background: var(--tint);
  border: 1px solid var(--line);
}
.seg-btn {
  font: inherit; font-size: 13px; font-weight: 600; letter-spacing: 0.02em;
  min-width: 44px; height: 32px; padding: 0 10px;
  border: 0; border-radius: 7px;
  background: transparent; color: var(--ink-2); cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.seg-btn:hover { color: var(--ink); }
.seg-btn[aria-pressed='true'] { background: var(--ink); color: var(--sheet); }

.main { min-height: 0; overflow: auto; outline: none; }
.page[hidden] { display: none !important; }
.page-pracownia { height: 100%; }

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font: inherit; font-size: 14px; font-weight: 500;
  height: 38px; padding: 0 14px;
  border-radius: var(--radius-s);
  border: 1px solid var(--line-strong);
  background: var(--sheet); color: var(--ink);
  cursor: pointer; white-space: nowrap;
  transition: background-color 150ms ease-out, border-color 150ms ease-out, color 150ms ease-out, transform 120ms ease-out;
}
.btn:hover:not(:disabled) { background: var(--tint); border-color: var(--ink-3); }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn .icon { flex: none; }

.btn-primary { background: var(--hue-pracownia); border-color: var(--hue-pracownia); color: var(--on-pracownia); }
.btn-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-pracownia) 86%, var(--ink)); border-color: transparent; }
.page-przyklady .btn-primary { background: var(--hue-przyklady); border-color: var(--hue-przyklady); color: var(--on-przyklady); }
.page-przyklady .btn-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-przyklady) 86%, var(--ink)); }

.btn-challenge { background: var(--hue-zadania); border-color: var(--hue-zadania); color: var(--on-zadania); }
.btn-challenge:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-zadania) 86%, var(--ink)); border-color: transparent; }

.btn-quiet { background: transparent; border-color: transparent; color: var(--ink-2); }
.btn-quiet:hover:not(:disabled) { color: var(--ink); background: var(--tint); border-color: transparent; }

.btn-danger { color: var(--vermilion-text); border-color: color-mix(in srgb, var(--vermilion) 45%, var(--line)); background: transparent; }
.btn-danger.is-armed { background: var(--vermilion); color: #fff; border-color: var(--vermilion); }

.btn-small { height: 32px; padding: 0 10px; font-size: 13px; gap: 6px; }
.btn-icon { width: 38px; padding: 0; }
.btn-small.btn-icon { width: 32px; }

/* ---------- Workspace ---------- */

.workspace {
  display: grid;
  grid-template-columns: minmax(360px, 42%) minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
  height: 100%;
  min-height: 0;
}

.panel {
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}

.code-panel { display: flex; flex-direction: column; }

.toolbar {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
}
.toolbar-group { display: flex; gap: 6px; }
.toolbar-sep { flex: 1; }
.btn-primary[data-action='run'] { min-width: 112px; }

.speed { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--ink-2); }
.speed input { width: 96px; accent-color: var(--hue-pracownia); }
.speed-out { min-width: 7.5ch; font-variant-numeric: tabular-nums; color: var(--ink); font-size: 12px; }

.notice {
  display: flex; align-items: center; gap: 10px;
  margin: 10px 12px 0;
  padding: 6px 6px 6px 12px;
  background: var(--tint-przyklady);
  border-radius: var(--radius-s);
  font-size: 13px;
}
.notice[hidden] { display: none; }
.notice > span { flex: 1; }

/* Editor */
.editor {
  flex: 1;
  min-height: 160px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  overflow: hidden;
  position: relative;
  font-family: var(--font-code);
  font-size: var(--code-size);
  line-height: var(--code-lh);
  font-variant-ligatures: none;
  tab-size: 2;
}
.editor-gutter {
  padding: 12px 10px 12px 14px;
  min-width: 4ch;
  text-align: right;
  color: var(--ink-3);
  font-variant-numeric: tabular-nums;
  user-select: none;
  background: var(--sheet);
  border-right: 1px solid var(--line);
  position: relative; z-index: 2;
}
.gutter-line { height: var(--code-lh); padding-right: 2px; border-radius: 4px; }
.gutter-line.is-exec { background: var(--hue-przyklady); color: var(--on-przyklady); font-weight: 600; }
.gutter-line.is-error { background: var(--vermilion); color: #fff; font-weight: 600; }

.editor-code { position: relative; min-width: 0; overflow: hidden; }
.editor-layer, .editor-input {
  margin: 0;
  padding: 12px 16px 12px 12px;
  font: inherit;
  line-height: inherit;
  letter-spacing: 0;
  white-space: pre;
  tab-size: inherit;
}
.editor-layer {
  position: absolute; inset: 0 auto auto 0;
  min-width: 100%;
  pointer-events: none;
  color: var(--ink);
}
.editor-line { height: var(--code-lh); white-space: pre; border-radius: 3px; }
.editor-line.is-exec { background: var(--tint-przyklady); box-shadow: inset 3px 0 0 var(--hue-przyklady); }
.editor-line.is-error { background: var(--vermilion-tint); }
.editor-input {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  border: 0; outline: none; resize: none;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  overflow: auto;
}
.editor-input::selection { background: color-mix(in srgb, var(--hue-pomoc) 26%, transparent); color: transparent; }
.editor:focus-within { box-shadow: inset 0 0 0 2px var(--focus); }

.t-cmd { color: var(--syn-cmd); font-weight: 500; }
.t-num { color: var(--syn-num); }
.t-name { color: var(--syn-name); }
.t-str { color: var(--syn-str); }
.t-str[style*='--swatch'] { border-bottom: 3px solid var(--swatch); }
.t-comment { color: var(--syn-comment); font-style: italic; }
.t-bracket { color: var(--syn-bracket); font-weight: 600; }
.t-op { color: var(--syn-op); }
.t-def { color: var(--syn-def); font-weight: 600; }
.t-value { color: var(--syn-name); font-style: italic; }

.error-token {
  background: transparent; color: inherit;
  text-decoration: underline wavy var(--vermilion);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 4px;
}
.error-caret { box-shadow: inset 2px 0 0 var(--vermilion); }
.error-flag {
  display: inline-block;
  margin-left: 3ch;
  padding: 0 8px;
  line-height: 20px;
  border-radius: 4px;
  background: var(--vermilion);
  color: #fff;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  vertical-align: 1px;
}
:root[data-theme='dark'] .error-flag { color: #160704; }

.statusbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 12px;
  padding: 10px 12px 8px;
  border-top: 1px solid var(--line);
}
.status-row { display: flex; align-items: flex-start; gap: 8px; min-height: 22px; grid-column: 1 / -1; }
.status-text { margin: 0; font-size: 13px; color: var(--ink-2); flex: 1; }
.status-text.is-error { color: var(--vermilion-text); font-weight: 500; }
.status-row .btn { margin-top: -4px; }
.meter { grid-column: 1; align-self: center; margin-top: 6px; }
.meter-track { height: 4px; border-radius: 2px; background: var(--tint); overflow: hidden; }
.meter-fill { height: 100%; width: 0; background: var(--hue-pracownia); transition: width 120ms linear; }
.meter-text { grid-column: 2; margin-top: 6px; font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; }

.filebar { display: flex; flex-wrap: wrap; gap: 2px; padding: 4px 8px; border-top: 1px solid var(--line); }

.share-panel { display: flex; align-items: flex-end; gap: 6px; padding: 0 12px 10px; }
.share-panel[hidden] { display: none; }
.share-label { flex: 1; display: grid; gap: 4px; font-size: 12px; color: var(--ink-2); }
.share-input {
  font: inherit; font-family: var(--font-code); font-size: 12px;
  height: 32px; padding: 0 8px; width: 100%;
  border: 1px solid var(--line-strong); border-radius: 6px;
  background: var(--paper); color: var(--ink);
}

.shortcuts { margin: 0; padding: 6px 12px 10px; font-size: 11px; color: var(--ink-3); }

/* Challenge banner: the fuchsia layer. */
.challenge-banner {
  padding: 12px 14px;
  background: var(--tint-zadania);
  border-bottom: 3px solid var(--hue-zadania);
  display: grid; gap: 6px;
}
.challenge-banner[hidden] { display: none; }
.banner-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.banner-title { margin: 0; font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.banner-task { margin: 0; font-size: 14px; max-width: 70ch; }
.banner-details { font-size: 13px; color: var(--ink-2); }
.banner-details summary { cursor: pointer; width: fit-content; border-radius: 4px; }
.banner-hint { margin: 4px 0 0; font-family: var(--font-code); font-size: 12.5px; }
.banner-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.banner-actions .btn-quiet[aria-pressed='true'] { color: var(--ink); background: color-mix(in srgb, var(--hue-zadania) 14%, transparent); }
.banner-result { margin: 0; display: flex; align-items: flex-start; gap: 6px; font-size: 14px; font-weight: 500; min-height: 0; }
.banner-result:empty { display: none; }
.banner-result .icon { margin-top: 3px; flex: none; }
.banner-result.is-pass { color: var(--hue-pracownia); }
:root:not([data-theme='dark']) .banner-result.is-pass { color: #146a2d; }
.banner-result.is-fail { color: var(--ink); }
.banner-result.is-fail .icon { color: var(--hue-zadania); }

/* Canvas panel */
.canvas-panel { position: relative; background: var(--paper); }
.stage, .view3d, .view3d-host { position: absolute; inset: 0; }
.view-canvas { display: block; width: 100%; height: 100%; touch-action: none; cursor: grab; }
.view-canvas:active { cursor: grabbing; }
.view-canvas:focus-visible { outline-offset: -3px; }
.axis-label {
  position: absolute; left: 0; top: 0;
  margin: -9px 0 0 6px;
  font-size: 12px; font-weight: 600;
  pointer-events: none;
}
.axis-x { color: var(--hue-zadania); }
.axis-y { color: var(--hue-pracownia); }
.axis-z { color: var(--hue-pomoc); }

.off3d {
  position: absolute; inset: 0;
  display: grid; place-content: center;
  padding: 32px; max-width: 560px; margin: auto;
  text-align: center; font-size: 14px; color: var(--ink-2);
}
.off3d[hidden] { display: none; }
.off3d strong { display: block; color: var(--ink); font-size: 16px; margin-bottom: 6px; }

.view-controls {
  position: absolute; right: 12px; bottom: 12px;
  display: flex; gap: 4px; padding: 4px;
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.btn-view { border-color: transparent; height: 36px; width: 36px; }
.workspace:not(.is-3d) [data-action='camera'] { display: none; }

.readout {
  position: absolute; left: 12px; bottom: 14px;
  padding: 4px 8px; border-radius: 6px;
  background: color-mix(in srgb, var(--sheet) 88%, transparent);
  font-family: var(--font-code); font-size: 11.5px; color: var(--ink-2);
  font-variant-numeric: tabular-nums; white-space: pre;
  pointer-events: none;
}

/* ---------- Pages ---------- */

.page-inner { max-width: 1160px; margin: 0 auto; padding: 28px 24px 64px; }
.page-head { margin-bottom: 24px; max-width: 72ch; }
.page-head h1 { margin: 0 0 6px; font-size: 28px; line-height: 1.2; font-weight: 600; letter-spacing: -0.02em; }
.lead { margin: 0; color: var(--ink-2); font-size: 15px; }
.page-head-rosette { display: flex; align-items: center; gap: 20px; max-width: none; }

.card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 16px; }

.example-card, .challenge-card {
  display: flex; flex-direction: column;
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.card-art { background: var(--paper); border-bottom: 3px solid var(--line); }
.example-card.mode-2d .card-art { border-bottom-color: var(--hue-przyklady); }
.example-card.mode-3d .card-art { border-bottom-color: var(--hue-violet); }
.challenge-card .card-art { border-bottom-color: var(--line-strong); }
.challenge-card.is-solved .card-art { border-bottom-color: var(--hue-zadania); }
.thumb { display: block; width: 100%; height: 168px; }
.card-body { display: flex; flex-direction: column; gap: 8px; padding: 12px 14px 14px; flex: 1; }
.card-body > .btn { align-self: flex-start; margin-top: auto; }
.card-plate { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.card-title { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -0.01em; }
.card-text { margin: 0; color: var(--ink-2); font-size: 14px; }
.card-code summary { cursor: pointer; font-size: 13px; color: var(--ink-2); width: fit-content; border-radius: 4px; }
.card-code .code-block { margin-top: 8px; max-height: 220px; }

.chip {
  display: inline-block; flex: none;
  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
  padding: 1px 8px; border-radius: 999px;
  background: var(--tint); color: var(--ink-2);
}
.chip-3d { background: color-mix(in srgb, var(--hue-violet) 16%, transparent); color: var(--hue-violet); }
:root:not([data-theme='dark']) .chip-3d { color: #5a3389; }

.challenge-status { margin: 0; display: flex; align-items: center; gap: 6px; font-size: 13px; color: var(--ink-3); font-weight: 500; }
.challenge-status.is-solved { color: var(--hue-zadania); }
:root:not([data-theme='dark']) .challenge-status.is-solved { color: #a3135a; }

.danger-zone {
  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  margin-top: 48px; padding-top: 16px; border-top: 1px solid var(--line);
  font-size: 13px; color: var(--ink-3);
}
.danger-zone p { margin: 0; }

/* Rosette: unsolved petals are outlines; solved ones are cut from coloured paper, with a punched notch. */
.rosette { flex: none; overflow: visible; }
.rosette .petal { fill: none; stroke: var(--line-strong); stroke-width: 3; }
.rosette .petal.is-solved { stroke: none; }
.rosette .notch { fill: var(--line-strong); }
.rosette .notch.is-solved { fill: var(--sheet); }
.rosette-core { fill: var(--ink); }
.progress-link .rosette .petal { stroke-width: 5; }

.code-block {
  margin: 0;
  padding: 12px 14px;
  overflow: auto;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius-s);
  font-size: 13px;
  line-height: 20px;
  font-variant-ligatures: none;
}

/* Reference (Read mode inside the shell). */
.doc-layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 40px; align-items: start; }
.toc { position: sticky; top: 16px; font-size: 14px; }
.toc-title { font-size: 12px; font-weight: 600; color: var(--ink-3); margin: 0 0 8px; letter-spacing: 0.04em; text-transform: uppercase; }
.toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.toc a { display: block; padding: 4px 10px; border-radius: 6px; color: var(--ink-2); text-decoration: none; }
.toc a:hover { background: var(--tint-pomoc); color: var(--ink); }
.doc-body { max-width: 74ch; }
.doc-section { padding-bottom: 12px; scroll-margin-top: 16px; }
.doc-section h2 { font-size: 22px; font-weight: 600; letter-spacing: -0.015em; margin: 36px 0 10px; padding-bottom: 6px; border-bottom: 3px solid var(--hue-pomoc); width: fit-content; }
.doc-section:first-child h2 { margin-top: 0; }
.doc-section h2:focus { outline: none; }
.doc-section p { margin: 0 0 12px; }
.cmd-doc { padding: 16px 0 18px; border-bottom: 1px solid var(--line); }
.cmd-doc h3 { margin: 0 0 8px; font-size: 17px; font-weight: 600; display: flex; align-items: center; gap: 10px; }
.cmd-facts { display: grid; grid-template-columns: max-content 1fr; gap: 2px 16px; margin: 0 0 8px; font-size: 14px; }
.cmd-facts dt { color: var(--ink-3); }
.cmd-facts dd { margin: 0; }
.cmd-facts code, .doc-section p code { font-size: 13px; background: var(--tint); padding: 0 4px; border-radius: 4px; }
.example { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; margin: 4px 0 14px; }
.example .code-block { width: 100%; }
.doc-table { border-collapse: collapse; width: 100%; font-size: 14px; margin: 4px 0 16px; }
.doc-table th, .doc-table td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
.doc-table thead th { font-size: 12px; color: var(--ink-3); font-weight: 600; border-bottom: 2px solid var(--line-strong); }
.doc-table tbody th { font-weight: 500; }
.doc-table td { font-variant-numeric: tabular-nums; }

/* ---------- Responsive ---------- */

@media (max-width: 1100px) {
  .speed-label { display: none; }
  .doc-layout { grid-template-columns: 1fr; }
  .toc { position: static; }
  .toc ol { grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); }
}

@media (max-width: 820px) {
  :root { --bar-h: 52px; --code-size: 15px; --code-lh: 23px; }
  .topbar { gap: 8px; padding: 0 10px; }
  .brand-name { font-size: 16px; }
  /* Sections move to a bottom bar. */
  .nav {
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 20;
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 0;
    background: var(--sheet);
    border-top: 1px solid var(--line);
    padding: 0 0 env(safe-area-inset-bottom);
  }
  .nav-link {
    flex-direction: column; gap: 2px; justify-content: center;
    height: 58px; padding: 0 4px; font-size: 11.5px;
    border-radius: 0;
  }
  .nav-link[aria-current='page'] { box-shadow: inset 0 4px 0 color-mix(in srgb, var(--section-on) 0%, transparent); }
  .app { height: auto; min-height: 100dvh; grid-template-rows: auto 1fr; padding-bottom: calc(58px + env(safe-area-inset-bottom)); }
  .main { overflow: visible; }
  .page-pracownia { height: auto; }
  .workspace { grid-template-columns: 1fr; height: auto; padding: 8px; gap: 8px; }
  .canvas-panel { order: -1; height: 44vh; min-height: 260px; }
  .editor { min-height: 46vh; }
  .toolbar { gap: 8px; padding: 8px; }
  .toolbar .btn { height: 44px; }
  .toolbar .btn[data-action='step'] .btn-label,
  .toolbar .btn[data-action='pause'] .btn-label,
  .toolbar .btn[data-action='reset'] .btn-label { display: none; }
  .toolbar .btn[data-action='step'], .toolbar .btn[data-action='pause'], .toolbar .btn[data-action='reset'] { width: 44px; padding: 0; }
  .speed { flex: 1; min-width: 150px; }
  .speed input { flex: 1; width: auto; }
  .toolbar-sep { display: none; }
  .filebar .btn { height: 40px; }
  .shortcuts { display: none; }
  .btn-view { width: 44px; height: 44px; }
  .page-inner { padding: 20px 14px 40px; }
  .page-head h1 { font-size: 24px; }
  .page-head-rosette { flex-direction: column; align-items: flex-start; gap: 12px; }
  .card-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
  .readout { bottom: 64px; }
}

@media (max-width: 380px) {
  .brand-name { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; animation-duration: 0ms !important; }
}

@media (forced-colors: active) {
  .nav-link[aria-current='page'], .seg-btn[aria-pressed='true'] { outline: 2px solid CanvasText; }
  .error-flag { border: 1px solid CanvasText; }
}

toolu_01MMBjiFnECM57NqjxzerPeu.content:
/* Logomocja — cut-paper workspace (wycinanki łowickie).
   Flat saturated layers on a white or black sheet; one hue per section; vermilion only for errors. */

:root {
  --font-ui: 'Lexend', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-code: 'JetBrains Mono', ui-monospace, 'Cascadia Mono', Menlo, Consolas, monospace;

  /* Sheet and ink (light: white paper). */
  --ground: #f2f4ef;
  --sheet: #ffffff;
  --paper: #ffffff;
  --ink: #161a17;
  --ink-2: #4a524c;
  --ink-3: #6c756d;
  --line: #d7dcd3;
  --line-strong: #b9c0b6;
  --tint: #eef1ea;

  /* Section hues: the wycinanka wheel. */
  --hue-pracownia: #187a35;
  --hue-przyklady: #f2a516;
  --hue-zadania: #c8186e;
  --hue-pomoc: #2346a8;
  --hue-violet: #6b3fa0;
  --on-pracownia: #ffffff;
  --on-przyklady: #161a17;
  --on-zadania: #ffffff;
  --on-pomoc: #ffffff;
  --tint-pracownia: #e6f2e9;
  --tint-przyklady: #fdf1d6;
  --tint-zadania: #fbe4ef;
  --tint-pomoc: #e5ebf8;

  /* Errors only. */
  --vermilion: #d63a1c;
  --vermilion-text: #b42f15;
  --vermilion-tint: #fde7e1;

  --focus: #2346a8;
  --canvas-grid: #eceee8;
  --canvas-axis: #b3bbb0;
  --canvas-target: rgba(200, 24, 110, 0.3);

  /* Syntax. */
  --syn-cmd: #2346a8;
  --syn-num: #9a4f00;
  --syn-name: #6b3fa0;
  --syn-str: #b0145f;
  --syn-comment: #6c756d;
  --syn-bracket: #187a35;
  --syn-op: #4a524c;
  --syn-def: #187a35;

  --radius: 12px;
  --radius-s: 8px;
  --code-size: 14px;
  --code-lh: 22px;
  --bar-h: 56px;

  --section-hue: var(--hue-pracownia);
  --section-on: var(--on-pracownia);
  --section-tint: var(--tint-pracownia);

  color-scheme: light;
}

:root[data-theme='dark'] {
  /* Black paper. */
  --ground: #0b0c0b;
  --sheet: #141614;
  --paper: #0f110f;
  --ink: #f1f3ed;
  --ink-2: #b2b9b0;
  --ink-3: #8c948a;
  --line: #2b302b;
  --line-strong: #434a42;
  --tint: #1b1e1b;

  --hue-pracownia: #3fbf68;
  --hue-przyklady: #f5b335;
  --hue-zadania: #f0559c;
  --hue-pomoc: #7f9cf5;
  --hue-violet: #b18ae8;
  --on-pracownia: #0b0c0b;
  --on-przyklady: #0b0c0b;
  --on-zadania: #0b0c0b;
  --on-pomoc: #0b0c0b;
  --tint-pracownia: #14261a;
  --tint-przyklady: #2b2210;
  --tint-zadania: #2d1220;
  --tint-pomoc: #161d33;

  --vermilion: #ff6b4a;
  --vermilion-text: #ff8a6e;
  --vermilion-tint: #33160f;

  --focus: #9db4ff;
  --canvas-grid: #1b1f1b;
  --canvas-axis: #3a423a;
  --canvas-target: rgba(240, 85, 156, 0.38);

  --syn-cmd: #8fa8ff;
  --syn-num: #f5b335;
  --syn-name: #c9a6f5;
  --syn-str: #ff7cb5;
  --syn-comment: #8c948a;
  --syn-bracket: #5fd283;
  --syn-op: #b2b9b0;
  --syn-def: #5fd283;

  color-scheme: dark;
}

.app[data-section='przyklady'] { --section-hue: var(--hue-przyklady); --section-on: var(--on-przyklady); --section-tint: var(--tint-przyklady); }
.app[data-section='zadania'] { --section-hue: var(--hue-zadania); --section-on: var(--on-zadania); --section-tint: var(--tint-zadania); }
.app[data-section='pomoc'] { --section-hue: var(--hue-pomoc); --section-on: var(--on-pomoc); --section-tint: var(--tint-pomoc); }

*,
*::before,
*::after { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--ground);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection { background: color-mix(in srgb, var(--section-hue) 28%, transparent); }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

a { color: var(--hue-pomoc); text-underline-offset: 3px; }

code, kbd, pre { font-family: var(--font-code); }

kbd {
  display: inline-block;
  font-size: 11px;
  line-height: 16px;
  padding: 0 5px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--sheet);
  color: var(--ink-2);
}

.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%);
  white-space: nowrap; border: 0; padding: 0; margin: -1px;
}

.skip-link {
  position: absolute; left: 12px; top: -60px; z-index: 30;
  background: var(--sheet); color: var(--ink);
  padding: 8px 14px; border-radius: var(--radius-s); border: 2px solid var(--focus);
}
.skip-link:focus { top: 8px; }

/* ---------- Shell ---------- */

.app {
  display: grid;
  grid-template-rows: auto 1fr;
  height: 100vh;
  height: 100dvh;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  height: var(--bar-h);
  padding: 0 16px;
  background: var(--sheet);
  /* The current section's layer runs under the whole bar. */
  border-bottom: 4px solid var(--section-hue);
  position: relative;
  z-index: 5;
}

.brand {
  display: flex; align-items: center; gap: 10px;
  color: var(--ink); text-decoration: none;
  font-weight: 600; font-size: 18px; letter-spacing: -0.01em;
  padding: 4px 6px; margin-left: -6px; border-radius: var(--radius-s);
}
.brand-mark .petal-0 { fill: var(--hue-pracownia); }
.brand-mark .petal-1 { fill: var(--hue-przyklady); }
.brand-mark .petal-2 { fill: var(--hue-zadania); }
.brand-mark .petal-3 { fill: var(--hue-pomoc); }
.brand-mark .brand-core { fill: var(--ink); }

.nav { display: flex; gap: 4px; align-self: stretch; align-items: flex-end; }

.nav-link {
  display: flex; align-items: center; gap: 8px;
  height: 40px; padding: 0 14px;
  border-radius: var(--radius-s) var(--radius-s) 0 0;
  color: var(--ink-2); text-decoration: none; font-weight: 500; font-size: 14px;
  transition: background-color 160ms ease-out, color 160ms ease-out;
}
.nav-link:hover { background: var(--tint); color: var(--ink); }
.nav-link[aria-current='page'] { background: var(--section-hue); color: var(--section-on); }
.nav-link[aria-current='page'] .icon { opacity: 1; }
.nav-link .icon { opacity: 0.8; }

.topbar-tools { margin-left: auto; display: flex; align-items: center; gap: 10px; }

.progress-link {
  display: grid; place-items: center;
  width: 40px; height: 40px; border-radius: 50%;
}
.progress-link:hover { background: var(--tint); }

.seg {
  display: inline-flex;
  padding: 3px;
  border-radius: 10px;
  background: var(--tint);
  border: 1px solid var(--line);
}
.seg-btn {
  font: inherit; font-size: 13px; font-weight: 600; letter-spacing: 0.02em;
  min-width: 44px; height: 32px; padding: 0 10px;
  border: 0; border-radius: 7px;
  background: transparent; color: var(--ink-2); cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.seg-btn:hover { color: var(--ink); }
.seg-btn[aria-pressed='true'] { background: var(--ink); color: var(--sheet); }

.main { min-height: 0; overflow: auto; outline: none; }
.page[hidden] { display: none !important; }
.page-pracownia { height: 100%; }

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font: inherit; font-size: 14px; font-weight: 500;
  height: 38px; padding: 0 14px;
  border-radius: var(--radius-s);
  border: 1px solid var(--line-strong);
  background: var(--sheet); color: var(--ink);
  cursor: pointer; white-space: nowrap;
  transition: background-color 150ms ease-out, border-color 150ms ease-out, color 150ms ease-out, transform 120ms ease-out;
}
.btn:hover:not(:disabled) { background: var(--tint); border-color: var(--ink-3); }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn .icon { flex: none; }

.btn-primary { background: var(--hue-pracownia); border-color: var(--hue-pracownia); color: var(--on-pracownia); }
.btn-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-pracownia) 86%, var(--ink)); border-color: transparent; }
.page-przyklady .btn-primary { background: var(--hue-przyklady); border-color: var(--hue-przyklady); color: var(--on-przyklady); }
.page-przyklady .btn-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-przyklady) 86%, var(--ink)); }

.btn-challenge { background: var(--hue-zadania); border-color: var(--hue-zadania); color: var(--on-zadania); }
.btn-challenge:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-zadania) 86%, var(--ink)); border-color: transparent; }

.btn-quiet { background: transparent; border-color: transparent; color: var(--ink-2); }
.btn-quiet:hover:not(:disabled) { color: var(--ink); background: var(--tint); border-color: transparent; }

.btn-danger { color: var(--vermilion-text); border-color: color-mix(in srgb, var(--vermilion) 45%, var(--line)); background: transparent; }
.btn-danger.is-armed { background: var(--vermilion); color: #fff; border-color: var(--vermilion); }

.btn-small { height: 32px; padding: 0 10px; font-size: 13px; gap: 6px; }
.btn-icon { width: 38px; padding: 0; }
.btn-small.btn-icon { width: 32px; }

/* ---------- Workspace ---------- */

.workspace {
  display: grid;
  grid-template-columns: minmax(360px, 42%) minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
  height: 100%;
  min-height: 0;
}

.panel {
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}

.code-panel { display: flex; flex-direction: column; }

.toolbar {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
}
.toolbar-group { display: flex; gap: 6px; }
.toolbar-sep { flex: 1; }
.btn-primary[data-action='run'] { min-width: 112px; }

.speed { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--ink-2); }
.speed input { width: 96px; accent-color: var(--hue-pracownia); }
.speed-out { min-width: 7.5ch; font-variant-numeric: tabular-nums; color: var(--ink); font-size: 12px; }

.notice {
  display: flex; align-items: center; gap: 10px;
  margin: 10px 12px 0;
  padding: 6px 6px 6px 12px;
  background: var(--tint-przyklady);
  border-radius: var(--radius-s);
  font-size: 13px;
}
.notice[hidden] { display: none; }
.notice > span { flex: 1; }

/* Editor */
.editor {
  flex: 1;
  min-height: 160px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  overflow: hidden;
  position: relative;
  font-family: var(--font-code);
  font-size: var(--code-size);
  line-height: var(--code-lh);
  font-variant-ligatures: none;
  tab-size: 2;
}
.editor-gutter {
  padding: 12px 10px 12px 14px;
  min-width: 4ch;
  text-align: right;
  color: var(--ink-3);
  font-variant-numeric: tabular-nums;
  user-select: none;
  background: var(--sheet);
  border-right: 1px solid var(--line);
  position: relative; z-index: 2;
}
.gutter-line { height: var(--code-lh); padding-right: 2px; border-radius: 4px; }
.gutter-line.is-exec { background: var(--hue-przyklady); color: var(--on-przyklady); font-weight: 600; }
.gutter-line.is-error { background: var(--vermilion); color: #fff; font-weight: 600; }

.editor-code { position: relative; min-width: 0; overflow: hidden; }
.editor-layer, .editor-input {
  margin: 0;
  padding: 12px 16px 12px 12px;
  font: inherit;
  line-height: inherit;
  letter-spacing: 0;
  white-space: pre;
  tab-size: inherit;
}
.editor-layer {
  position: absolute; inset: 0 auto auto 0;
  min-width: 100%;
  pointer-events: none;
  color: var(--ink);
}
.editor-line { height: var(--code-lh); white-space: pre; border-radius: 3px; }
.editor-line.is-exec { background: var(--tint-przyklady); box-shadow: inset 3px 0 0 var(--hue-przyklady); }
.editor-line.is-error { background: var(--vermilion-tint); }
.editor-input {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  border: 0; outline: none; resize: none;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  overflow: auto;
}
.editor-input::selection { background: color-mix(in srgb, var(--hue-pomoc) 26%, transparent); color: transparent; }
.editor:focus-within { box-shadow: inset 0 0 0 2px var(--focus); }

.t-cmd { color: var(--syn-cmd); font-weight: 500; }
.t-num { color: var(--syn-num); }
.t-name { color: var(--syn-name); }
.t-str { color: var(--syn-str); }
.t-str[style*='--swatch'] { border-bottom: 3px solid var(--swatch); }
.t-comment { color: var(--syn-comment); font-style: italic; }
.t-bracket { color: var(--syn-bracket); font-weight: 600; }
.t-op { color: var(--syn-op); }
.t-def { color: var(--syn-def); font-weight: 600; }
.t-value { color: var(--syn-name); font-style: italic; }

.error-token {
  background: transparent; color: inherit;
  text-decoration: underline wavy var(--vermilion);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 4px;
}
.error-caret { box-shadow: inset 2px 0 0 var(--vermilion); }
.error-flag {
  display: inline-block;
  margin-left: 3ch;
  padding: 0 8px;
  line-height: 20px;
  border-radius: 4px;
  background: var(--vermilion);
  color: #fff;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  vertical-align: 1px;
}
:root[data-theme='dark'] .error-flag { color: #160704; }

.statusbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 12px;
  padding: 10px 12px 8px;
  border-top: 1px solid var(--line);
}
.status-row { display: flex; align-items: flex-start; gap: 8px; min-height: 22px; grid-column: 1 / -1; }
.status-text { margin: 0; font-size: 13px; color: var(--ink-2); flex: 1; }
.status-text.is-error { color: var(--vermilion-text); font-weight: 500; }
.status-row .btn { margin-top: -4px; }
.meter { grid-column: 1; align-self: center; margin-top: 6px; }
.meter-track { height: 4px; border-radius: 2px; background: var(--tint); overflow: hidden; }
.meter-fill { height: 100%; width: 0; background: var(--hue-pracownia); transition: width 120ms linear; }
.meter-text { grid-column: 2; margin-top: 6px; font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; }

.filebar { display: flex; flex-wrap: wrap; gap: 2px; padding: 4px 8px; border-top: 1px solid var(--line); }

.share-panel { display: flex; align-items: flex-end; gap: 6px; padding: 0 12px 10px; }
.share-panel[hidden] { display: none; }
.share-label { flex: 1; display: grid; gap: 4px; font-size: 12px; color: var(--ink-2); }
.share-input {
  font: inherit; font-family: var(--font-code); font-size: 12px;
  height: 32px; padding: 0 8px; width: 100%;
  border: 1px solid var(--line-strong); border-radius: 6px;
  background: var(--paper); color: var(--ink);
}

.shortcuts { margin: 0; padding: 6px 12px 10px; font-size: 11px; color: var(--ink-3); }

/* Challenge banner: the fuchsia layer. */
.challenge-banner {
  padding: 12px 14px;
  background: var(--tint-zadania);
  border-bottom: 3px solid var(--hue-zadania);
  display: grid; gap: 6px;
}
.challenge-banner[hidden] { display: none; }
.banner-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.banner-title { margin: 0; font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.banner-task { margin: 0; font-size: 14px; max-width: 70ch; }
.banner-details { font-size: 13px; color: var(--ink-2); }
.banner-details summary { cursor: pointer; width: fit-content; border-radius: 4px; }
.banner-hint { margin: 4px 0 0; font-family: var(--font-code); font-size: 12.5px; }
.banner-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.banner-actions .btn-quiet[aria-pressed='true'] { color: var(--ink); background: color-mix(in srgb, var(--hue-zadania) 14%, transparent); }
.banner-result { margin: 0; display: flex; align-items: flex-start; gap: 6px; font-size: 14px; font-weight: 500; min-height: 0; }
.banner-result:empty { display: none; }
.banner-result .icon { margin-top: 3px; flex: none; }
.banner-result.is-pass { color: var(--hue-pracownia); }
:root:not([data-theme='dark']) .banner-result.is-pass { color: #146a2d; }
.banner-result.is-fail { color: var(--ink); }
.banner-result.is-fail .icon { color: var(--hue-zadania); }

/* Canvas panel */
.canvas-panel { position: relative; background: var(--paper); }
.stage, .view3d, .view3d-host { position: absolute; inset: 0; }
.view-canvas { display: block; width: 100%; height: 100%; touch-action: none; cursor: grab; }
.view-canvas:active { cursor: grabbing; }
.view-canvas:focus-visible { outline-offset: -3px; }
.axis-label {
  position: absolute; left: 0; top: 0;
  margin: -9px 0 0 6px;
  font-size: 12px; font-weight: 600;
  pointer-events: none;
}
.axis-x { color: var(--hue-zadania); }
.axis-y { color: var(--hue-pracownia); }
.axis-z { color: var(--hue-pomoc); }

.off3d {
  position: absolute; inset: 0;
  display: grid; place-content: center;
  padding: 32px; max-width: 560px; margin: auto;
  text-align: center; font-size: 14px; color: var(--ink-2);
}
.off3d[hidden] { display: none; }
.off3d strong { display: block; color: var(--ink); font-size: 16px; margin-bottom: 6px; }

.view-controls {
  position: absolute; right: 12px; bottom: 12px;
  display: flex; gap: 4px; padding: 4px;
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.btn-view { border-color: transparent; height: 36px; width: 36px; }
.workspace:not(.is-3d) [data-action='camera'] { display: none; }

.readout {
  position: absolute; left: 12px; bottom: 14px;
  padding: 4px 8px; border-radius: 6px;
  background: color-mix(in srgb, var(--sheet) 88%, transparent);
  font-family: var(--font-code); font-size: 11.5px; color: var(--ink-2);
  font-variant-numeric: tabular-nums; white-space: pre;
  pointer-events: none;
}

/* ---------- Pages ---------- */

.page-inner { max-width: 1160px; margin: 0 auto; padding: 28px 24px 64px; }
.page-head { margin-bottom: 24px; max-width: 72ch; }
.page-head h1 { margin: 0 0 6px; font-size: 28px; line-height: 1.2; font-weight: 600; letter-spacing: -0.02em; }
.lead { margin: 0; color: var(--ink-2); font-size: 15px; }
.page-head-rosette { display: flex; align-items: center; gap: 20px; max-width: none; }

.card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 16px; }

.example-card, .challenge-card {
  display: flex; flex-direction: column;
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.card-art { background: var(--paper); border-bottom: 3px solid var(--line); }
.example-card.mode-2d .card-art { border-bottom-color: var(--hue-przyklady); }
.example-card.mode-3d .card-art { border-bottom-color: var(--hue-violet); }
.challenge-card .card-art { border-bottom-color: var(--line-strong); }
.challenge-card.is-solved .card-art { border-bottom-color: var(--hue-zadania); }
.thumb { display: block; width: 100%; height: 168px; }
.card-body { display: flex; flex-direction: column; gap: 8px; padding: 12px 14px 14px; flex: 1; }
.card-body > .btn { align-self: flex-start; margin-top: auto; }
.card-plate { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.card-title { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -0.01em; }
.card-text { margin: 0; color: var(--ink-2); font-size: 14px; }
.card-code summary { cursor: pointer; font-size: 13px; color: var(--ink-2); width: fit-content; border-radius: 4px; }
.card-code .code-block { margin-top: 8px; max-height: 220px; }

.chip {
  display: inline-block; flex: none;
  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
  padding: 1px 8px; border-radius: 999px;
  background: var(--tint); color: var(--ink-2);
}
.chip-3d { background: color-mix(in srgb, var(--hue-violet) 16%, transparent); color: var(--hue-violet); }
:root:not([data-theme='dark']) .chip-3d { color: #5a3389; }

.challenge-status { margin: 0; display: flex; align-items: center; gap: 6px; font-size: 13px; color: var(--ink-3); font-weight: 500; }
.challenge-status.is-solved { color: var(--hue-zadania); }
:root:not([data-theme='dark']) .challenge-status.is-solved { color: #a3135a; }

.danger-zone {
  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  margin-top: 48px; padding-top: 16px; border-top: 1px solid var(--line);
  font-size: 13px; color: var(--ink-3);
}
.danger-zone p { margin: 0; }

/* Rosette: unsolved petals are outlines; solved ones are cut from coloured paper, with a punched notch. */
.rosette { flex: none; overflow: visible; }
.rosette .petal { fill: none; stroke: var(--line-strong); stroke-width: 3; }
.rosette .petal.is-solved { stroke: none; }
.rosette .notch { fill: var(--line-strong); }
.rosette .notch.is-solved { fill: var(--sheet); }
.rosette-core { fill: var(--ink); }
.progress-link .rosette .petal { stroke-width: 5; }

.code-block {
  margin: 0;
  padding: 12px 14px;
  overflow: auto;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius-s);
  font-size: 13px;
  line-height: 20px;
  font-variant-ligatures: none;
}

/* Reference (Read mode inside the shell). */
.doc-layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 40px; align-items: start; }
.toc { position: sticky; top: 16px; font-size: 14px; }
.toc-title { font-size: 12px; font-weight: 600; color: var(--ink-3); margin: 0 0 8px; letter-spacing: 0.04em; text-transform: uppercase; }
.toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.toc a { display: block; padding: 4px 10px; border-radius: 6px; color: var(--ink-2); text-decoration: none; }
.toc a:hover { background: var(--tint-pomoc); color: var(--ink); }
.doc-body { max-width: 74ch; }
.doc-section { padding-bottom: 12px; scroll-margin-top: 16px; }
.doc-section h2 { font-size: 22px; font-weight: 600; letter-spacing: -0.015em; margin: 36px 0 10px; padding-bottom: 6px; border-bottom: 3px solid var(--hue-pomoc); width: fit-content; }
.doc-section:first-child h2 { margin-top: 0; }
.doc-section h2:focus { outline: none; }
.doc-section p { margin: 0 0 12px; }
.cmd-doc { padding: 16px 0 18px; border-bottom: 1px solid var(--line); }
.cmd-doc h3 { margin: 0 0 8px; font-size: 17px; font-weight: 600; display: flex; align-items: center; gap: 10px; }
.cmd-facts { display: grid; grid-template-columns: max-content 1fr; gap: 2px 16px; margin: 0 0 8px; font-size: 14px; }
.cmd-facts dt { color: var(--ink-3); }
.cmd-facts dd { margin: 0; }
.cmd-facts code, .doc-section p code { font-size: 13px; background: var(--tint); padding: 0 4px; border-radius: 4px; }
.example { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; margin: 4px 0 14px; }
.example .code-block { width: 100%; }
.doc-table { border-collapse: collapse; width: 100%; font-size: 14px; margin: 4px 0 16px; }
.doc-table th, .doc-table td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
.doc-table thead th { font-size: 12px; color: var(--ink-3); font-weight: 600; border-bottom: 2px solid var(--line-strong); }
.doc-table tbody th { font-weight: 500; }
.doc-table td { font-variant-numeric: tabular-nums; }

/* ---------- Responsive ---------- */

@media (max-width: 1100px) {
  .speed-label { display: none; }
  .doc-layout { grid-template-columns: 1fr; }
  .toc { position: static; }
  .toc ol { grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); }
}

@media (max-width: 820px) {
  :root { --bar-h: 52px; --code-size: 15px; --code-lh: 23px; }
  .topbar { gap: 8px; padding: 0 10px; }
  .brand-name { font-size: 16px; }
  /* Sections move to a bottom bar. */
  .nav {
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 20;
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 0;
    background: var(--sheet);
    border-top: 1px solid var(--line);
    padding: 0 0 env(safe-area-inset-bottom);
  }
  .nav-link {
    flex-direction: column; gap: 2px; justify-content: center;
    height: 58px; padding: 0 4px; font-size: 11.5px;
    border-radius: 0;
  }
  .nav-link[aria-current='page'] { box-shadow: inset 0 4px 0 color-mix(in srgb, var(--section-on) 0%, transparent); }
  .app { height: auto; min-height: 100dvh; grid-template-rows: auto 1fr; padding-bottom: calc(58px + env(safe-area-inset-bottom)); }
  .main { overflow: visible; }
  .page-pracownia { height: auto; }
  .workspace { grid-template-columns: 1fr; height: auto; padding: 8px; gap: 8px; }
  .canvas-panel { order: -1; height: 44vh; min-height: 260px; }
  .editor { min-height: 46vh; }
  .toolbar { gap: 8px; padding: 8px; }
  .toolbar .btn { height: 44px; }
  .toolbar .btn[data-action='step'] .btn-label,
  .toolbar .btn[data-action='pause'] .btn-label,
  .toolbar .btn[data-action='reset'] .btn-label { display: none; }
  .toolbar .btn[data-action='step'], .toolbar .btn[data-action='pause'], .toolbar .btn[data-action='reset'] { width: 44px; padding: 0; }
  .speed { flex: 1; min-width: 150px; }
  .speed input { flex: 1; width: auto; }
  .toolbar-sep { display: none; }
  .filebar .btn { height: 40px; }
  .shortcuts { display: none; }
  .btn-view { width: 44px; height: 44px; }
  .page-inner { padding: 20px 14px 40px; }
  .page-head h1 { font-size: 24px; }
  .page-head-rosette { flex-direction: column; align-items: flex-start; gap: 12px; }
  .card-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
  .readout { bottom: 64px; }
}

@media (max-width: 380px) {
  .brand-name { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; animation-duration: 0ms !important; }
}

@media (forced-colors: active) {
  .nav-link[aria-current='page'], .seg-btn[aria-pressed='true'] { outline: 2px solid CanvasText; }
  .error-flag { border: 1px solid CanvasText; }
}

tool_use_result.content:
/* Logomocja — cut-paper workspace (wycinanki łowickie).
   Flat saturated layers on a white or black sheet; one hue per section; vermilion only for errors. */

:root {
  --font-ui: 'Lexend', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-code: 'JetBrains Mono', ui-monospace, 'Cascadia Mono', Menlo, Consolas, monospace;

  /* Sheet and ink (light: white paper). */
  --ground: #f2f4ef;
  --sheet: #ffffff;
  --paper: #ffffff;
  --ink: #161a17;
  --ink-2: #4a524c;
  --ink-3: #6c756d;
  --line: #d7dcd3;
  --line-strong: #b9c0b6;
  --tint: #eef1ea;

  /* Section hues: the wycinanka wheel. */
  --hue-pracownia: #187a35;
  --hue-przyklady: #f2a516;
  --hue-zadania: #c8186e;
  --hue-pomoc: #2346a8;
  --hue-violet: #6b3fa0;
  --on-pracownia: #ffffff;
  --on-przyklady: #161a17;
  --on-zadania: #ffffff;
  --on-pomoc: #ffffff;
  --tint-pracownia: #e6f2e9;
  --tint-przyklady: #fdf1d6;
  --tint-zadania: #fbe4ef;
  --tint-pomoc: #e5ebf8;

  /* Errors only. */
  --vermilion: #d63a1c;
  --vermilion-text: #b42f15;
  --vermilion-tint: #fde7e1;

  --focus: #2346a8;
  --canvas-grid: #eceee8;
  --canvas-axis: #b3bbb0;
  --canvas-target: rgba(200, 24, 110, 0.3);

  /* Syntax. */
  --syn-cmd: #2346a8;
  --syn-num: #9a4f00;
  --syn-name: #6b3fa0;
  --syn-str: #b0145f;
  --syn-comment: #6c756d;
  --syn-bracket: #187a35;
  --syn-op: #4a524c;
  --syn-def: #187a35;

  --radius: 12px;
  --radius-s: 8px;
  --code-size: 14px;
  --code-lh: 22px;
  --bar-h: 56px;

  --section-hue: var(--hue-pracownia);
  --section-on: var(--on-pracownia);
  --section-tint: var(--tint-pracownia);

  color-scheme: light;
}

:root[data-theme='dark'] {
  /* Black paper. */
  --ground: #0b0c0b;
  --sheet: #141614;
  --paper: #0f110f;
  --ink: #f1f3ed;
  --ink-2: #b2b9b0;
  --ink-3: #8c948a;
  --line: #2b302b;
  --line-strong: #434a42;
  --tint: #1b1e1b;

  --hue-pracownia: #3fbf68;
  --hue-przyklady: #f5b335;
  --hue-zadania: #f0559c;
  --hue-pomoc: #7f9cf5;
  --hue-violet: #b18ae8;
  --on-pracownia: #0b0c0b;
  --on-przyklady: #0b0c0b;
  --on-zadania: #0b0c0b;
  --on-pomoc: #0b0c0b;
  --tint-pracownia: #14261a;
  --tint-przyklady: #2b2210;
  --tint-zadania: #2d1220;
  --tint-pomoc: #161d33;

  --vermilion: #ff6b4a;
  --vermilion-text: #ff8a6e;
  --vermilion-tint: #33160f;

  --focus: #9db4ff;
  --canvas-grid: #1b1f1b;
  --canvas-axis: #3a423a;
  --canvas-target: rgba(240, 85, 156, 0.38);

  --syn-cmd: #8fa8ff;
  --syn-num: #f5b335;
  --syn-name: #c9a6f5;
  --syn-str: #ff7cb5;
  --syn-comment: #8c948a;
  --syn-bracket: #5fd283;
  --syn-op: #b2b9b0;
  --syn-def: #5fd283;

  color-scheme: dark;
}

.app[data-section='przyklady'] { --section-hue: var(--hue-przyklady); --section-on: var(--on-przyklady); --section-tint: var(--tint-przyklady); }
.app[data-section='zadania'] { --section-hue: var(--hue-zadania); --section-on: var(--on-zadania); --section-tint: var(--tint-zadania); }
.app[data-section='pomoc'] { --section-hue: var(--hue-pomoc); --section-on: var(--on-pomoc); --section-tint: var(--tint-pomoc); }

*,
*::before,
*::after { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 15px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--ground);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

::selection { background: color-mix(in srgb, var(--section-hue) 28%, transparent); }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

a { color: var(--hue-pomoc); text-underline-offset: 3px; }

code, kbd, pre { font-family: var(--font-code); }

kbd {
  display: inline-block;
  font-size: 11px;
  line-height: 16px;
  padding: 0 5px;
  border: 1px solid var(--line-strong);
  border-bottom-width: 2px;
  border-radius: 4px;
  background: var(--sheet);
  color: var(--ink-2);
}

.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  overflow: hidden; clip: rect(0 0 0 0); clip-path: inset(50%);
  white-space: nowrap; border: 0; padding: 0; margin: -1px;
}

.skip-link {
  position: absolute; left: 12px; top: -60px; z-index: 30;
  background: var(--sheet); color: var(--ink);
  padding: 8px 14px; border-radius: var(--radius-s); border: 2px solid var(--focus);
}
.skip-link:focus { top: 8px; }

/* ---------- Shell ---------- */

.app {
  display: grid;
  grid-template-rows: auto 1fr;
  height: 100vh;
  height: 100dvh;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  height: var(--bar-h);
  padding: 0 16px;
  background: var(--sheet);
  /* The current section's layer runs under the whole bar. */
  border-bottom: 4px solid var(--section-hue);
  position: relative;
  z-index: 5;
}

.brand {
  display: flex; align-items: center; gap: 10px;
  color: var(--ink); text-decoration: none;
  font-weight: 600; font-size: 18px; letter-spacing: -0.01em;
  padding: 4px 6px; margin-left: -6px; border-radius: var(--radius-s);
}
.brand-mark .petal-0 { fill: var(--hue-pracownia); }
.brand-mark .petal-1 { fill: var(--hue-przyklady); }
.brand-mark .petal-2 { fill: var(--hue-zadania); }
.brand-mark .petal-3 { fill: var(--hue-pomoc); }
.brand-mark .brand-core { fill: var(--ink); }

.nav { display: flex; gap: 4px; align-self: stretch; align-items: flex-end; }

.nav-link {
  display: flex; align-items: center; gap: 8px;
  height: 40px; padding: 0 14px;
  border-radius: var(--radius-s) var(--radius-s) 0 0;
  color: var(--ink-2); text-decoration: none; font-weight: 500; font-size: 14px;
  transition: background-color 160ms ease-out, color 160ms ease-out;
}
.nav-link:hover { background: var(--tint); color: var(--ink); }
.nav-link[aria-current='page'] { background: var(--section-hue); color: var(--section-on); }
.nav-link[aria-current='page'] .icon { opacity: 1; }
.nav-link .icon { opacity: 0.8; }

.topbar-tools { margin-left: auto; display: flex; align-items: center; gap: 10px; }

.progress-link {
  display: grid; place-items: center;
  width: 40px; height: 40px; border-radius: 50%;
}
.progress-link:hover { background: var(--tint); }

.seg {
  display: inline-flex;
  padding: 3px;
  border-radius: 10px;
  background: var(--tint);
  border: 1px solid var(--line);
}
.seg-btn {
  font: inherit; font-size: 13px; font-weight: 600; letter-spacing: 0.02em;
  min-width: 44px; height: 32px; padding: 0 10px;
  border: 0; border-radius: 7px;
  background: transparent; color: var(--ink-2); cursor: pointer;
  font-variant-numeric: tabular-nums;
}
.seg-btn:hover { color: var(--ink); }
.seg-btn[aria-pressed='true'] { background: var(--ink); color: var(--sheet); }

.main { min-height: 0; overflow: auto; outline: none; }
.page[hidden] { display: none !important; }
.page-pracownia { height: 100%; }

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font: inherit; font-size: 14px; font-weight: 500;
  height: 38px; padding: 0 14px;
  border-radius: var(--radius-s);
  border: 1px solid var(--line-strong);
  background: var(--sheet); color: var(--ink);
  cursor: pointer; white-space: nowrap;
  transition: background-color 150ms ease-out, border-color 150ms ease-out, color 150ms ease-out, transform 120ms ease-out;
}
.btn:hover:not(:disabled) { background: var(--tint); border-color: var(--ink-3); }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { opacity: 0.45; cursor: not-allowed; }
.btn .icon { flex: none; }

.btn-primary { background: var(--hue-pracownia); border-color: var(--hue-pracownia); color: var(--on-pracownia); }
.btn-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-pracownia) 86%, var(--ink)); border-color: transparent; }
.page-przyklady .btn-primary { background: var(--hue-przyklady); border-color: var(--hue-przyklady); color: var(--on-przyklady); }
.page-przyklady .btn-primary:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-przyklady) 86%, var(--ink)); }

.btn-challenge { background: var(--hue-zadania); border-color: var(--hue-zadania); color: var(--on-zadania); }
.btn-challenge:hover:not(:disabled) { background: color-mix(in srgb, var(--hue-zadania) 86%, var(--ink)); border-color: transparent; }

.btn-quiet { background: transparent; border-color: transparent; color: var(--ink-2); }
.btn-quiet:hover:not(:disabled) { color: var(--ink); background: var(--tint); border-color: transparent; }

.btn-danger { color: var(--vermilion-text); border-color: color-mix(in srgb, var(--vermilion) 45%, var(--line)); background: transparent; }
.btn-danger.is-armed { background: var(--vermilion); color: #fff; border-color: var(--vermilion); }

.btn-small { height: 32px; padding: 0 10px; font-size: 13px; gap: 6px; }
.btn-icon { width: 38px; padding: 0; }
.btn-small.btn-icon { width: 32px; }

/* ---------- Workspace ---------- */

.workspace {
  display: grid;
  grid-template-columns: minmax(360px, 42%) minmax(0, 1fr);
  gap: 12px;
  padding: 12px;
  height: 100%;
  min-height: 0;
}

.panel {
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  min-height: 0;
  min-width: 0;
  overflow: hidden;
}

.code-panel { display: flex; flex-direction: column; }

.toolbar {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap;
  padding: 10px 12px;
  border-bottom: 1px solid var(--line);
}
.toolbar-group { display: flex; gap: 6px; }
.toolbar-sep { flex: 1; }
.btn-primary[data-action='run'] { min-width: 112px; }

.speed { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--ink-2); }
.speed input { width: 96px; accent-color: var(--hue-pracownia); }
.speed-out { min-width: 7.5ch; font-variant-numeric: tabular-nums; color: var(--ink); font-size: 12px; }

.notice {
  display: flex; align-items: center; gap: 10px;
  margin: 10px 12px 0;
  padding: 6px 6px 6px 12px;
  background: var(--tint-przyklady);
  border-radius: var(--radius-s);
  font-size: 13px;
}
.notice[hidden] { display: none; }
.notice > span { flex: 1; }

/* Editor */
.editor {
  flex: 1;
  min-height: 160px;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  overflow: hidden;
  position: relative;
  font-family: var(--font-code);
  font-size: var(--code-size);
  line-height: var(--code-lh);
  font-variant-ligatures: none;
  tab-size: 2;
}
.editor-gutter {
  padding: 12px 10px 12px 14px;
  min-width: 4ch;
  text-align: right;
  color: var(--ink-3);
  font-variant-numeric: tabular-nums;
  user-select: none;
  background: var(--sheet);
  border-right: 1px solid var(--line);
  position: relative; z-index: 2;
}
.gutter-line { height: var(--code-lh); padding-right: 2px; border-radius: 4px; }
.gutter-line.is-exec { background: var(--hue-przyklady); color: var(--on-przyklady); font-weight: 600; }
.gutter-line.is-error { background: var(--vermilion); color: #fff; font-weight: 600; }

.editor-code { position: relative; min-width: 0; overflow: hidden; }
.editor-layer, .editor-input {
  margin: 0;
  padding: 12px 16px 12px 12px;
  font: inherit;
  line-height: inherit;
  letter-spacing: 0;
  white-space: pre;
  tab-size: inherit;
}
.editor-layer {
  position: absolute; inset: 0 auto auto 0;
  min-width: 100%;
  pointer-events: none;
  color: var(--ink);
}
.editor-line { height: var(--code-lh); white-space: pre; border-radius: 3px; }
.editor-line.is-exec { background: var(--tint-przyklady); box-shadow: inset 3px 0 0 var(--hue-przyklady); }
.editor-line.is-error { background: var(--vermilion-tint); }
.editor-input {
  position: absolute; inset: 0;
  width: 100%; height: 100%;
  border: 0; outline: none; resize: none;
  background: transparent;
  color: transparent;
  caret-color: var(--ink);
  overflow: auto;
}
.editor-input::selection { background: color-mix(in srgb, var(--hue-pomoc) 26%, transparent); color: transparent; }
.editor:focus-within { box-shadow: inset 0 0 0 2px var(--focus); }

.t-cmd { color: var(--syn-cmd); font-weight: 500; }
.t-num { color: var(--syn-num); }
.t-name { color: var(--syn-name); }
.t-str { color: var(--syn-str); }
.t-str[style*='--swatch'] { border-bottom: 3px solid var(--swatch); }
.t-comment { color: var(--syn-comment); font-style: italic; }
.t-bracket { color: var(--syn-bracket); font-weight: 600; }
.t-op { color: var(--syn-op); }
.t-def { color: var(--syn-def); font-weight: 600; }
.t-value { color: var(--syn-name); font-style: italic; }

.error-token {
  background: transparent; color: inherit;
  text-decoration: underline wavy var(--vermilion);
  text-decoration-thickness: 1.5px;
  text-underline-offset: 4px;
}
.error-caret { box-shadow: inset 2px 0 0 var(--vermilion); }
.error-flag {
  display: inline-block;
  margin-left: 3ch;
  padding: 0 8px;
  line-height: 20px;
  border-radius: 4px;
  background: var(--vermilion);
  color: #fff;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  vertical-align: 1px;
}
:root[data-theme='dark'] .error-flag { color: #160704; }

.statusbar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  column-gap: 12px;
  padding: 10px 12px 8px;
  border-top: 1px solid var(--line);
}
.status-row { display: flex; align-items: flex-start; gap: 8px; min-height: 22px; grid-column: 1 / -1; }
.status-text { margin: 0; font-size: 13px; color: var(--ink-2); flex: 1; }
.status-text.is-error { color: var(--vermilion-text); font-weight: 500; }
.status-row .btn { margin-top: -4px; }
.meter { grid-column: 1; align-self: center; margin-top: 6px; }
.meter-track { height: 4px; border-radius: 2px; background: var(--tint); overflow: hidden; }
.meter-fill { height: 100%; width: 0; background: var(--hue-pracownia); transition: width 120ms linear; }
.meter-text { grid-column: 2; margin-top: 6px; font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; }

.filebar { display: flex; flex-wrap: wrap; gap: 2px; padding: 4px 8px; border-top: 1px solid var(--line); }

.share-panel { display: flex; align-items: flex-end; gap: 6px; padding: 0 12px 10px; }
.share-panel[hidden] { display: none; }
.share-label { flex: 1; display: grid; gap: 4px; font-size: 12px; color: var(--ink-2); }
.share-input {
  font: inherit; font-family: var(--font-code); font-size: 12px;
  height: 32px; padding: 0 8px; width: 100%;
  border: 1px solid var(--line-strong); border-radius: 6px;
  background: var(--paper); color: var(--ink);
}

.shortcuts { margin: 0; padding: 6px 12px 10px; font-size: 11px; color: var(--ink-3); }

/* Challenge banner: the fuchsia layer. */
.challenge-banner {
  padding: 12px 14px;
  background: var(--tint-zadania);
  border-bottom: 3px solid var(--hue-zadania);
  display: grid; gap: 6px;
}
.challenge-banner[hidden] { display: none; }
.banner-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.banner-title { margin: 0; font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
.banner-task { margin: 0; font-size: 14px; max-width: 70ch; }
.banner-details { font-size: 13px; color: var(--ink-2); }
.banner-details summary { cursor: pointer; width: fit-content; border-radius: 4px; }
.banner-hint { margin: 4px 0 0; font-family: var(--font-code); font-size: 12.5px; }
.banner-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.banner-actions .btn-quiet[aria-pressed='true'] { color: var(--ink); background: color-mix(in srgb, var(--hue-zadania) 14%, transparent); }
.banner-result { margin: 0; display: flex; align-items: flex-start; gap: 6px; font-size: 14px; font-weight: 500; min-height: 0; }
.banner-result:empty { display: none; }
.banner-result .icon { margin-top: 3px; flex: none; }
.banner-result.is-pass { color: var(--hue-pracownia); }
:root:not([data-theme='dark']) .banner-result.is-pass { color: #146a2d; }
.banner-result.is-fail { color: var(--ink); }
.banner-result.is-fail .icon { color: var(--hue-zadania); }

/* Canvas panel */
.canvas-panel { position: relative; background: var(--paper); }
.stage, .view3d, .view3d-host { position: absolute; inset: 0; }
.view-canvas { display: block; width: 100%; height: 100%; touch-action: none; cursor: grab; }
.view-canvas:active { cursor: grabbing; }
.view-canvas:focus-visible { outline-offset: -3px; }
.axis-label {
  position: absolute; left: 0; top: 0;
  margin: -9px 0 0 6px;
  font-size: 12px; font-weight: 600;
  pointer-events: none;
}
.axis-x { color: var(--hue-zadania); }
.axis-y { color: var(--hue-pracownia); }
.axis-z { color: var(--hue-pomoc); }

.off3d {
  position: absolute; inset: 0;
  display: grid; place-content: center;
  padding: 32px; max-width: 560px; margin: auto;
  text-align: center; font-size: 14px; color: var(--ink-2);
}
.off3d[hidden] { display: none; }
.off3d strong { display: block; color: var(--ink); font-size: 16px; margin-bottom: 6px; }

.view-controls {
  position: absolute; right: 12px; bottom: 12px;
  display: flex; gap: 4px; padding: 4px;
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: 10px;
}
.btn-view { border-color: transparent; height: 36px; width: 36px; }
.workspace:not(.is-3d) [data-action='camera'] { display: none; }

.readout {
  position: absolute; left: 12px; bottom: 14px;
  padding: 4px 8px; border-radius: 6px;
  background: color-mix(in srgb, var(--sheet) 88%, transparent);
  font-family: var(--font-code); font-size: 11.5px; color: var(--ink-2);
  font-variant-numeric: tabular-nums; white-space: pre;
  pointer-events: none;
}

/* ---------- Pages ---------- */

.page-inner { max-width: 1160px; margin: 0 auto; padding: 28px 24px 64px; }
.page-head { margin-bottom: 24px; max-width: 72ch; }
.page-head h1 { margin: 0 0 6px; font-size: 28px; line-height: 1.2; font-weight: 600; letter-spacing: -0.02em; }
.lead { margin: 0; color: var(--ink-2); font-size: 15px; }
.page-head-rosette { display: flex; align-items: center; gap: 20px; max-width: none; }

.card-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 16px; }

.example-card, .challenge-card {
  display: flex; flex-direction: column;
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
.card-art { background: var(--paper); border-bottom: 3px solid var(--line); }
.example-card.mode-2d .card-art { border-bottom-color: var(--hue-przyklady); }
.example-card.mode-3d .card-art { border-bottom-color: var(--hue-violet); }
.challenge-card .card-art { border-bottom-color: var(--line-strong); }
.challenge-card.is-solved .card-art { border-bottom-color: var(--hue-zadania); }
.thumb { display: block; width: 100%; height: 168px; }
.card-body { display: flex; flex-direction: column; gap: 8px; padding: 12px 14px 14px; flex: 1; }
.card-body > .btn { align-self: flex-start; margin-top: auto; }
.card-plate { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.card-title { margin: 0; font-size: 17px; font-weight: 600; letter-spacing: -0.01em; }
.card-text { margin: 0; color: var(--ink-2); font-size: 14px; }
.card-code summary { cursor: pointer; font-size: 13px; color: var(--ink-2); width: fit-content; border-radius: 4px; }
.card-code .code-block { margin-top: 8px; max-height: 220px; }

.chip {
  display: inline-block; flex: none;
  font-size: 11px; font-weight: 600; letter-spacing: 0.02em;
  padding: 1px 8px; border-radius: 999px;
  background: var(--tint); color: var(--ink-2);
}
.chip-3d { background: color-mix(in srgb, var(--hue-violet) 16%, transparent); color: var(--hue-violet); }
:root:not([data-theme='dark']) .chip-3d { color: #5a3389; }

.challenge-status { margin: 0; display: flex; align-items: center; gap: 6px; font-size: 13px; color: var(--ink-3); font-weight: 500; }
.challenge-status.is-solved { color: var(--hue-zadania); }
:root:not([data-theme='dark']) .challenge-status.is-solved { color: #a3135a; }

.danger-zone {
  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  margin-top: 48px; padding-top: 16px; border-top: 1px solid var(--line);
  font-size: 13px; color: var(--ink-3);
}
.danger-zone p { margin: 0; }

/* Rosette: unsolved petals are outlines; solved ones are cut from coloured paper, with a punched notch. */
.rosette { flex: none; overflow: visible; }
.rosette .petal { fill: none; stroke: var(--line-strong); stroke-width: 3; }
.rosette .petal.is-solved { stroke: none; }
.rosette .notch { fill: var(--line-strong); }
.rosette .notch.is-solved { fill: var(--sheet); }
.rosette-core { fill: var(--ink); }
.progress-link .rosette .petal { stroke-width: 5; }

.code-block {
  margin: 0;
  padding: 12px 14px;
  overflow: auto;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: var(--radius-s);
  font-size: 13px;
  line-height: 20px;
  font-variant-ligatures: none;
}

/* Reference (Read mode inside the shell). */
.doc-layout { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 40px; align-items: start; }
.toc { position: sticky; top: 16px; font-size: 14px; }
.toc-title { font-size: 12px; font-weight: 600; color: var(--ink-3); margin: 0 0 8px; letter-spacing: 0.04em; text-transform: uppercase; }
.toc ol { list-style: none; margin: 0; padding: 0; display: grid; gap: 2px; }
.toc a { display: block; padding: 4px 10px; border-radius: 6px; color: var(--ink-2); text-decoration: none; }
.toc a:hover { background: var(--tint-pomoc); color: var(--ink); }
.doc-body { max-width: 74ch; }
.doc-section { padding-bottom: 12px; scroll-margin-top: 16px; }
.doc-section h2 { font-size: 22px; font-weight: 600; letter-spacing: -0.015em; margin: 36px 0 10px; padding-bottom: 6px; border-bottom: 3px solid var(--hue-pomoc); width: fit-content; }
.doc-section:first-child h2 { margin-top: 0; }
.doc-section h2:focus { outline: none; }
.doc-section p { margin: 0 0 12px; }
.cmd-doc { padding: 16px 0 18px; border-bottom: 1px solid var(--line); }
.cmd-doc h3 { margin: 0 0 8px; font-size: 17px; font-weight: 600; display: flex; align-items: center; gap: 10px; }
.cmd-facts { display: grid; grid-template-columns: max-content 1fr; gap: 2px 16px; margin: 0 0 8px; font-size: 14px; }
.cmd-facts dt { color: var(--ink-3); }
.cmd-facts dd { margin: 0; }
.cmd-facts code, .doc-section p code { font-size: 13px; background: var(--tint); padding: 0 4px; border-radius: 4px; }
.example { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; margin: 4px 0 14px; }
.example .code-block { width: 100%; }
.doc-table { border-collapse: collapse; width: 100%; font-size: 14px; margin: 4px 0 16px; }
.doc-table th, .doc-table td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }
.doc-table thead th { font-size: 12px; color: var(--ink-3); font-weight: 600; border-bottom: 2px solid var(--line-strong); }
.doc-table tbody th { font-weight: 500; }
.doc-table td { font-variant-numeric: tabular-nums; }

/* ---------- Responsive ---------- */

@media (max-width: 1100px) {
  .speed-label { display: none; }
  .doc-layout { grid-template-columns: 1fr; }
  .toc { position: static; }
  .toc ol { grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); }
}

@media (max-width: 820px) {
  :root { --bar-h: 52px; --code-size: 15px; --code-lh: 23px; }
  .topbar { gap: 8px; padding: 0 10px; }
  .brand-name { font-size: 16px; }
  /* Sections move to a bottom bar. */
  .nav {
    position: fixed; left: 0; right: 0; bottom: 0; z-index: 20;
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 0;
    background: var(--sheet);
    border-top: 1px solid var(--line);
    padding: 0 0 env(safe-area-inset-bottom);
  }
  .nav-link {
    flex-direction: column; gap: 2px; justify-content: center;
    height: 58px; padding: 0 4px; font-size: 11.5px;
    border-radius: 0;
  }
  .nav-link[aria-current='page'] { box-shadow: inset 0 4px 0 color-mix(in srgb, var(--section-on) 0%, transparent); }
  .app { height: auto; min-height: 100dvh; grid-template-rows: auto 1fr; padding-bottom: calc(58px + env(safe-area-inset-bottom)); }
  .main { overflow: visible; }
  .page-pracownia { height: auto; }
  .workspace { grid-template-columns: 1fr; height: auto; padding: 8px; gap: 8px; }
  .canvas-panel { order: -1; height: 44vh; min-height: 260px; }
  .editor { min-height: 46vh; }
  .toolbar { gap: 8px; padding: 8px; }
  .toolbar .btn { height: 44px; }
  .toolbar .btn[data-action='step'] .btn-label,
  .toolbar .btn[data-action='pause'] .btn-label,
  .toolbar .btn[data-action='reset'] .btn-label { display: none; }
  .toolbar .btn[data-action='step'], .toolbar .btn[data-action='pause'], .toolbar .btn[data-action='reset'] { width: 44px; padding: 0; }
  .speed { flex: 1; min-width: 150px; }
  .speed input { flex: 1; width: auto; }
  .toolbar-sep { display: none; }
  .filebar .btn { height: 40px; }
  .shortcuts { display: none; }
  .btn-view { width: 44px; height: 44px; }
  .page-inner { padding: 20px 14px 40px; }
  .page-head h1 { font-size: 24px; }
  .page-head-rosette { flex-direction: column; align-items: flex-start; gap: 12px; }
  .card-grid { grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
  .readout { bottom: 64px; }
}

@media (max-width: 380px) {
  .brand-name { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0ms !important; animation-duration: 0ms !important; }
}

@media (forced-colors: active) {
  .nav-link[aria-current='page'], .seg-btn[aria-pressed='true'] { outline: 2px solid CanvasText; }
  .error-flag { border: 1px solid CanvasText; }
}

